insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-1','wisdom',20,15,1,1,'Proverbs 15:1',1,'In a team meeting, a frustrated coworker loudly blames you for a missed deadline that was not entirely your fault. Everyone turns to see how you will react. Which response best reflects the teaching of Proverbs 15:1?',null,'["List every mistake the coworker has made this quarter to put them in their place", "Raise your voice to match theirs so everyone knows you will not be pushed around", "Answer calmly and gently, acknowledging the frustration and offering to work out the problem together", "Make a sarcastic remark that gets a laugh from the room at their expense"]'::jsonb,2,'Proverbs 15:1 teaches that "a soft answer turneth away wrath: but grievous words stir up anger." A gentle reply calms the situation, while harsh or cutting words make it worse.','The verse contrasts two kinds of answers and what each one does to anger.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'A soft answer turneth away wrath: but grievous words stir up anger.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-2','wisdom',49,4,25,25,'Ephesians 4:25',1,'A friend asks whether you liked the business plan they emailed you. You found serious problems in it, and a quick ''It''s great!'' would be much easier. What does Ephesians 4:25 counsel here?',null,'["Speak the truth to them, because you are members one of another", "Praise it to their face but tell others what you really think", "Say nothing and simply stop replying to their messages", "Tell them it is perfect so you avoid an awkward conversation"]'::jsonb,0,'Ephesians 4:25 says, "putting away lying, speak every man truth with his neighbour: for we are members one of another." Honest speech, not a convenient falsehood, is the instruction.','The verse gives a reason for honesty based on how believers are joined together.',null,null,'KJV',array['wisdom','Ephesians']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Wherefore putting away lying, speak every man truth with his neighbour: for we are members one of another.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-3','wisdom',20,11,13,13,'Proverbs 11:13',2,'A close colleague confides that they are struggling with a personal matter and asks you to keep it private. Later, over lunch, others start guessing about why the colleague seems distracted. According to Proverbs 11:13, what should you do?',null,'["Keep the matter to yourself, as a person of a faithful spirit would", "Reveal it only to the one coworker you trust most", "Share what you know so the group understands and can be sympathetic", "Drop hints without saying it outright, so you technically keep the secret"]'::jsonb,0,'Proverbs 11:13 contrasts the talebearer who "revealeth secrets" with one "of a faithful spirit" who "concealeth the matter." Keeping the confidence is the faithful choice.','The verse contrasts two kinds of people by what they do with secrets.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'A talebearer revealeth secrets: but he that is of a faithful spirit concealeth the matter.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-4','wisdom',40,5,37,37,'Matthew 5:37',2,'A client keeps asking whether you will really deliver on Friday. You are tempted to pile on dramatic assurances like ''I swear on everything I have'' to sound more convincing. Which approach best reflects Matthew 5:37?',null,'["Avoid giving any clear answer so you cannot be held to it", "Use the strongest guarantees you can think of so the client feels secure", "Promise Friday now and quietly plan to explain later if it slips", "Give a plain, honest ''yes'' or ''no'' and let your word stand on its own"]'::jsonb,3,'In Matthew 5:37 Jesus says, "let your communication be, Yea, yea; Nay, nay: for whatsoever is more than these cometh of evil." A simple, truthful answer is what He teaches.','Jesus describes how plain a trustworthy answer should be.',null,null,'KJV',array['wisdom','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But let your communication be, Yea, yea; Nay, nay: for whatsoever is more than these cometh of evil.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-5','wisdom',21,5,4,5,'Ecclesiastes 5:4-5',3,'Months ago, during a moving worship service, you made a sincere vow to God to give a specific gift to a ministry. Since then you keep putting it off, half-wondering whether a vow made in the moment really counts. What does Ecclesiastes 5:4-5 counsel?',null,'["Make a larger vow to make up for the unpaid one", "Keep postponing indefinitely, since God does not mind delays", "Fulfil what you vowed without delay, since it is better not to vow than to vow and not pay", "Consider the vow cancelled because it was made in an emotional moment"]'::jsonb,2,'Ecclesiastes 5:4-5 says, "When thou vowest a vow unto God, defer not to pay it... Better is it that thou shouldest not vow, than that thou shouldest vow and not pay." A vow should be kept, and kept promptly.','The passage speaks both about timing and about whether vowing at all is wise.',null,null,'KJV',array['wisdom','Ecclesiastes']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'When thou vowest a vow unto God, defer not to pay it; for he hath no pleasure in fools: pay that which thou hast vowed. Better is it that thou shouldest not vow, than that thou shouldest vow and not pay.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-6','wisdom',20,26,20,20,'Proverbs 26:20',3,'Two family members are feuding, and each one calls you to vent about the other and pass along what was said. You notice the conflict grows every time comments get relayed between them. Which response best reflects Proverbs 26:20?',null,'["Post about the feud online to get outside opinions", "Pass along each side''s remarks accurately so both stay informed", "Tell each person the other said worse things than they did, to speed up a showdown", "Refuse to carry stories between them, letting the quarrel lose its fuel"]'::jsonb,3,'Proverbs 26:20 says, "Where no wood is, there the fire goeth out: so where there is no talebearer, the strife ceaseth." Refusing to carry tales removes the fuel that keeps strife burning.','Think about what happens to a fire when no more wood is added.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Where no wood is, there the fire goeth out: so where there is no talebearer, the strife ceaseth.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-7','wisdom',19,15,4,4,'Psalms 15:4',4,'You agreed to sell your car to a neighbour at a set price and shook hands on it. Before the transfer, someone else offers you considerably more. Which response best reflects the character described in Psalms 15:4?',null,'["Invent a mechanical problem so you can back out gracefully", "Keep your word to the neighbour even though it now costs you", "Tell the neighbour they must match the new price or lose the deal", "Accept the higher offer, since nothing has been signed yet"]'::jsonb,1,'Psalms 15:4 describes the one who may dwell with the LORD as "He that sweareth to his own hurt, and changeth not." Such a person keeps a commitment even when it becomes costly.','The psalm praises someone whose promise holds even when keeping it hurts.',null,null,'KJV',array['wisdom','Psalms']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'In whose eyes a vile person is contemned; but he honoureth them that fear the LORD. He that sweareth to his own hurt, and changeth not.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-8','wisdom',20,18,17,17,'Proverbs 18:17',4,'A friend tells you a convincing story about how a mutual acquaintance cheated them, and you feel ready to share it and take sides. You have not heard from the other person at all. What does Proverbs 18:17 counsel here?',null,'["Confront the acquaintance publicly so the truth comes out quickly", "Recognize that the first account can seem right until the other side is examined, and withhold judgment", "Trust the first account fully, since a friend would not mislead you", "Warn others about the acquaintance right away to protect them"]'::jsonb,1,'Proverbs 18:17 says, "He that is first in his own cause seemeth just; but his neighbour cometh and searcheth him." A one-sided story can sound right until it is examined, so judgment and repetition should wait.','The verse notes how a case can appear before anyone questions it.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that is first in his own cause seemeth just; but his neighbour cometh and searcheth him.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-1','wisdom',20,15,1,1,'Proverbs 15:1',1,'A frustrated customer calls your desk and starts shouting about a billing mistake that wasn''t your fault. You feel your own temper rising. Which response best reflects the teaching of Proverbs 15:1?',null,'["Point out sharply that the mistake was someone else''s fault", "Raise your voice to match theirs so they know you won''t be pushed around", "Hang up and let them call back when they''ve cooled off", "Answer calmly and gently while you work toward a solution"]'::jsonb,3,'Proverbs 15:1 teaches that ''a soft answer turneth away wrath: but grievous words stir up anger,'' so a gentle reply calms the conflict.','This verse contrasts two kinds of answers and what each one does to anger.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'A soft answer turneth away wrath: but grievous words stir up anger.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-2','wisdom',49,4,26,26,'Ephesians 4:26',1,'You and your spouse had a heated disagreement about household chores after dinner. It''s getting late, and you''re tempted to go to bed still fuming and deal with it ''someday.'' What does Ephesians 4:26 counsel here?',null,'["Sleep in another room until the other person apologizes first", "Let the anger simmer for a few days so the other person learns a lesson", "Pretend nothing happened and never bring the issue up again", "Deal with your anger promptly rather than letting it carry on unresolved"]'::jsonb,3,'Ephesians 4:26 says, ''Be ye angry, and sin not: let not the sun go down upon your wrath,'' urging that anger be dealt with quickly rather than nursed.','The verse uses the end of the day as a time marker for anger.',null,null,'KJV',array['wisdom','Ephesians']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Be ye angry, and sin not: let not the sun go down upon your wrath:',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-3','wisdom',59,1,19,20,'James 1:19-20',2,'In a team meeting, a coworker criticizes a project you led. Before they finish explaining, you''re already forming a sharp rebuttal in your head. Which response best reflects James 1:19-20?',null,'["Respond with a forceful counterattack to show you''re confident", "Stay silent in the meeting, then vent angrily about them afterward", "Listen carefully to the full concern before answering, and keep your anger in check", "Interrupt immediately so the criticism doesn''t spread to others"]'::jsonb,2,'James 1:19-20 calls us to be ''swift to hear, slow to speak, slow to wrath,'' because ''the wrath of man worketh not the righteousness of God.''','James lists three things to be quick or slow about, in a specific order.',null,null,'KJV',array['wisdom','James']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath: For the wrath of man worketh not the righteousness of God.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-4','wisdom',40,5,23,24,'Matthew 5:23-24',2,'You''re heading to a worship service, ready to give an offering, when you remember that a friend is still hurt by a harsh comment you made last week. What does Jesus teach in Matthew 5:23-24?',null,'["Give a larger offering to make up for the harsh comment", "Wait for your friend to come to you, since they''re the one upset", "Focus only on your worship; relationships are a separate matter", "Go and seek to be reconciled with your friend as a priority"]'::jsonb,3,'In Matthew 5:23-24 Jesus says to leave the gift, ''first be reconciled to thy brother, and then come and offer thy gift.''','Jesus tells the worshipper what to do before offering at the altar.',null,null,'KJV',array['wisdom','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Therefore if thou bring thy gift to the altar, and there rememberest that thy brother hath ought against thee; Leave there thy gift before the altar, and go thy way; first be reconciled to thy brother, and then come and offer thy gift.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-5','wisdom',45,12,17,21,'Romans 12:17-21',3,'A neighbor spread false rumors about you in your community group. Later you learn that their family has fallen on hard times and is struggling to afford groceries. Which response best reflects Romans 12:17-21?',null,'["Quietly work to get them removed from the community group", "Share the news of their hardship in the group so they feel what you felt", "Refuse to take revenge and instead offer practical help, like food", "Ignore them entirely, since they brought this on themselves"]'::jsonb,2,'Romans 12:19-21 says ''avenge not yourselves'' and ''if thine enemy hunger, feed him,'' concluding, ''overcome evil with good.''','Paul describes what to do if an enemy is hungry or thirsty.',null,null,'KJV',array['wisdom','Romans']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Recompense to no man evil for evil. Provide things honest in the sight of all men. If it be possible, as much as lieth in you, live peaceably with all men. Dearly beloved, avenge not yourselves, but rather give place unto wrath: for it is written, Vengeance is mine; I will repay, saith the Lord. Therefore if thine enemy hunger, feed him; if he thirst, give him drink: for in so doing thou shalt heap coals of fire on his head. Be not overcome of evil, but overcome evil with good.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-6','wisdom',20,17,14,14,'Proverbs 17:14',3,'A minor disagreement with your sibling over splitting a restaurant bill is starting to escalate, and old grievances are creeping into the conversation. What does Proverbs 17:14 counsel here?',null,'["Drop the quarrel early, before it grows into something bigger", "Bring up every past grievance now so everything is finally aired", "Insist on settling the exact amount, no matter how long it takes", "Keep arguing but lower your voice so it seems more reasonable"]'::jsonb,0,'Proverbs 17:14 compares ''the beginning of strife'' to letting out water, so we should ''leave off contention, before it be meddled with.''','The verse compares a quarrel''s start to a small breach that releases water.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'The beginning of strife is as when one letteth out water: therefore leave off contention, before it be meddled with.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-7','wisdom',20,26,17,17,'Proverbs 26:17',4,'Walking through the office, you overhear two colleagues from another department arguing over a matter that has nothing to do with you. You''re tempted to jump in and tell them who''s right. Which response best reflects Proverbs 26:17?',null,'["Tell other coworkers about the argument so everyone''s aware", "Step in and take a side, since you clearly know who''s right", "Report both of them to their manager to show initiative", "Stay out of a quarrel that doesn''t belong to you"]'::jsonb,3,'Proverbs 26:17 says he ''that passeth by, and meddleth with strife belonging not to him, is like one that taketh a dog by the ears''—inviting needless trouble.','The proverb uses a vivid picture involving an animal to describe interfering.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that passeth by, and meddleth with strife belonging not to him, is like one that taketh a dog by the ears.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-8','wisdom',21,7,21,22,'Ecclesiastes 7:21-22',4,'A friend tells you that someone at work grumbled about you behind your back. You feel stung and start planning to confront them over every word. Which response best reflects Ecclesiastes 7:21-22?',null,'["Start grumbling about them too, so things are even", "Ask your friend to keep reporting anything else said about you", "Track down exactly what was said so you can respond point by point", "Don''t dwell on every remark, remembering you have spoken against others too"]'::jsonb,3,'Ecclesiastes 7:21-22 advises to ''take no heed unto all words that are spoken,'' because ''thine own heart knoweth that thou thyself likewise hast cursed others.''','The Preacher appeals to your own conscience about your past words.',null,null,'KJV',array['wisdom','Ecclesiastes']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Also take no heed unto all words that are spoken; lest thou hear thy servant curse thee: For oftentimes also thine own heart knoweth that thou thyself likewise hast cursed others.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-1','wisdom',20,16,18,18,'Proverbs 16:18',1,'You have just landed the biggest client in your company''s history, and you start telling coworkers that the team couldn''t function without you. You feel untouchable and stop double-checking your work. Which attitude best reflects the teaching of Proverbs 16:18?',null,'["Make sure everyone knows the win was yours before someone else claims it", "Recognize that a haughty spirit sets you up for a fall, and stay humble and careful", "Relax your standards, since past success guarantees future success", "Enjoy the moment, because success shows that your pride is justified"]'::jsonb,1,'Proverbs 16:18 warns that "Pride goeth before destruction, and an haughty spirit before a fall." Humility and care guard against the fall that pride invites.','This verse links an inner attitude to an outcome that soon follows it.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Pride goeth before destruction, and an haughty spirit before a fall.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-2','wisdom',20,12,15,15,'Proverbs 12:15',1,'You are planning to put most of your savings into a new business idea. A trusted friend with years of experience offers to review your plan, but you are already certain it will work. What does Proverbs 12:15 counsel here?',null,'["Decline the review, because confidence in your own judgment is enough", "Ask for advice only after the money is spent", "Listen to your friend''s counsel before deciding", "Go ahead quickly so doubts don''t slow you down"]'::jsonb,2,'Proverbs 12:15 says "The way of a fool is right in his own eyes: but he that hearkeneth unto counsel is wise." The wise person listens to advice instead of trusting only their own view.','Notice the contrast between someone sure of themselves and someone who listens.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'The way of a fool is right in his own eyes: but he that hearkeneth unto counsel is wise.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-3','wisdom',20,27,2,2,'Proverbs 27:2',2,'During your annual review, you are tempted to spend the meeting listing all your accomplishments and describing yourself as the best performer on the team. Your manager has already noticed much of your work. Which response best reflects the teaching of Proverbs 27:2?',null,'["Praise yourself boldly, since no one else will speak up for you", "Answer honestly and let others, rather than your own mouth, do the praising", "Post your achievements online so strangers will admire you", "Belittle your coworkers so your own work looks better"]'::jsonb,1,'Proverbs 27:2 teaches, "Let another man praise thee, and not thine own mouth." Praise is fitting when it comes from others, not from self-promotion.','The verse is about whose lips should speak your praise.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Let another man praise thee, and not thine own mouth; a stranger, and not thine own lips.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-4','wisdom',20,15,22,22,'Proverbs 15:22',2,'Your family is deciding whether to move across the country for a new job. You are inclined to make the decision alone so no one complicates things. What does Proverbs 15:22 counsel here?',null,'["Make the decision first and inform everyone afterward", "Decide quietly by yourself, because more voices only cause confusion", "Seek counsel from several wise, trusted people before deciding", "Ask only one person who is sure to agree with you"]'::jsonb,2,'Proverbs 15:22 says "Without counsel purposes are disappointed: but in the multitude of counsellors they are established." Plans are made firm by seeking many wise advisers.','The verse contrasts plans made with no input against plans made with many voices.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Without counsel purposes are disappointed: but in the multitude of counsellors they are established.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-5','wisdom',20,12,1,1,'Proverbs 12:1',3,'A colleague points out, privately and kindly, a serious error in a report you submitted. Your first instinct is to feel insulted and to avoid them. Which response best reflects the teaching of Proverbs 12:1?',null,'["Defend the report, since admitting fault damages your reputation", "Ignore the feedback and wait for the issue to be forgotten", "Welcome the correction as a way to learn, rather than resenting it", "Report the colleague for overstepping"]'::jsonb,2,'Proverbs 12:1 says "Whoso loveth instruction loveth knowledge: but he that hateth reproof is brutish." Loving correction is the path to knowledge, while hating it is called brutish.','The verse describes the person who hates reproof in very unflattering terms.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Whoso loveth instruction loveth knowledge: but he that hateth reproof is brutish.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-6','wisdom',45,12,16,16,'Romans 12:16',3,'At a neighborhood gathering, you notice yourself spending time only with the most successful and influential guests while ignoring a quiet newcomer who seems to be struggling. You also find yourself privately feeling smarter than most people there. What does Romans 12:16 counsel here?',null,'["Associate with those of low estate and do not be wise in your own conceits", "Focus on networking with people who can raise your status", "Trust your sense of superiority, since it reflects real wisdom", "Keep your distance from the newcomer so you don''t seem lowly"]'::jsonb,0,'Romans 12:16 says "Mind not high things, but condescend to men of low estate. Be not wise in your own conceits." Believers are to associate with the lowly and avoid thinking too highly of their own wisdom.','Paul addresses both who you spend time with and how you view your own wisdom.',null,null,'KJV',array['wisdom','Romans']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Be of the same mind one toward another. Mind not high things, but condescend to men of low estate. Be not wise in your own conceits.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-7','wisdom',21,4,13,13,'Ecclesiastes 4:13',4,'You have led your department for twenty years. A young new hire respectfully suggests a better process, and you are tempted to dismiss it simply because of your seniority and long experience. Which response best reflects the teaching of Ecclesiastes 4:13?',null,'["Stay teachable and open to admonition, regardless of your rank or age", "Wait until the new hire has earned enough years before listening", "Accept advice only from people who are older than you", "Dismiss the idea, since age and position always outweigh youth"]'::jsonb,0,'Ecclesiastes 4:13 says "Better is a poor and a wise child than an old and foolish king, who will no more be admonished." Position and age are worth less than wisdom when a person refuses correction.','The verse compares a young person and a ruler, and what makes the ruler foolish.',null,null,'KJV',array['wisdom','Ecclesiastes']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Better is a poor and a wise child than an old and foolish king, who will no more be admonished.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-8','wisdom',20,25,6,7,'Proverbs 25:6-7',4,'At a formal company dinner, you arrive early and are tempted to sit at the head table beside the CEO, even though no one has invited you there. What does Proverbs 25:6-7 counsel here?',null,'["Take the best seat early, since boldness gets you noticed", "Sit near the CEO and wait to see whether anyone objects", "Stand beside the important guests so you look important too", "Take a modest place and let your host invite you higher"]'::jsonb,3,'Proverbs 25:6-7 says "Put not forth thyself in the presence of the king," for it is better to be told "Come up hither" than to be put lower. Humbly waiting to be honored is better than being publicly demoted.','The passage compares two ways of being moved by your host, one honorable and one embarrassing.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Put not forth thyself in the presence of the king, and stand not in the place of great men: For better it is that it be said unto thee, Come up hither; than that thou shouldest be put lower in the presence of the prince whom thine eyes have seen.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-1','wisdom',20,15,1,1,'Proverbs 15:1',1,'Your sister calls, upset and accusing you of forgetting her birthday dinner. You feel unfairly blamed because the date was changed without telling you. Which response best reflects the teaching of Proverbs 15:1?',null,'["Hang up and refuse to discuss it until she apologises", "Raise your voice so she understands she is the one at fault", "Answer her gently and calmly, acknowledging her hurt before explaining the mix-up", "Point out sharply all the times she has forgotten your plans"]'::jsonb,2,'Proverbs 15:1 teaches that ''a soft answer turneth away wrath: but grievous words stir up anger,'' so a gentle reply is the wise path.','The verse contrasts two kinds of words and what each one does to anger.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'A soft answer turneth away wrath: but grievous words stir up anger.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-2','wisdom',49,4,26,26,'Ephesians 4:26',1,'You and your spouse had a heated disagreement about household chores this evening. It is getting late, and you are tempted to go to bed still fuming and deal with it ''some other time.'' What does Ephesians 4:26 counsel here?',null,'["Vent to friends over the next few days while staying angry at your spouse", "Say nothing, but quietly keep holding on to your resentment", "Deal with the anger without sinning and seek to settle it before the day ends", "Let the anger simmer for a few days so your spouse learns a lesson"]'::jsonb,2,'Ephesians 4:26 says, ''Be ye angry, and sin not: let not the sun go down upon your wrath.'' Anger is not to lead to sin, nor to be carried past the end of the day. It should be dealt with promptly rather than nursed.','Think about what the verse says regarding the end of the day.',null,null,'KJV',array['wisdom','Ephesians']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Be ye angry, and sin not: let not the sun go down upon your wrath:',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-3','wisdom',40,5,23,24,'Matthew 5:23-24',2,'You are about to take part in a worship service when you remember that a close friend is still hurt by a careless remark you made last week. You would rather just focus on the service and let things blow over. What does Matthew 5:23-24 counsel here?',null,'["Give a larger offering to make up for the remark", "Carry on with your offering, since worship matters more than the friendship", "First go and be reconciled with your friend, then come and offer your gift", "Wait for your friend to come to you, since they are the one upset"]'::jsonb,2,'In Matthew 5:23-24 Jesus says to ''leave there thy gift before the altar'' and ''first be reconciled to thy brother, and then come and offer thy gift.''','Notice the order of actions Jesus gives in the passage.',null,null,'KJV',array['wisdom','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Therefore if thou bring thy gift to the altar, and there rememberest that thy brother hath ought against thee; Leave there thy gift before the altar, and go thy way; first be reconciled to thy brother, and then come and offer thy gift.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-4','wisdom',45,12,15,15,'Romans 12:15',2,'A neighbour shares joyful news about her new grandchild, and later the same week another neighbour tells you his father has died. You are busy and tempted to keep your distance from both. Which response best reflects the teaching of Romans 12:15?',null,'["Stay neutral with both so you do not get too involved", "Remind the grieving neighbour that others have it worse", "Share in the first neighbour''s joy and grieve alongside the second", "Celebrate the good news but avoid the grieving neighbour to keep things positive"]'::jsonb,2,'Romans 12:15 instructs, ''Rejoice with them that do rejoice, and weep with them that weep,'' calling us to share both the joys and sorrows of others.','The verse names two emotions and asks you to share in each.',null,null,'KJV',array['wisdom','Romans']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Rejoice with them that do rejoice, and weep with them that weep.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-5','wisdom',20,17,9,9,'Proverbs 17:9',3,'A friend once wronged a mutual acquaintance, apologised, and made it right. Now, in a group chat, someone asks whether you know anything about that old falling-out. Which response best reflects the teaching of Proverbs 17:9?',null,'["Let the settled matter rest rather than retelling it", "Bring it up privately with each person in the group", "Hint at the details so people can guess what happened", "Recount the full story so everyone has the facts"]'::jsonb,0,'Proverbs 17:9 says, ''He that covereth a transgression seeketh love; but he that repeateth a matter separateth very friends,'' so repeating the old offence damages friendships.','The proverb contrasts two responses to an offence and what each does to friendship.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that covereth a transgression seeketh love; but he that repeateth a matter separateth very friends.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-6','wisdom',20,3,27,28,'Proverbs 3:27-28',3,'A neighbour asks to borrow a tool you own and are not using; you could hand it over right now. You feel like saying, ''Come back tomorrow,'' simply because it is inconvenient to dig it out. What does Proverbs 3:27-28 counsel here?',null,'["Promise to lend it but quietly hope he forgets", "Help him now, since it is in your power and you have it on hand", "Refuse, because lending to neighbours always causes trouble", "Tell him to come back another day, since your time is your own"]'::jsonb,1,'Proverbs 3:27-28 says, ''Withhold not good from them to whom it is due, when it is in the power of thine hand to do it,'' and not to say ''to morrow I will give; when thou hast it by thee.''','The passage warns against a particular kind of needless delay.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Withhold not good from them to whom it is due, when it is in the power of thine hand to do it. Say not unto thy neighbour, Go, and come again, and to morrow I will give; when thou hast it by thee.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-7','wisdom',20,27,10,10,'Proverbs 27:10',4,'A crisis hits your household, and your nearest relative lives across the country. A longtime family friend and a nearby neighbour both offer immediate help, but you feel you should only rely on blood relatives. Which response best reflects the teaching of Proverbs 27:10?',null,'["Value the faithful family friend and accept the near neighbour''s help", "Avoid involving anyone so you do not appear weak", "Wait for your distant brother to travel to you before accepting any help", "Decline the friend''s help, since only family should be trusted in hard times"]'::jsonb,0,'Proverbs 27:10 says, ''Thine own friend, and thy father''s friend, forsake not,'' and ''better is a neighbour that is near than a brother far off.''','The proverb compares the value of someone close at hand with a relative who is distant.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Thine own friend, and thy father’s friend, forsake not; neither go into thy brother’s house in the day of thy calamity: for better is a neighbour that is near than a brother far off.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-8','wisdom',20,27,14,14,'Proverbs 27:14',4,'You want to thank a friend for a big favour, so you plan to show up at his door at dawn and loudly praise him before he has even woken up. You feel the enthusiasm proves your gratitude. Which response best reflects the teaching of Proverbs 27:14?',null,'["Go ahead, because louder praise always shows greater love", "Repeat the early-morning praise several days in a row for emphasis", "Consider his circumstances, since ill-timed, loud blessing can be received as a curse", "Praise him loudly in public so everyone hears how grateful you are"]'::jsonb,2,'Proverbs 27:14 warns, ''He that blesseth his friend with a loud voice, rising early in the morning, it shall be counted a curse to him,'' so good intentions need wise timing.','The proverb is about how and when a blessing is given, not just whether it is given.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that blesseth his friend with a loud voice, rising early in the morning, it shall be counted a curse to him.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-1','wisdom',20,6,6,8,'Proverbs 6:6-8',1,'You have a flexible remote job and no manager checking in daily. It''s tempting to coast through the slow season and scramble later when the busy months arrive. Which response best reflects the teaching of Proverbs 6:6-8?',null,'["Work steadily and prepare during the slow season, without needing someone to oversee you", "Wait until the busy season starts and then decide how to cope", "Relax fully now, since nobody is watching and the busy season is far off", "Do only what is checked, because effort without a supervisor is wasted"]'::jsonb,0,'Proverbs 6:6-8 points the sluggard to the ant, which has "no guide, overseer, or ruler" yet "provideth her meat in the summer." Diligence and preparation should not depend on being supervised.','Think of a small creature that gathers its food in summer and harvest with no one telling it to.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Go to the ant, thou sluggard; consider her ways, and be wise: Which having no guide, overseer, or ruler, Provideth her meat in the summer, and gathereth her food in the harvest.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-2','wisdom',51,3,23,23,'Colossians 3:23',1,'You''ve been assigned a tedious task at work that your boss will probably never review closely. You''re tempted to do the bare minimum since no one will notice the difference. What does Colossians 3:23 counsel here?',null,'["Put in effort only when it will impress the people above you", "Do the bare minimum, since the effort will go unnoticed", "Do the work wholeheartedly, as though doing it for the Lord rather than for people", "Hand the task off to someone else, since unseen work doesn''t matter"]'::jsonb,2,'Colossians 3:23 says, "whatsoever ye do, do it heartily, as to the Lord, and not unto men." The quality of our work is not meant to depend on human recognition.','The verse names a different audience for your work than your boss.',null,null,'KJV',array['wisdom','Colossians']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And whatsoever ye do, do it heartily, as to the Lord, and not unto men;',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-3','wisdom',20,16,3,3,'Proverbs 16:3',2,'You''re launching a small side project and have been anxiously drafting plans late into the night, relying entirely on your own cleverness. A friend suggests you approach the venture differently. Which response best reflects the teaching of Proverbs 16:3?',null,'["Commit your work to the LORD, trusting Him to establish your plans", "Keep your plans to yourself, since sharing them invites failure", "Rely solely on your own strategy, since success depends only on you", "Abandon planning altogether and simply hope things work out"]'::jsonb,0,'Proverbs 16:3 teaches, "Commit thy works unto the LORD, and thy thoughts shall be established." Planning is paired with entrusting the work to God.','The verse begins with an instruction about what to do with your works.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Commit thy works unto the LORD, and thy thoughts shall be established.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-4','wisdom',42,14,28,30,'Luke 14:28-30',2,'You''re excited about a major home renovation and want to start knocking down walls this weekend. You haven''t yet worked out whether you have the money to finish it. Which response best reflects Jesus'' teaching in Luke 14:28-30?',null,'["Begin the demolition and figure out the budget once you see how it goes", "Avoid all large projects, since any plan might fail", "Sit down first and count the cost to see if you can finish what you start", "Start right away; enthusiasm will carry the project to completion"]'::jsonb,2,'In Luke 14:28-30 Jesus asks, "which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?" Otherwise onlookers would mock the one who "began to build, and was not able to finish." Jesus gives this picture to illustrate counting the cost of following him, and the principle is to count the cost before starting.','Jesus describes someone building a tower and what he does before laying the foundation.',null,null,'KJV',array['wisdom','Luke']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? Lest haply, after he hath laid the foundation, and is not able to finish it, all that behold it begin to mock him, Saying, This man began to build, and was not able to finish.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-5','wisdom',59,4,13,15,'James 4:13-15',3,'At dinner you confidently announce a five-year plan: move cities next spring, start a business, and be profitable within a year. A thoughtful friend gently questions how you''re speaking about the future. Which response best reflects the teaching of James 4:13-15?',null,'["Announce your plans boldly, since confidence guarantees success", "Keep your plans vague so no one can hold you to them", "Speak of your plans humbly, saying, \"If the Lord will, we shall live, and do this, or that\"", "Make no plans at all, since planning is forbidden"]'::jsonb,2,'James 4:13-15 reminds us that we "know not what shall be on the morrow" and that life is "a vapour," so we "ought to say, If the Lord will, we shall live, and do this, or that." James corrects presumption, not planning itself.','James compares life to something that appears briefly and vanishes, then gives a phrase to add to our plans.',null,null,'KJV',array['wisdom','James']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Go to now, ye that say, To day or to morrow we will go into such a city, and continue there a year, and buy and sell, and get gain: Whereas ye know not what shall be on the morrow. For what is your life? It is even a vapour, that appeareth for a little time, and then vanisheth away. For that ye ought to say, If the Lord will, we shall live, and do this, or that.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-6','wisdom',49,4,28,28,'Ephesians 4:28',3,'You''re doing well in a steady job, and you''ve begun to think of your earnings purely as a means to upgrade your own lifestyle. A mentor asks you to consider a further purpose for your work. According to Ephesians 4:28, what is one stated purpose of honest labour?',null,'["To prove you are more deserving than others", "To earn status and recognition among peers", "To accumulate enough that you never need to work again", "To have something to give to those in need"]'::jsonb,3,'Ephesians 4:28 urges honest work, "working with his hands the thing which is good, that he may have to give to him that needeth." Labour is meant to provide for generosity, not only for self.','The verse ends by naming someone who benefits from your work besides yourself.',null,null,'KJV',array['wisdom','Ephesians']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Let him that stole steal no more: but rather let him labour, working with his hands the thing which is good, that he may have to give to him that needeth.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-7','wisdom',21,11,4,4,'Ecclesiastes 11:4',4,'For two years you''ve delayed starting a project, waiting for the economy, your schedule and your confidence to all line up perfectly. Each month you find a new reason the conditions aren''t quite right. Which response best reflects the teaching of Ecclesiastes 11:4?',null,'["Keep waiting, because wise people act only when every condition is ideal", "Recognize that endlessly watching for perfect conditions means you will never sow or reap", "Let someone else decide for you so you are not responsible for the timing", "Give up on the project, since uncertain conditions prove it isn''t meant to be"]'::jsonb,1,'Ecclesiastes 11:4 warns, "He that observeth the wind shall not sow; and he that regardeth the clouds shall not reap." Waiting for perfect conditions leads to never acting at all.','The verse pictures a farmer who keeps watching the weather.',null,null,'KJV',array['wisdom','Ecclesiastes']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that observeth the wind shall not sow; and he that regardeth the clouds shall not reap.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-8','wisdom',20,21,5,5,'Proverbs 21:5',4,'A colleague urges you to rush into a quick-profit opportunity before thinking it through, promising fast results. You prefer to work out a careful, steady plan instead. What does Proverbs 21:5 contrast here?',null,'["It teaches that both haste and diligence lead to the same outcome", "It teaches that speed always beats careful thought in gaining wealth", "It teaches that thinking about plans is pointless, since outcomes are random", "It teaches that the diligent person''s thoughts lead to plenty, while hastiness leads to want"]'::jsonb,3,'Proverbs 21:5 says, "The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want." Careful, diligent planning is contrasted with haste that ends in lack.','The verse sets two kinds of people against each other: one careful, one in a hurry.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-1','wisdom',50,4,6,7,'Philippians 4:6-7',1,'A routine medical test has you waiting a week for results, and you keep lying awake running through every possible outcome. A friend asks how you are holding up. Which response best reflects the teaching of Philippians 4:6-7?',null,'["Make anxiety your focus, since worrying hard shows you take the situation seriously", "Keep it to yourself, since bringing small worries to God would show a lack of faith", "Bring your concerns to God in prayer with thanksgiving, trusting His peace to keep your heart and mind", "Distract yourself completely and avoid thinking or praying about it until the week is over"]'::jsonb,2,'Paul writes, ''Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God,'' promising that ''the peace of God'' will keep hearts and minds (Philippians 4:6-7).','Notice what Paul says to do ''in every thing'' instead of being anxious.',null,null,'KJV',array['wisdom','Philippians']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God. And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-2','wisdom',40,6,34,34,'Matthew 6:34',1,'Your manager hints that layoffs might come sometime next year. You start spending every evening imagining worst-case scenarios months ahead, and it is draining your joy today. What does Jesus counsel in Matthew 6:34?',null,'["Spend extra time each day rehearsing every possible future problem so nothing surprises you", "Assume the worst will certainly happen and prepare to be miserable", "Worry now so that tomorrow will feel lighter", "Take no anxious thought for tomorrow; each day has enough trouble of its own"]'::jsonb,3,'Jesus says, ''Take therefore no thought for the morrow... Sufficient unto the day is the evil thereof'' (Matthew 6:34), teaching His hearers not to borrow tomorrow''s anxieties.','Jesus says each day already carries enough of its own.',null,null,'KJV',array['wisdom','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-3','wisdom',20,3,5,6,'Proverbs 3:5-6',2,'You are weighing two job offers. You have made spreadsheets and pro-and-con lists, and you are tempted to rely entirely on your own analysis without ever bringing the decision to God. Which response best reflects the teaching of Proverbs 3:5-6?',null,'["Rely only on your own reasoning, since God is not concerned with everyday choices", "Trust God with part of your heart while keeping the final say for your own wisdom", "Acknowledge God only after the decision is made and has turned out well", "Trust the Lord with all your heart, not leaning on your own understanding, and acknowledge Him in the decision"]'::jsonb,3,'Proverbs 3:5-6 says, ''Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths.''','The verse speaks of ''all thine heart'' and ''all thy ways''.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-4','wisdom',59,1,2,4,'James 1:2-4',2,'A long, difficult season at home has tested you, and you are frustrated that it has not ended quickly. You find yourself asking whether hardship has any purpose at all. What does James 1:2-4 counsel here?',null,'["Count it joy, knowing the trying of your faith works patience that makes you mature", "Treat every trial as proof that God has abandoned you", "Pretend the difficulty is not real and refuse to acknowledge it", "Try to escape the trial as fast as possible by any means, since it has no value"]'::jsonb,0,'James writes, ''count it all joy when ye fall into divers temptations; Knowing this, that the trying of your faith worketh patience,'' and urges, ''let patience have her perfect work'' (James 1:2-4).','James connects testing with the growth of a particular virtue.',null,null,'KJV',array['wisdom','James']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'My brethren, count it all joy when ye fall into divers temptations; Knowing this, that the trying of your faith worketh patience. But let patience have her perfect work, that ye may be perfect and entire, wanting nothing.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-5','wisdom',19,37,7,8,'Psalms 37:7-8',3,'A coworker who cuts corners keeps getting praised and promoted while your honest work goes unnoticed. You feel bitterness rising and are tempted to bend the rules yourself. Which response best reflects the teaching of Psalms 37:7-8?',null,'["Rest in the Lord and wait patiently, refusing to fret or let anger push you toward doing evil", "Start cutting corners too, since that is clearly what gets rewarded", "Conclude that honesty is pointless and give up trying to do right", "Let your anger build until you can confront and expose him publicly"]'::jsonb,0,'The psalmist says, ''Rest in the LORD, and wait patiently for him: fret not thyself because of him who prospereth in his way... Cease from anger, and forsake wrath: fret not thyself in any wise to do evil'' (Psalms 37:7-8).','The psalm warns that fretting can lead somewhere worse.',null,null,'KJV',array['wisdom','Psalms']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Rest in the LORD, and wait patiently for him: fret not thyself because of him who prospereth in his way, because of the man who bringeth wicked devices to pass. Cease from anger, and forsake wrath: fret not thyself in any wise to do evil.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-6','wisdom',59,4,13,15,'James 4:13-15',3,'You confidently announce to friends that next year you will move cities, start a business, and be turning a profit within twelve months. One friend gently asks how you are holding those plans before God. Which response best reflects the teaching of James 4:13-15?',null,'["Make plans humbly, recognizing life is like a vapour and saying, ''If the Lord will, we shall live, and do this''", "Boast about the plans, since confidence guarantees success", "Never make any plans at all, since planning is forbidden", "Insist that your future is fully secure because you have worked out every detail"]'::jsonb,0,'James notes ''ye know not what shall be on the morrow'' and that life ''is even a vapour,'' so ''ye ought to say, If the Lord will, we shall live, and do this, or that'' (James 4:13-15).','James does not condemn planning itself, but a certain attitude toward it.',null,null,'KJV',array['wisdom','James']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Go to now, ye that say, To day or to morrow we will go into such a city, and continue there a year, and buy and sell, and get gain: Whereas ye know not what shall be on the morrow. For what is your life? It is even a vapour, that appeareth for a little time, and then vanisheth away. For that ye ought to say, If the Lord will, we shall live, and do this, or that.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-7','wisdom',21,11,4,6,'Ecclesiastes 11:4-6',4,'You have wanted to start a volunteer ministry for years, but you keep postponing because the timing never feels perfect and you fear it might not succeed. Which response best reflects the teaching of Ecclesiastes 11:4-6?',null,'["Wait until every condition is ideal and success is certain before beginning", "Work only in the morning and stop if results do not come quickly", "Give up the idea, since uncertainty means God is against it", "Stop waiting for perfect conditions and sow diligently, since you cannot know which effort will prosper"]'::jsonb,3,'Ecclesiastes says ''He that observeth the wind shall not sow,'' and counsels, ''In the morning sow thy seed, and in the evening withhold not thine hand: for thou knowest not whether shall prosper'' (Ecclesiastes 11:4-6).','Consider what happens to the farmer who keeps watching the weather.',null,null,'KJV',array['wisdom','Ecclesiastes']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that observeth the wind shall not sow; and he that regardeth the clouds shall not reap. As thou knowest not what is the way of the spirit, nor how the bones do grow in the womb of her that is with child: even so thou knowest not the works of God who maketh all. In the morning sow thy seed, and in the evening withhold not thine hand: for thou knowest not whether shall prosper, either this or that, or whether they both shall be alike good.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-8','wisdom',20,12,25,25,'Proverbs 12:25',4,'A close friend calls you, weighed down with anxiety about family pressures. You are unsure whether to say anything or simply change the subject. Which response best reflects the teaching of Proverbs 12:25?',null,'["Offer a good, encouraging word, because heaviness bows the heart but a good word makes it glad", "Tell them their feelings are foolish and they should simply stop being anxious", "Point out all the ways their situation could get even worse", "Avoid the topic entirely, since words make no difference to a heavy heart"]'::jsonb,0,'Proverbs 12:25 observes, ''Heaviness in the heart of man maketh it stoop: but a good word maketh it glad,'' showing the lifting power of kind, encouraging speech.','The proverb contrasts what bows the heart with what gladdens it.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Heaviness in the heart of man maketh it stoop: but a good word maketh it glad.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-2','wisdom',58,13,5,5,'Hebrews 13:5',1,'Scrolling social media, you see friends showing off vacations and new homes, and you start feeling dissatisfied with your modest apartment. You catch yourself planning purchases just to keep up. What does Hebrews 13:5 counsel here?',null,'["Contentment only comes once you own as much as your neighbors", "Keep up with others so you don''t feel left behind", "Be content with what you have, trusting that God will never leave you", "Envy is harmless as long as you don''t say it out loud"]'::jsonb,2,'Hebrews 13:5 urges, ''be content with such things as ye have,'' grounding contentment in God''s promise, ''I will never leave thee, nor forsake thee.''','The verse pairs a call to contentment with a promise of God''s presence.',null,null,'KJV',array['wisdom','Hebrews']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-3','wisdom',47,9,7,7,'2 Corinthians 9:7',2,'Your workplace is collecting donations for a coworker''s family after a house fire. You feel pressured by a manager watching who gives, and you''re tempted to give reluctantly just to look good. Which response best reflects the teaching of 2 Corinthians 9:7?',null,'["Give grudgingly, since the attitude doesn''t matter as long as money is given", "Give only because you were told you must", "Decide in your heart what to give and give it cheerfully, not grudgingly", "Give the largest amount so no one questions you"]'::jsonb,2,'2 Corinthians 9:7 says each should give ''as he purposeth in his heart... not grudgingly, or of necessity: for God loveth a cheerful giver.'' The heart behind the gift matters.','The verse focuses on the giver''s attitude more than the amount.',null,null,'KJV',array['wisdom','2 Corinthians']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for God loveth a cheerful giver.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-4','wisdom',40,6,19,21,'Matthew 6:19-21',2,'You''ve received a sizable bonus and are considering pouring all of it into luxury items. You realize your thoughts have been consumed by acquiring more possessions. Which response best reflects the teaching of Matthew 6:19-21?',null,'["Store up as many earthly goods as possible, since they last forever", "Lay up treasures in heaven rather than on earth, knowing your heart follows your treasure", "Your heart and your treasure are unrelated, so spend however you like", "Earthly possessions are safe from loss if you buy quality items"]'::jsonb,1,'Jesus teaches, ''lay up for yourselves treasures in heaven,'' because earthly goods decay or are stolen, and ''where your treasure is, there will your heart be also'' (Matthew 6:19-21).','Consider what moth, rust, and thieves can and cannot reach.',null,null,'KJV',array['wisdom','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Lay not up for yourselves treasures upon earth, where moth and rust doth corrupt, and where thieves break through and steal: But lay up for yourselves treasures in heaven, where neither moth nor rust doth corrupt, and where thieves do not break through nor steal: For where your treasure is, there will your heart be also.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-5','wisdom',20,3,27,28,'Proverbs 3:27-28',3,'A friend lent you money months ago and you now have enough in your account to repay it. You''re tempted to tell them, ''Check back next month,'' so you can enjoy a little extra cushion. Which response best reflects the teaching of Proverbs 3:27-28?',null,'["Repay them now, since you have it and it is in your power to do good", "Keep the money, since the loan was informal", "Delay repayment, since a friend should be patient indefinitely", "Repay only if they ask several more times"]'::jsonb,0,'Proverbs 3:27-28 says, ''Withhold not good from them to whom it is due,'' and warns against saying ''to morrow I will give; when thou hast it by thee.''','The passage specifically addresses putting someone off when you already have the means.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Withhold not good from them to whom it is due, when it is in the power of thine hand to do it. Say not unto thy neighbour, Go, and come again, and to morrow I will give; when thou hast it by thee.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-6','wisdom',50,4,11,12,'Philippians 4:11-12',3,'After a job loss, you''ve had to cut back sharply, and you feel your peace depends on your bank balance. You remember a time when money was plentiful and you felt no different inside. Which response best reflects the teaching of Philippians 4:11-12?',null,'["Learn to be content in every state, whether abased or abounding", "Contentment is only possible when you have plenty", "Paul teaches that circumstances must change before peace can come", "Contentment is only possible when you have very little"]'::jsonb,0,'Paul writes, ''I have learned, in whatsoever state I am, therewith to be content,'' knowing both ''how to be abased'' and ''how to abound'' (Philippians 4:11-12). Contentment is learned, not dependent on circumstances.','Paul says contentment is something he ''learned'' across opposite situations.',null,null,'KJV',array['wisdom','Philippians']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Not that I speak in respect of want: for I have learned, in whatsoever state I am, therewith to be content. I know both how to be abased, and I know how to abound: every where and in all things I am instructed both to be full and to be hungry, both to abound and to suffer need.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-7','wisdom',20,6,1,5,'Proverbs 6:1-5',4,'In a moment of enthusiasm, you rashly pledged to stand behind an acquaintance''s financial obligations, and now you realize you are bound by your own words. You''re tempted to put off dealing with it. What does Proverbs 6:1-5 counsel here?',null,'["Act urgently and humbly, going to the person to seek to be released", "Take on additional pledges for others to show good faith", "Avoid the person entirely and hope they forget your promise", "Relax and sleep on it for a few months; the situation will resolve itself"]'::jsonb,0,'Proverbs 6:1-5 says one who becomes ''surety for thy friend'' is ''snared with the words of thy mouth'' and should ''go, humble thyself,'' giving ''not sleep to thine eyes'' until delivered.','The passage uses images of a roe and a bird escaping a hunter.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'My son, if thou be surety for thy friend, if thou hast stricken thy hand with a stranger, Thou art snared with the words of thy mouth, thou art taken with the words of thy mouth. Do this now, my son, and deliver thyself, when thou art come into the hand of thy friend; go, humble thyself, and make sure thy friend. Give not sleep to thine eyes, nor slumber to thine eyelids. Deliver thyself as a roe from the hand of the hunter, and as a bird from the hand of the fowler.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-8','wisdom',20,30,8,9,'Proverbs 30:8-9',4,'You''re writing a personal prayer about your finances. Part of you wants to ask for great wealth, while another part fears hardship. Which request best reflects the prayer in Proverbs 30:8-9?',null,'["Ask for poverty, since lack never tempts anyone to wrongdoing", "Ask only for riches so that you never need to trust God", "Ask for great riches, since abundance never draws the heart from God", "Ask for neither poverty nor riches, but enough, lest fullness lead to denying God or want lead to stealing"]'::jsonb,3,'Proverbs 30:8-9 prays, ''give me neither poverty nor riches; feed me with food convenient for me,'' recognizing that being full may lead to denying God and being poor may lead to stealing.','The writer sees spiritual danger at both extremes.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Remove far from me vanity and lies: give me neither poverty nor riches; feed me with food convenient for me: Lest I be full, and deny thee, and say, Who is the LORD? or lest I be poor, and steal, and take the name of my God in vain.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-1','wisdom',40,5,44,44,'Matthew 5:44',1,'A coworker has openly mocked you in meetings and spread unkind rumors about you. A friend suggests you quietly return the favor or at least cut them off entirely. Which response best reflects the teaching of Matthew 5:44?',null,'["Ignore them completely until they apologize first", "Love them, bless them, do good to them and pray for them", "Return the treatment in kind so they learn a lesson", "Gather evidence and expose their faults to the whole team"]'::jsonb,1,'Jesus commands, "Love your enemies, bless them that curse you, do good to them that hate you, and pray for them" (Matthew 5:44). Retaliation, exposure or cold withdrawal run against this command.','Jesus lists four active things to do toward those who mistreat you.',null,null,'KJV',array['wisdom','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you;',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-2','wisdom',59,2,1,4,'James 2:1-4',1,'You help greet people at a community gathering. A well-dressed businessman and a visibly poor man in worn clothes arrive at the same time, and you feel tempted to give the businessman the best seat. What does James 2:1-4 counsel here?',null,'["Let the poor man in only if there are seats left over", "Show no partiality, welcoming both with equal honor", "Seat the businessman up front, since he may support the group", "Ask the poor man to stand at the back so others feel comfortable"]'::jsonb,1,'James warns against holding the faith "with respect of persons," rebuking those who honor the man with the gold ring while telling the poor man in vile raiment, "Stand thou there" (James 2:1-4).','James describes this exact seating situation and calls favoritism being partial.',null,null,'KJV',array['wisdom','James']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'My brethren, have not the faith of our Lord Jesus Christ, the Lord of glory, with respect of persons. For if there come unto your assembly a man with a gold ring, in goodly apparel, and there come in also a poor man in vile raiment; And ye have respect to him that weareth the gay clothing, and say unto him, Sit thou here in a good place; and say to the poor, Stand thou there, or sit here under my footstool: Are ye not then partial in yourselves, and are become judges of evil thoughts?',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-3','wisdom',20,19,17,17,'Proverbs 19:17',2,'A struggling neighbor asks for help buying groceries this week. You hesitate, thinking you''ll never get the money back. Which response best reflects the teaching of Proverbs 19:17?',null,'["Give with pity, trusting that kindness to the poor is lent to the LORD", "Tell the neighbor to rely on someone wealthier", "Help only if the neighbor signs a promise to repay", "Refuse, because money given away is simply lost"]'::jsonb,0,'Proverbs 19:17 says, "He that hath pity upon the poor lendeth unto the LORD; and that which he hath given will he pay him again." Giving to the needy is not lost but entrusted to God.','The verse describes generosity to the poor as a kind of loan, but not to the poor person.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that hath pity upon the poor lendeth unto the LORD; and that which he hath given will he pay him again.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-4','wisdom',20,25,21,22,'Proverbs 25:21-22',2,'A former friend who betrayed you is now going through hard times and is short on food. You learn they are hungry and could easily help. Which response best reflects the teaching of Proverbs 25:21-22?',null,'["Give them food and drink, trusting the LORD to reward you", "Help only after they publicly admit what they did", "Tell mutual friends so everyone knows they deserve it", "Wait and let them experience the consequences of their choices"]'::jsonb,0,'Proverbs 25:21-22 instructs, "If thine enemy be hungry, give him bread to eat; and if he be thirsty, give him water to drink," adding that "the LORD shall reward thee."','The passage names both hunger and thirst and tells you what to do about each.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'If thine enemy be hungry, give him bread to eat; and if he be thirsty, give him water to drink: For thou shalt heap coals of fire upon his head, and the LORD shall reward thee.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-5','wisdom',45,12,17,19,'Romans 12:17-19',3,'A relative cheated you in a family business deal and you are furious. You are considering ways to make them pay without anyone knowing it was you. Which response best reflects the teaching of Romans 12:17-19?',null,'["Take revenge only if you are certain they are guilty", "Refuse to repay evil for evil, seek peace where possible, and leave vengeance to God", "Cut off all contact and warn others to punish them socially", "Repay them quietly in a way that matches the harm they caused"]'::jsonb,1,'Paul writes, "Recompense to no man evil for evil... live peaceably with all men. Dearly beloved, avenge not yourselves... Vengeance is mine; I will repay, saith the Lord" (Romans 12:17-19).','The passage explains who is to repay wrongs.',null,null,'KJV',array['wisdom','Romans']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Recompense to no man evil for evil. Provide things honest in the sight of all men. If it be possible, as much as lieth in you, live peaceably with all men. Dearly beloved, avenge not yourselves, but rather give place unto wrath: for it is written, Vengeance is mine; I will repay, saith the Lord.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-6','wisdom',3,19,33,34,'Leviticus 19:33-34',3,'A family from another country moves into your neighborhood. Some neighbors are cool toward them and make jokes about their accent and customs. Which response best reflects the teaching of Leviticus 19:33-34?',null,'["Be polite but make clear they are guests, not equals", "Treat them as one born among you and love them as yourself", "Join the jokes lightly so you fit in with your neighbors", "Keep your distance until they adapt to local ways"]'::jsonb,1,'Leviticus 19:33-34 commands, "Ye shall not vex him. But the stranger that dwelleth with you shall be unto you as one born among you, and thou shalt love him as thyself."','The passage reminds Israel that they themselves were once strangers in Egypt.',null,null,'KJV',array['wisdom','Leviticus']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And if a stranger sojourn with thee in your land, ye shall not vex him. But the stranger that dwelleth with you shall be unto you as one born among you, and thou shalt love him as thyself; for ye were strangers in the land of Egypt: I am the LORD your God.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-7','wisdom',5,24,14,15,'Deuteronomy 24:14-15',4,'You hired a day laborer to do yard work. The job is done, but it would be more convenient to pay him at the end of the month with your other bills. Which response best reflects the teaching of Deuteronomy 24:14-15?',null,'["Pay at month''s end; any delay is fine as long as you pay eventually", "Reduce his pay since he is poor and will accept less", "Pay him the same day, before the sun goes down, since he depends on it", "Pay him only if he reminds you several times"]'::jsonb,2,'Deuteronomy 24:14-15 says not to oppress a poor hired servant: "At his day thou shalt give him his hire, neither shall the sun go down upon it; for he is poor, and setteth his heart upon it."','The passage gives a specific time limit tied to the day''s end.',null,null,'KJV',array['wisdom','Deuteronomy']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Thou shalt not oppress an hired servant that is poor and needy, whether he be of thy brethren, or of thy strangers that are in thy land within thy gates: At his day thou shalt give him his hire, neither shall the sun go down upon it; for he is poor, and setteth his heart upon it: lest he cry against thee unto the LORD, and it be sin unto thee.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-8','wisdom',20,24,17,18,'Proverbs 24:17-18',4,'A rival at work who treated you unfairly has just been publicly reprimanded and demoted. Colleagues invite you to celebrate their downfall over lunch. Which response best reflects the teaching of Proverbs 24:17-18?',null,'["Smile inwardly but avoid saying anything publicly", "Celebrate, since justice has finally been done", "Refuse to rejoice in their fall, guarding even your heart from gladness at it", "Remind everyone of what they did so the lesson sticks"]'::jsonb,2,'Proverbs 24:17-18 warns, "Rejoice not when thine enemy falleth, and let not thine heart be glad when he stumbleth," because it displeases the LORD. This covers inward gladness, not just outward celebration.','The verse addresses not only your words but also your heart.',null,null,'KJV',array['wisdom','Proverbs']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Rejoice not when thine enemy falleth, and let not thine heart be glad when he stumbleth: Lest the LORD see it, and it displease him, and he turn away his wrath from him.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-1','geography',42,2,51,51,'Luke 2:51',1,'After his visit to the temple at age twelve, the boy Jesus returned with Mary and Joseph to the town marked on the map and was subject unto them. Which town is it?',null,'["Nazareth", "Capernaum", "Bethlehem", "Jericho"]'::jsonb,0,'Luke 2:51 says Jesus went down with his parents and came to Nazareth, where he was subject unto them.','This Galilean hometown later gave Jesus a title: ''of ...''.',null,null,'KJV',array['geography','Nazareth','Luke']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he went down with them, and came to Nazareth, and was subject unto them: but his mother kept all these sayings in her heart.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 32.7021, "lon": 35.2977}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-2','geography',40,2,1,1,'Matthew 2:1',1,'Jesus was born in Bethlehem of Judaea in the days of Herod the king, and wise men from the east came to Jerusalem seeking him. Which marker shows Bethlehem?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Matthew 2:1 records that Jesus was born in Bethlehem of Judaea in the days of Herod the king, and that wise men came from the east to Jerusalem.','Look in the hill country of Judea, just south of Jerusalem.',null,null,'KJV',array['geography','Bethlehem','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now when Jesus was born in Bethlehem of Judaea in the days of Herod the king, behold, there came wise men from the east to Jerusalem,',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.504, "lon": 34.4644, "label": "A"}, {"lat": 31.7043, "lon": 35.2076, "label": "B"}, {"lat": 32.7021, "lon": 35.2977, "label": "C"}, {"lat": 32.8811, "lon": 35.575, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-3','geography',40,4,13,13,'Matthew 4:13',2,'Leaving Nazareth, Jesus came and dwelt in the town marked on the map, upon the sea coast in the borders of Zabulon and Nephthalim. Which town is it?',null,'["Nazareth", "Bethlehem", "Jericho", "Capernaum"]'::jsonb,3,'Matthew 4:13 says that, leaving Nazareth, Jesus came and dwelt in Capernaum, which is upon the sea coast.','This town sits on the northern shore of a freshwater lake.',null,null,'KJV',array['geography','Capernaum','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And leaving Nazareth, he came and dwelt in Capernaum, which is upon the sea coast, in the borders of Zabulon and Nephthalim:',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 32.8811, "lon": 35.575}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-4','geography',42,7,11,15,'Luke 7:11-15',3,'Jesus raised the only son of a widow as his funeral procession left the gate of a city called Nain. Which marker shows Nain?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'Luke 7:11-15 tells how Jesus went into a city called Nain and raised the dead son of a widow, delivering him to his mother.','This village lies in lower Galilee, not far from Nazareth and Mount Tabor.',null,null,'KJV',array['geography','Nain','Luke']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And it came to pass the day after, that he went into a city called Nain; and many of his disciples went with him, and much people. Now when he came nigh to the gate of the city, behold, there was a dead man carried out, the only son of his mother, and she was a widow: and much people of the city was with her. And when the Lord saw her, he had compassion on her, and said unto her, Weep not. And he came and touched the bier: and they that bare him stood still. And he said, Young man, I say unto thee, Arise. And he that was dead sat up, and began to speak. And he delivered him to his mother.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.6307, "lon": 35.3501, "label": "A"}, {"lat": 31.7767, "lon": 35.2342, "label": "B"}, {"lat": 31.8717, "lon": 35.4446, "label": "C"}, {"lat": 33.2708, "lon": 35.1961, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-5','geography',42,19,1,5,'Luke 19:1-5',2,'Jesus entered and passed through the city marked on the map, where a chief publican named Zacchaeus climbed a sycomore tree to see him. Which city is it?',null,'["Jericho", "Hebron", "Bethany", "Bethlehem"]'::jsonb,0,'Luke 19:1-5 records that Jesus passed through Jericho, where Zacchaeus climbed a sycomore tree and Jesus called him down.','This ancient city lies in the Jordan valley, near the north end of the Dead Sea.',null,null,'KJV',array['geography','Jericho','Luke']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Jesus entered and passed through Jericho. And, behold, there was a man named Zacchæus, which was the chief among the publicans, and he was rich. And he sought to see Jesus who he was; and could not for the press, because he was little of stature. And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way. And when Jesus came to the place, he looked up, and saw him, and said unto him, Zacchæus, make haste, and come down; for to day I must abide at thy house.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.8717, "lon": 35.4446}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-6','geography',43,11,1,1,'John 11:1',3,'Lazarus, whom Jesus raised from the dead, lived in Bethany, the town of Mary and her sister Martha. Which marker shows Bethany?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,2,'John 11:1 introduces Lazarus of Bethany, the town of Mary and her sister Martha.','This village lies just east of Jerusalem, beyond the Mount of Olives.',null,null,'KJV',array['geography','Bethany','John']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.504, "lon": 34.4644, "label": "A"}, {"lat": 32.5, "lon": 34.8917, "label": "B"}, {"lat": 31.7717, "lon": 35.2559, "label": "C"}, {"lat": 32.8811, "lon": 35.575, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-7','geography',40,4,18,18,'Matthew 4:18',1,'Walking beside the body of water marked on the map, Jesus saw Simon Peter and Andrew casting a net, for they were fishers. Which body of water is it?',null,'["Mount Tabor", "Salt Sea", "Sea of Galilee", "Jordan"]'::jsonb,2,'Matthew 4:18 says Jesus, walking by the sea of Galilee, saw Simon called Peter and Andrew casting a net into the sea.','This freshwater lake lies in the north, fed by the Jordan.',null,null,'KJV',array['geography','Sea of Galilee','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Jesus, walking by the sea of Galilee, saw two brethren, Simon called Peter, and Andrew his brother, casting a net into the sea: for they were fishers.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 32.8189, "lon": 35.59}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-8','geography',40,3,13,13,'Matthew 3:13',2,'Jesus came from Galilee to the Jordan to be baptized by John. Which marker shows the Jordan?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Matthew 3:13 records that Jesus came from Galilee to Jordan unto John, to be baptized of him.','Look for the river running north to south through the rift valley, far from the coast.',null,null,'KJV',array['geography','Jordan','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then cometh Jesus from Galilee to Jordan unto John, to be baptized of him.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.6725, "lon": 35.0233, "label": "A"}, {"lat": 31.7614, "lon": 35.5583, "label": "B"}, {"lat": 31.504, "lon": 34.4644, "label": "C"}, {"lat": 32.0545, "lon": 34.753, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-9','geography',40,26,36,36,'Matthew 26:36',3,'On the night he was betrayed, Jesus went with his disciples to the place marked on the map and told them to sit while he went to pray. Which place is it?',null,'["Nazareth", "Bethlehem", "Gethsemane", "Jericho"]'::jsonb,2,'Matthew 26:36 says Jesus came with his disciples unto a place called Gethsemane and told them to sit while he went to pray.','This garden lay just outside Jerusalem''s eastern wall.',null,null,'KJV',array['geography','Gethsemane','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then cometh Jesus with them unto a place called Gethsemane, and saith unto the disciples, Sit ye here, while I go and pray yonder.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.7794, "lon": 35.2394}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-10','geography',40,15,21,22,'Matthew 15:21-22',4,'Jesus departed into the coasts of Tyre and Sidon, where a woman of Canaan begged him to heal her daughter. Which marker shows Tyre?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,2,'Matthew 15:21-22 says Jesus departed into the coasts of Tyre and Sidon, and a woman of Canaan cried to him for her daughter.','This Phoenician port lies on the Mediterranean coast, north of Galilee.',null,null,'KJV',array['geography','Tyre','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then Jesus went thence, and departed into the coasts of Tyre and Sidon. And, behold, a woman of Canaan came out of the same coasts, and cried unto him, saying, Have mercy on me, O Lord, thou Son of David; my daughter is grievously vexed with a devil.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.7767, "lon": 35.2342, "label": "A"}, {"lat": 31.504, "lon": 34.4644, "label": "B"}, {"lat": 33.2708, "lon": 35.1961, "label": "C"}, {"lat": 32.8811, "lon": 35.575, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-1','geography',9,5,1,2,'1 Samuel 5:1-2',2,'After capturing the ark of God, the Philistines brought it into the house of their god Dagon in the city marked on the map. Which city is it?',null,'["Jericho", "Hebron", "Nazareth", "Ashdod"]'::jsonb,3,'The Philistines took the ark of God from Ebenezer to Ashdod and set it in the house of Dagon (1 Samuel 5:1-2).','It was one of the five Philistine lords'' cities on the coastal plain.',null,null,'KJV',array['geography','Ashdod','1 Samuel']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the Philistines took the ark of God, and brought it from Eben-ezer unto Ashdod. When the Philistines took the ark of God, they brought it into the house of Dagon, and set it by Dagon.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.7572, "lon": 34.6578}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-2','geography',7,16,1,3,'Judges 16:1-3',1,'Samson rose at midnight and carried off the doors of the city gate of Gaza. Which marker shows Gaza?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Samson went to Gaza, then rose at midnight and took the doors of the city gate up to a hill before Hebron (Judges 16:1-3).','Look for the southernmost Philistine city on the coast.',null,null,'KJV',array['geography','Gaza','Judges']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then went Samson to Gaza, and saw there an harlot, and went in unto her. And it was told the Gazites, saying, Samson is come hither. And they compassed him in, and laid wait for him all night in the gate of the city, and were quiet all the night, saying, In the morning, when it is day, we shall kill him. And Samson lay till midnight, and arose at midnight, and took the doors of the gate of the city, and the two posts, and went away with them, bar and all, and put them upon his shoulders, and carried them up to the top of an hill that is before Hebron.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.5853, "lon": 35.1844, "label": "A"}, {"lat": 31.504, "lon": 34.4644, "label": "B"}, {"lat": 33.249, "lon": 35.652, "label": "C"}, {"lat": 31.8717, "lon": 35.4446, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-3','geography',7,14,19,19,'Judges 14:19',3,'Samson went down to Ashkelon and slew thirty men to pay the wager over his riddle. Which marker shows Ashkelon?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,2,'The Spirit of the LORD came upon Samson, and he went down to Ashkelon and slew thirty men, giving their garments to those who expounded the riddle (Judges 14:19).','This Philistine city lay on the Mediterranean shore.',null,null,'KJV',array['geography','Ashkelon','Judges']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the Spirit of the LORD came upon him, and he went down to Ashkelon, and slew thirty men of them, and took their spoil, and gave change of garments unto them which expounded the riddle. And his anger was kindled, and he went up to his father’s house.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.2761, "lon": 35.195, "label": "A"}, {"lat": 31.5251, "lon": 35.1022, "label": "B"}, {"lat": 31.6639, "lon": 34.5458, "label": "C"}, {"lat": 32.8811, "lon": 35.575, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-4','geography',9,5,10,10,'1 Samuel 5:10',3,'When the ark of God was sent to the city marked on the map, its people cried out that it had been brought to slay them. Which city is it?',null,'["Shechem", "Bethel", "Ekron", "Hazor"]'::jsonb,2,'The Philistines sent the ark of God to Ekron, and the Ekronites cried out in fear (1 Samuel 5:10).','After Ashdod and Gath, the ark was sent on to this city, whose people feared it would kill them.',null,null,'KJV',array['geography','Ekron','1 Samuel']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Therefore they sent the ark of God to Ekron. And it came to pass, as the ark of God came to Ekron, that the Ekronites cried out, saying, They have brought about the ark of the God of Israel to us, to slay us and our people.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.7775, "lon": 34.8519}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-5','geography',11,5,1,1,'1 Kings 5:1',1,'The king of the city marked on the map sent his servants unto Solomon when he heard Solomon had been anointed king, for this king was ever a lover of David. Which city is it?',null,'["Tyre", "Beersheba", "Gaza", "Joppa"]'::jsonb,0,'Hiram king of Tyre sent his servants unto Solomon, having heard he was anointed king in his father''s room, for Hiram was ever a lover of David (1 Kings 5:1).','A famous Phoenician seaport north of Israel.',null,null,'KJV',array['geography','Tyre','1 Kings']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Hiram king of Tyre sent his servants unto Solomon; for he had heard that they had anointed him king in the room of his father: for Hiram was ever a lover of David.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 33.2708, "lon": 35.1961}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-6','geography',11,17,9,10,'1 Kings 17:9-10',2,'God sent Elijah to Zarephath, where a widow fed him during the drought. Which marker shows Zarephath?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'The LORD told Elijah to go to Zarephath, which belonged to Zidon, where a widow woman would sustain him (1 Kings 17:9-10).','The text says this town belonged to Zidon, on the Phoenician coast.',null,null,'KJV',array['geography','Zarephath','1 Kings']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Arise, get thee to Zarephath, which belongeth to Zidon, and dwell there: behold, I have commanded a widow woman there to sustain thee. So he arose and went to Zarephath. And when he came to the gate of the city, behold, the widow woman was there gathering of sticks: and he called to her, and said, Fetch me, I pray thee, a little water in a vessel, that I may drink.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 33.4642, "lon": 35.2951, "label": "A"}, {"lat": 31.8717, "lon": 35.4446, "label": "B"}, {"lat": 31.2447, "lon": 34.8408, "label": "C"}, {"lat": 31.7767, "lon": 35.2342, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-7','geography',32,1,3,3,'Jonah 1:3',1,'Fleeing from the presence of the LORD, Jonah went down to Joppa and found a ship going to Tarshish. Which marker shows Joppa?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'Jonah went down to Joppa and found a ship going to Tarshish (Jonah 1:3).','He needed a seaport on the Mediterranean.',null,null,'KJV',array['geography','Joppa','Jonah']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But Jonah rose up to flee unto Tarshish from the presence of the LORD, and went down to Joppa; and he found a ship going to Tarshish: so he paid the fare thereof, and went down into it, to go with them unto Tarshish from the presence of the LORD.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.0545, "lon": 34.753, "label": "A"}, {"lat": 31.8717, "lon": 35.4446, "label": "B"}, {"lat": 32.8811, "lon": 35.575, "label": "C"}, {"lat": 31.5251, "lon": 35.1022, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-8','geography',9,31,1,2,'1 Samuel 31:1-2',2,'Fleeing the Philistines, the men of Israel fell down slain on the mountain marked on the map, and the Philistines slew Saul''s sons Jonathan, Abinadab, and Malchi-shua. Which mountain is it?',null,'["Mount Gilboa", "Mount Hermon", "Mount Carmel", "Mount Tabor"]'::jsonb,0,'The men of Israel fled from the Philistines and fell down slain in mount Gilboa, and the Philistines slew Saul''s sons (1 Samuel 31:1-2).','Its ridge runs along the southeastern edge of the Jezreel valley, toward Beth-shan.',null,null,'KJV',array['geography','Mount Gilboa','1 Samuel']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now the Philistines fought against Israel: and the men of Israel fled from before the Philistines, and fell down slain in mount Gilboa. And the Philistines followed hard upon Saul and upon his sons; and the Philistines slew Jonathan, and Abinadab, and Malchi-shua, Saul’s sons.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 32.4339, "lon": 35.4144}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-9','geography',6,10,12,12,'Joshua 10:12',3,'In the battle to defend Gibeon, Joshua said, ''Sun, stand thou still upon Gibeon.'' Which marker shows Gibeon?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,2,'Joshua spoke to the LORD and said, ''Sun, stand thou still upon Gibeon; and thou, Moon, in the valley of Ajalon'' (Joshua 10:12).','This town lay in the hill country of Benjamin, just north of Jerusalem.',null,null,'KJV',array['geography','Gibeon','Joshua']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then spake Joshua to the LORD in the day when the LORD delivered up the Amorites before the children of Israel, and he said in the sight of Israel, Sun, stand thou still upon Gibeon; and thou, Moon, in the valley of Ajalon.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.2447, "lon": 34.8408, "label": "A"}, {"lat": 32.5853, "lon": 35.1844, "label": "B"}, {"lat": 31.8475, "lon": 35.1834, "label": "C"}, {"lat": 31.5653, "lon": 34.8492, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-10','geography',12,18,13,14,'2 Kings 18:13-14',4,'Hezekiah sent a message of submission to the king of Assyria while he was encamped at the city marked on the map. Which city is it?',null,'["Lachish", "Beth-shan", "Shiloh", "Dan"]'::jsonb,0,'After Sennacherib took the fenced cities of Judah, Hezekiah sent to the king of Assyria to Lachish, saying, ''I have offended'' (2 Kings 18:13-14).','A major fortified city in the lowlands of Judah, southwest of Jerusalem.',null,null,'KJV',array['geography','Lachish','2 Kings']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now in the fourteenth year of king Hezekiah did Sennacherib king of Assyria come up against all the fenced cities of Judah, and took them. And Hezekiah king of Judah sent to the king of Assyria to Lachish, saying, I have offended; return from me: that which thou puttest on me will I bear. And the king of Assyria appointed unto Hezekiah king of Judah three hundred talents of silver and thirty talents of gold.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.5653, "lon": 34.8492}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-1','geography',1,28,12,19,'Genesis 28:12-19',1,'Jacob dreamed of a ladder reaching to heaven and named the place where he slept. Which town is marked on the map?',null,'["Hebron", "Bethel", "Shechem", "Beersheba"]'::jsonb,1,'After dreaming of a ladder set up on the earth that reached to heaven, Jacob called the name of that place Bethel, formerly Luz (Genesis 28:12-19).','The name means ''house of God''.',null,null,'KJV',array['geography','Bethel','Genesis']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of God ascending and descending on it. And, behold, the LORD stood above it, and said, I am the LORD God of Abraham thy father, and the God of Isaac: the land whereon thou liest, to thee will I give it, and to thy seed; And thy seed shall be as the dust of the earth, and thou shalt spread abroad to the west, and to the east, and to the north, and to the south: and in thee and in thy seed shall all the families of the earth be blessed. And, behold, I am with thee, and will keep thee in all places whither thou goest, and will bring thee again into this land; for I will not leave …',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.9228, "lon": 35.2414}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-2','geography',6,6,2,5,'Joshua 6:2-5',1,'After Israel crossed the Jordan, the LORD told Joshua that this city''s wall would fall down flat when the people shouted. Which city is marked on the map?',null,'["Jericho", "Bethel", "Gibeon", "Shiloh"]'::jsonb,0,'The LORD said, ''I have given into thine hand Jericho,'' and promised that after the trumpets and the shout the wall of the city would fall down flat (Joshua 6:2-5).','Israel marched around this city once a day for six days.',null,null,'KJV',array['geography','Jericho','Joshua']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the LORD said unto Joshua, See, I have given into thine hand Jericho, and the king thereof, and the mighty men of valour. And ye shall compass the city, all ye men of war, and go round about the city once. Thus shalt thou do six days. And seven priests shall bear before the ark seven trumpets of rams’ horns: and the seventh day ye shall compass the city seven times, and the priests shall blow with the trumpets. And it shall come to pass, that when they make a long blast with the ram’s horn, and when ye hear the sound of the trumpet, all the people shall shout with a great shout; and the wall of the city shall fall down flat, and the people shall ascend up every man straight before him.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.8717, "lon": 35.4446}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-3','geography',7,16,1,3,'Judges 16:1-3',1,'Samson carried off the doors of the city gate of Gaza. Which marker shows Gaza?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'Samson went to Gaza, and at midnight he took the doors of the gate of the city and carried them away (Judges 16:1-3).','Look for a Philistine city near the southern coast.',null,null,'KJV',array['geography','Gaza','Judges']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then went Samson to Gaza, and saw there an harlot, and went in unto her. And it was told the Gazites, saying, Samson is come hither. And they compassed him in, and laid wait for him all night in the gate of the city, and were quiet all the night, saying, In the morning, when it is day, we shall kill him. And Samson lay till midnight, and arose at midnight, and took the doors of the gate of the city, and the two posts, and went away with them, bar and all, and put them upon his shoulders, and carried them up to the top of an hill that is before Hebron.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.504, "lon": 34.4644, "label": "A"}, {"lat": 33.249, "lon": 35.652, "label": "B"}, {"lat": 31.8717, "lon": 35.4446, "label": "C"}, {"lat": 32.5036, "lon": 35.5031, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-4','geography',1,11,31,31,'Genesis 11:31',2,'Terah left Ur with Abram, Sarai and Lot, heading for Canaan, but they stopped and dwelt in the city marked on the map. Which city is it?',null,'["Babylon", "Damascus", "Nineveh", "Haran"]'::jsonb,3,'Terah and his family went forth from Ur of the Chaldees to go into Canaan, but they came unto Haran and dwelt there (Genesis 11:31).','This city lies in the north, along the route from Mesopotamia toward Canaan.',null,null,'KJV',array['geography','Haran','Genesis']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Terah took Abram his son, and Lot the son of Haran his son’s son, and Sarai his daughter in law, his son Abram’s wife; and they went forth with them from Ur of the Chaldees, to go into the land of Canaan; and they came unto Haran, and dwelt there.',null,'{"map": {"view": "east", "kind": "identify", "markers": [{"lat": 36.8644, "lon": 39.0328}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-5','geography',1,15,7,7,'Genesis 15:7',2,'The LORD reminded Abram that He had brought him out of Ur of the Chaldees. Which marker shows Ur?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,2,'The LORD said to Abram, ''I am the LORD that brought thee out of Ur of the Chaldees, to give thee this land'' (Genesis 15:7).','Look in southern Mesopotamia, near the lower Euphrates.',null,null,'KJV',array['geography','Ur','Genesis']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he said unto him, I am the LORD that brought thee out of Ur of the Chaldees, to give thee this land to inherit it.',null,'{"map": {"view": "east", "kind": "locate", "markers": [{"lat": 32.1892, "lon": 48.2578, "label": "A"}, {"lat": 29.8488, "lon": 31.253, "label": "B"}, {"lat": 30.9622, "lon": 46.1044, "label": "C"}, {"lat": 36.8644, "lon": 39.0328, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-6','geography',1,23,19,19,'Genesis 23:19',2,'Abraham buried Sarah in the cave of Machpelah, near the city of Hebron. Which marker shows Hebron?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Abraham buried Sarah in the cave of the field of Machpelah before Mamre, ''the same is Hebron in the land of Canaan'' (Genesis 23:19).','It lies in the hill country of Judah, south of Jerusalem.',null,null,'KJV',array['geography','Hebron','Genesis']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And after this, Abraham buried Sarah his wife in the cave of the field of Machpelah before Mamre: the same is Hebron in the land of Canaan.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.2136, "lon": 35.2819, "label": "A"}, {"lat": 31.5251, "lon": 35.1022, "label": "B"}, {"lat": 33.249, "lon": 35.652, "label": "C"}, {"lat": 31.2447, "lon": 34.8408, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-7','geography',1,21,31,31,'Genesis 21:31',3,'Abraham and Abimelech made a covenant at a well, and Abraham named the place after the oath they swore. Which place is marked on the map?',null,'["Hebron", "Kadesh-barnea", "Gaza", "Beersheba"]'::jsonb,3,'Abraham called that place Beersheba ''because there they sware both of them'' (Genesis 21:31).','Its name is linked to a well and an oath, in the Negev.',null,null,'KJV',array['geography','Beersheba','Genesis']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Wherefore he called that place Beer-sheba; because there they sware both of them.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.2447, "lon": 34.8408}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-8','geography',1,33,18,18,'Genesis 33:18',3,'Returning from Padanaram, Jacob came to Shalem, a city of Shechem, and pitched his tent before it. Which marker shows Shechem?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'Jacob came to Shalem, a city of Shechem in the land of Canaan, when he came from Padanaram, and pitched his tent before the city (Genesis 33:18).','Look in the central hill country, north of Bethel.',null,null,'KJV',array['geography','Shechem','Genesis']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Jacob came to Shalem, a city of Shechem, which is in the land of Canaan, when he came from Padan-aram; and pitched his tent before the city.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.2136, "lon": 35.2819, "label": "A"}, {"lat": 32.5853, "lon": 35.1844, "label": "B"}, {"lat": 31.7767, "lon": 35.2342, "label": "C"}, {"lat": 33.249, "lon": 35.652, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-9','geography',7,4,6,6,'Judges 4:6',3,'Deborah told Barak to gather ten thousand men and draw toward the mountain marked on the map. Which mountain is it?',null,'["Mount Gilboa", "Mount Carmel", "Mount Hermon", "Mount Tabor"]'::jsonb,3,'Deborah called Barak and told him, ''Go and draw toward mount Tabor, and take with thee ten thousand men'' (Judges 4:6).','This rounded mountain rises from the plain in lower Galilee.',null,null,'KJV',array['geography','Mount Tabor','Judges']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And she sent and called Barak the son of Abinoam out of Kedesh-naphtali, and said unto him, Hath not the LORD God of Israel commanded, saying, Go and draw toward mount Tabor, and take with thee ten thousand men of the children of Naphtali and of the children of Zebulun?',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 32.6863, "lon": 35.3929}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-10','geography',4,32,8,8,'Numbers 32:8',4,'Moses recalled that the spies were sent from Kadesh-barnea to see the land. Which marker shows Kadesh-barnea?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Moses reminded the tribes that their fathers did the same ''when I sent them from Kadeshbarnea to see the land'' (Numbers 32:8).','Look in the wilderness far to the south, beyond the Negev.',null,null,'KJV',array['geography','Kadesh-barnea','Numbers']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Thus did your fathers, when I sent them from Kadesh-barnea to see the land.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.504, "lon": 34.4644, "label": "A"}, {"lat": 30.6483, "lon": 34.4222, "label": "B"}, {"lat": 31.5251, "lon": 35.1022, "label": "C"}, {"lat": 31.8717, "lon": 35.4446, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gz-1','geography',44,9,3,6,'Acts 9:3-6',1,'Saul was approaching the city marked on the map when a light from heaven shone around him. Which city is it?',null,'["Damascus", "Corinth", "Ephesus", "Tarsus"]'::jsonb,0,'Acts 9:3 says that as Saul journeyed, he came near Damascus, and suddenly a light from heaven shone round about him.','Saul was traveling there with letters to arrest believers, and it was an ancient city of Syria.',null,null,'KJV',array['geography','Damascus','Acts']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven: And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me? And he said, Who art thou, Lord? And the Lord said, I am Jesus whom thou persecutest: it is hard for thee to kick against the pricks. And he trembling and astonished said, Lord, what wilt thou have me to do? And the Lord said unto him, Arise, and go into the city, and it shall be told thee what thou must do.',null,'{"map": {"view": "med", "kind": "identify", "markers": [{"lat": 33.5111, "lon": 36.3064}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gz-2','geography',44,28,14,16,'Acts 28:14-16',1,'After his voyage and shipwreck, Paul arrived as a prisoner in Rome, where he was allowed to dwell by himself with a soldier guarding him. Which marker shows Rome?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Acts 28:16 records that when they came to Rome, Paul was suffered to dwell by himself with a soldier that kept him.','Look for the imperial capital on the Italian peninsula.',null,null,'KJV',array['geography','Rome','Acts']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Where we found brethren, and were desired to tarry with them seven days: and so we went toward Rome. And from thence, when the brethren heard of us, they came to meet us as far as Appii forum, and The three taverns: whom when Paul saw, he thanked God, and took courage. And when we came to Rome, the centurion delivered the prisoners to the captain of the guard: but Paul was suffered to dwell by himself with a soldier that kept him.',null,'{"map": {"view": "med", "kind": "locate", "markers": [{"lat": 32.8209, "lon": 21.8512, "label": "A"}, {"lat": 41.8922, "lon": 12.4852, "label": "B"}, {"lat": 40.6378, "lon": 22.9458, "label": "C"}, {"lat": 33.5111, "lon": 36.3064, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gz-3','geography',44,17,22,23,'Acts 17:22-23',1,'Paul stood in the midst of Mars'' hill and addressed the men of the city marked on the map about an altar to the unknown god. Which city is it?',null,'["Philippi", "Ephesus", "Athens", "Corinth"]'::jsonb,2,'In Acts 17:22-23 Paul stood on Mars'' hill and said, ''Ye men of Athens,'' referring to their altar inscribed TO THE UNKNOWN GOD.','This Greek city was famous for its philosophers.',null,null,'KJV',array['geography','Athens','Acts']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then Paul stood in the midst of Mars’ hill, and said, Ye men of Athens, I perceive that in all things ye are too superstitious. For as I passed by, and beheld your devotions, I found an altar with this inscription, TO THE UNKNOWN GOD. Whom therefore ye ignorantly worship, him declare I unto you.',null,'{"map": {"view": "med", "kind": "identify", "markers": [{"lat": 37.9719, "lon": 23.7267}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gz-4','geography',44,19,1,2,'Acts 19:1-2',2,'While Apollos was at Corinth, Paul passed through the upper coasts and came to Ephesus, where he found certain disciples. Which marker shows Ephesus?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,2,'Acts 19:1 says that while Apollos was at Corinth, Paul came to Ephesus and found certain disciples there.','It was a major port on the western coast of Asia Minor.',null,null,'KJV',array['geography','Ephesus','Acts']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And it came to pass, that, while Apollos was at Corinth, Paul having passed through the upper coasts came to Ephesus: and finding certain disciples, He said unto them, Have ye received the Holy Ghost since ye believed? And they said unto him, We have not so much as heard whether there be any Holy Ghost.',null,'{"map": {"view": "med", "kind": "locate", "markers": [{"lat": 32.8209, "lon": 21.8512, "label": "A"}, {"lat": 36.913, "lon": 34.8921, "label": "B"}, {"lat": 37.9391, "lon": 27.3407, "label": "C"}, {"lat": 37.9058, "lon": 22.8787, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gz-5','geography',44,16,12,14,'Acts 16:12-14',2,'Paul came to the city marked on the map, the chief city of that part of Macedonia, where Lydia, a seller of purple, heard him by the riverside. Which city is it?',null,'["Berea", "Philippi", "Troas", "Thessalonica"]'::jsonb,1,'Acts 16:12-14 describes Philippi as the chief city of that part of Macedonia and a colony, where Lydia heard Paul by a river side.','It was a Roman colony and the first stop inland after Paul crossed from Asia into Macedonia.',null,null,'KJV',array['geography','Philippi','Acts']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And from thence to Philippi, which is the chief city of that part of Macedonia, and a colony: and we were in that city abiding certain days. And on the sabbath we went out of the city by a river side, where prayer was wont to be made; and we sat down, and spake unto the women which resorted thither. And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul.',null,'{"map": {"view": "med", "kind": "identify", "markers": [{"lat": 41.0121, "lon": 24.2846}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gz-6','geography',66,1,9,11,'Revelation 1:9-11',2,'John was on the isle called Patmos for the word of God and the testimony of Jesus Christ when he received his revelation. Which marker shows Patmos?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'Revelation 1:9 says John was in the isle that is called Patmos, for the word of God and the testimony of Jesus Christ.','Look for a small island in the Aegean Sea, off the coast of Asia Minor.',null,null,'KJV',array['geography','Patmos','Revelation']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'I John, who also am your brother, and companion in tribulation, and in the kingdom and patience of Jesus Christ, was in the isle that is called Patmos, for the word of God, and for the testimony of Jesus Christ. I was in the Spirit on the Lord’s day, and heard behind me a great voice, as of a trumpet, Saying, I am Alpha and Omega, the first and the last: and, What thou seest, write in a book, and send it unto the seven churches which are in Asia; unto Ephesus, and unto Smyrna, and unto Pergamos, and unto Thyatira, and unto Sardis, and unto Philadelphia, and unto Laodicea.',null,'{"map": {"view": "east", "kind": "locate", "markers": [{"lat": 37.325, "lon": 26.5417, "label": "A"}, {"lat": 35.3097, "lon": 24.8933, "label": "B"}, {"lat": 35.0, "lon": 33.0, "label": "C"}, {"lat": 32.5433, "lon": 44.4222, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gz-7','geography',44,18,1,3,'Acts 18:1-3',3,'After leaving Athens, Paul came to the city marked on the map and stayed with Aquila and Priscilla, because they shared the same craft as tentmakers. Which city is it?',null,'["Cyrene", "Thessalonica", "Corinth", "Berea"]'::jsonb,2,'Acts 18:1-3 says Paul departed from Athens and came to Corinth, where he lived and worked with Aquila and Priscilla, for they were tentmakers.','This Greek city lay on the narrow isthmus west of Athens.',null,null,'KJV',array['geography','Corinth','Acts']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'After these things Paul departed from Athens, and came to Corinth; And found a certain Jew named Aquila, born in Pontus, lately come from Italy, with his wife Priscilla; (because that Claudius had commanded all Jews to depart from Rome:) and came unto them. And because he was of the same craft, he abode with them, and wrought: for by their occupation they were tentmakers.',null,'{"map": {"view": "med", "kind": "identify", "markers": [{"lat": 37.9058, "lon": 22.8787}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gz-9','geography',44,14,8,10,'Acts 14:8-10',3,'In the town marked on the map, Paul healed a man who had been a cripple from his mother''s womb and had never walked. Which town is it?',null,'["Derbe", "Tarsus", "Lystra", "Iconium"]'::jsonb,2,'Acts 14:8-10 says there sat a certain man at Lystra, a cripple from his mother''s womb, who leaped and walked when Paul told him to stand upright.','After this miracle, the crowd mistook Paul and Barnabas for gods.',null,null,'KJV',array['geography','Lystra','Acts']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And there sat a certain man at Lystra, impotent in his feet, being a cripple from his mother’s womb, who never had walked: The same heard Paul speak: who stedfastly beholding him, and perceiving that he had faith to be healed, Said with a loud voice, Stand upright on thy feet. And he leaped and walked.',null,'{"map": {"view": "east", "kind": "identify", "markers": [{"lat": 37.6017, "lon": 32.3384}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gz-10','geography',44,17,10,11,'Acts 17:10-11',4,'The brethren sent Paul and Silas by night unto Berea, where the people were more noble than those in Thessalonica and searched the scriptures daily. Which marker shows Berea?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,3,'Acts 17:10-11 says Paul and Silas were sent unto Berea, whose people received the word with readiness and searched the scriptures daily.','It lay in Macedonia, west of Thessalonica, in northern Greece.',null,null,'KJV',array['geography','Berea','Acts']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the brethren immediately sent away Paul and Silas by night unto Berea: who coming thither went into the synagogue of the Jews. These were more noble than those in Thessalonica, in that they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so.',null,'{"map": {"view": "med", "kind": "locate", "markers": [{"lat": 37.9391, "lon": 27.3407, "label": "A"}, {"lat": 37.9719, "lon": 23.7267, "label": "B"}, {"lat": 41.0121, "lon": 24.2846, "label": "C"}, {"lat": 40.5183, "lon": 22.2, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gv-1','geography',11,18,19,20,'1 Kings 18:19-20',1,'Elijah challenged the prophets of Baal on the mountain marked on the map. Which mountain is it?',null,'["Mount Hermon", "Mount Gilboa", "Mount Tabor", "Mount Carmel"]'::jsonb,3,'Elijah told Ahab to gather all Israel and the four hundred and fifty prophets of Baal unto mount Carmel (1 Kings 18:19-20).','This ridge runs down to the Mediterranean coast near modern Haifa.',null,null,'KJV',array['geography','Mount Carmel','1 Kings']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now therefore send, and gather to me all Israel unto mount Carmel, and the prophets of Baal four hundred and fifty, and the prophets of the groves four hundred, which eat at Jezebel’s table. So Ahab sent unto all the children of Israel, and gathered the prophets together unto mount Carmel.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 32.6725, "lon": 35.0233}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gv-2','geography',41,1,16,16,'Mark 1:16',1,'Jesus saw Simon and Andrew casting a net as he walked by the Sea of Galilee. Which marker shows the Sea of Galilee?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'Mark 1:16 says Jesus walked by the sea of Galilee and saw Simon and Andrew casting a net into the sea.','Look for the freshwater lake in the north, fed by the Jordan.',null,null,'KJV',array['geography','Sea of Galilee','Mark']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now as he walked by the sea of Galilee, he saw Simon and Andrew his brother casting a net into the sea: for they were fishers.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.8189, "lon": 35.59, "label": "A"}, {"lat": 32.6725, "lon": 35.0233, "label": "B"}, {"lat": 31.5, "lon": 35.5, "label": "C"}, {"lat": 31.7767, "lon": 35.2342, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gv-3','geography',40,3,13,13,'Matthew 3:13',1,'Jesus came from Galilee to be baptized by John in the river marked on the map. Which river is it?',null,'["Jabbok", "Arnon", "Jordan", "Kidron"]'::jsonb,2,'Matthew 3:13 records that Jesus came from Galilee to Jordan unto John, to be baptized of him.','This river flows north to south, linking two seas.',null,null,'KJV',array['geography','Jordan','Matthew']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then cometh Jesus from Galilee to Jordan unto John, to be baptized of him.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.7614, "lon": 35.5583}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gv-4','geography',9,31,1,4,'1 Samuel 31:1-4',3,'King Saul and his sons fell in battle against the Philistines on Mount Gilboa. Which marker shows Mount Gilboa?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'The men of Israel fell down slain in mount Gilboa, and Saul took a sword and fell upon it (1 Samuel 31:1-4).','It overlooks the eastern end of the Jezreel Valley.',null,null,'KJV',array['geography','Mount Gilboa','1 Samuel']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now the Philistines fought against Israel: and the men of Israel fled from before the Philistines, and fell down slain in mount Gilboa. And the Philistines followed hard upon Saul and upon his sons; and the Philistines slew Jonathan, and Abinadab, and Malchi-shua, Saul’s sons. And the battle went sore against Saul, and the archers hit him; and he was sore wounded of the archers. Then said Saul unto his armourbearer, Draw thy sword, and thrust me through therewith; lest these uncircumcised come and thrust me through, and abuse me. But his armourbearer would not; for he was sore afraid. Therefore Saul took a sword, and fell upon it.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.7779, "lon": 35.2457, "label": "A"}, {"lat": 32.4339, "lon": 35.4144, "label": "B"}, {"lat": 31.5251, "lon": 35.1022, "label": "C"}, {"lat": 32.6725, "lon": 35.0233, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gv-5','geography',1,32,22,24,'Genesis 32:22-24',3,'Jacob sent his family across the ford of the river marked on the map, then wrestled with a man until daybreak. Which river is it?',null,'["Jabbok", "Arnon", "Jordan", "Kidron"]'::jsonb,0,'Jacob passed over the ford Jabbok, and there wrestled a man with him until the breaking of the day (Genesis 32:22-24).','An eastern tributary that joins the Jordan from the hills of Gilead.',null,null,'KJV',array['geography','Jabbok','Genesis']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he rose up that night, and took his two wives, and his two womenservants, and his eleven sons, and passed over the ford Jabbok. And he took them, and sent them over the brook, and sent over that he had. And Jacob was left alone; and there wrestled a man with him until the breaking of the day.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 32.1153, "lon": 35.5431}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gv-6','geography',1,2,10,14,'Genesis 2:10-14',2,'Genesis names the Euphrates as the fourth of the rivers flowing out of Eden. Which marker shows the Euphrates?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Genesis 2:10-14 describes a river going out of Eden that parted into four heads, and the fourth river is Euphrates.','This great river runs through Mesopotamia toward the Persian Gulf.',null,null,'KJV',array['geography','Euphrates','Genesis']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And a river went out of Eden to water the garden; and from thence it was parted, and became into four heads. The name of the first is Pison: that is it which compasseth the whole land of Havilah, where there is gold; And the gold of that land is good: there is bdellium and the onyx stone. And the name of the second river is Gihon: the same is it that compasseth the whole land of Ethiopia. And the name of the third river is Hiddekel: that is it which goeth toward the east of Assyria. And the fourth river is Euphrates.',null,'{"map": {"view": "east", "kind": "locate", "markers": [{"lat": 31.7614, "lon": 35.5583, "label": "A"}, {"lat": 31.0043, "lon": 47.442, "label": "B"}, {"lat": 31.4653, "lon": 30.3667, "label": "C"}, {"lat": 32.1892, "lon": 48.2578, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gv-7','geography',42,22,39,39,'Luke 22:39',2,'On the night of his betrayal, Jesus went with his disciples, as he was wont, to the hill marked on the map. Which hill is it?',null,'["Mount Hermon", "Mount Tabor", "Mount of Olives", "Mount Carmel"]'::jsonb,2,'Luke 22:39 says Jesus came out and went, as he was wont, to the mount of Olives, and his disciples followed him.','It rises just east of Jerusalem across a valley.',null,null,'KJV',array['geography','Mount of Olives','Luke']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he came out, and went, as he was wont, to the mount of Olives; and his disciples also followed him.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.7779, "lon": 35.2457}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gv-8','geography',1,8,4,4,'Genesis 8:4',3,'After the flood, Noah''s ark came to rest upon the mountains of Ararat. Which marker shows Ararat?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Genesis 8:4 states that the ark rested in the seventh month upon the mountains of Ararat.','Look to the highlands far north of Mesopotamia.',null,null,'KJV',array['geography','Ararat','Genesis']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the ark rested in the seventh month, on the seventeenth day of the month, upon the mountains of Ararat.',null,'{"map": {"view": "east", "kind": "locate", "markers": [{"lat": 26.65, "lon": 37.9167, "label": "A"}, {"lat": 39.7028, "lon": 44.3004, "label": "B"}, {"lat": 32.5433, "lon": 44.4222, "label": "C"}, {"lat": 29.8488, "lon": 31.253, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gv-9','geography',1,14,3,3,'Genesis 14:3',2,'In Abram''s day, kings were joined together in the vale of Siddim, ''which is the salt sea.'' Which marker shows the Salt Sea?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'Genesis 14:3 says the kings were joined together in the vale of Siddim, which is the salt sea.','It lies at the southern end of the Jordan River.',null,null,'KJV',array['geography','Salt Sea','Genesis']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'All these were joined together in the vale of Siddim, which is the salt sea.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.5, "lon": 35.5, "label": "A"}, {"lat": 32.8189, "lon": 35.59, "label": "B"}, {"lat": 32.6725, "lon": 35.0233, "label": "C"}, {"lat": 32.0545, "lon": 34.753, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gv-10','geography',10,15,23,23,'2 Samuel 15:23',4,'Fleeing from Absalom, King David passed over the brook marked on the map as he left Jerusalem. Which brook is it?',null,'["Arnon", "Kidron", "Jabbok", "Jordan"]'::jsonb,1,'2 Samuel 15:23 records that the king himself passed over the brook Kidron, and all the people passed over toward the wilderness.','This brook runs in the valley between Jerusalem and the Mount of Olives.',null,null,'KJV',array['geography','Kidron','2 Samuel']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And all the country wept with a loud voice, and all the people passed over: the king also himself passed over the brook Kidron, and all the people passed over, toward the way of the wilderness.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.7803, "lon": 35.24}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gy-1','geography',32,3,3,3,'Jonah 3:3',1,'After the great fish, the LORD sent Jonah a second time to preach to Nineveh, ''an exceeding great city.'' Which marker shows Nineveh?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Jonah 3:3 says Jonah ''went unto Nineveh, according to the word of the LORD,'' a city of three days'' journey. Nineveh lay on the Tigris in Assyria.','Look along the Tigris in the heart of Assyria, north of Babylonia.',null,null,'KJV',array['geography','Nineveh','Jonah']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'So Jonah arose, and went unto Nineveh, according to the word of the LORD. Now Nineveh was an exceeding great city of three days’ journey.',null,'{"map": {"view": "east", "kind": "locate", "markers": [{"lat": 32.1892, "lon": 48.2578, "label": "A"}, {"lat": 36.3594, "lon": 43.1528, "label": "B"}, {"lat": 29.8488, "lon": 31.253, "label": "C"}, {"lat": 32.5433, "lon": 44.4222, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gy-2','geography',12,24,15,15,'2 Kings 24:15',1,'Nebuchadnezzar carried King Jehoiachin, his household and the mighty of the land away captive to the city marked on the map. Which city is it?',null,'["Nineveh", "Susa", "Babylon", "Haran"]'::jsonb,2,'2 Kings 24:15 records that Nebuchadnezzar ''carried away Jehoiachin to Babylon,'' taking them ''into captivity from Jerusalem to Babylon.''','It was the capital of Nebuchadnezzar''s own empire, on the Euphrates.',null,null,'KJV',array['geography','Babylon','2 Kings']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he carried away Jehoiachin to Babylon, and the king’s mother, and the king’s wives, and his officers, and the mighty of the land, those carried he into captivity from Jerusalem to Babylon.',null,'{"map": {"view": "east", "kind": "identify", "markers": [{"lat": 32.5433, "lon": 44.4222}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gy-3','geography',11,18,19,19,'1 Kings 18:19',1,'Elijah challenged Ahab to gather all Israel and the four hundred and fifty prophets of Baal to Mount Carmel. Which marker shows Mount Carmel?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'In 1 Kings 18:19 Elijah tells Ahab to ''gather to me all Israel unto mount Carmel'' with the prophets of Baal. Carmel is the ridge reaching the Mediterranean coast in the north.','This mountain ridge juts out toward the sea on Israel''s northern coast.',null,null,'KJV',array['geography','Mount Carmel','1 Kings']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now therefore send, and gather to me all Israel unto mount Carmel, and the prophets of Baal four hundred and fifty, and the prophets of the groves four hundred, which eat at Jezebel’s table.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.7779, "lon": 35.2457, "label": "A"}, {"lat": 32.6725, "lon": 35.0233, "label": "B"}, {"lat": 33.4, "lon": 35.85, "label": "C"}, {"lat": 31.2447, "lon": 34.8408, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gy-5','geography',11,16,24,24,'1 Kings 16:24',2,'King Omri bought a hill from Shemer for two talents of silver and built a city on it, naming it Samaria. Which marker shows Samaria?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'1 Kings 16:24 tells how Omri ''bought the hill Samaria of Shemer for two talents of silver'' and called the city Samaria ''after the name of Shemer, owner of the hill.'' It became the capital of the northern kingdom.','It was the northern kingdom''s capital, in the hill country north of Jerusalem.',null,null,'KJV',array['geography','Samaria','1 Kings']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he bought the hill Samaria of Shemer for two talents of silver, and built on the hill, and called the name of the city which he built, after the name of Shemer, owner of the hill, Samaria.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 33.249, "lon": 35.652, "label": "A"}, {"lat": 32.2761, "lon": 35.195, "label": "B"}, {"lat": 31.7767, "lon": 35.2342, "label": "C"}, {"lat": 31.2447, "lon": 34.8408, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gy-6','geography',12,25,6,6,'2 Kings 25:6',4,'After Jerusalem fell, King Zedekiah was captured and brought up to the king of Babylon, who passed judgment on him at the town marked on the map. Which town is it?',null,'["Riblah", "Damascus", "Hamath", "Sidon"]'::jsonb,0,'2 Kings 25:6 says ''they took the king, and brought him up to the king of Babylon to Riblah; and they gave judgment upon him.'' Riblah lay in Syria on the Orontes.','Nebuchadnezzar held his field headquarters here in Syria, far north of Jerusalem.',null,null,'KJV',array['geography','Riblah','2 Kings']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'So they took the king, and brought him up to the king of Babylon to Riblah; and they gave judgment upon him.',null,'{"map": {"view": "east", "kind": "identify", "markers": [{"lat": 34.4595, "lon": 36.5726}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gy-7','geography',30,1,1,1,'Amos 1:1',3,'The prophet Amos was ''among the herdmen'' of the town marked on the map. Which town is it?',null,'["Bethel", "Megiddo", "Dan", "Tekoa"]'::jsonb,3,'Amos 1:1 introduces ''The words of Amos, who was among the herdmen of Tekoa.'' Tekoa was a village in Judah south of Bethlehem.','Amos came from a small Judean village on the edge of the wilderness, south of Bethlehem.',null,null,'KJV',array['geography','Tekoa','Amos']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'The words of Amos, who was among the herdmen of Tekoa, which he saw concerning Israel in the days of Uzziah king of Judah, and in the days of Jeroboam the son of Joash king of Israel, two years before the earthquake.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.6325, "lon": 35.2105}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gy-8','geography',11,17,9,9,'1 Kings 17:9',2,'During the drought the LORD told Elijah to go to Zarephath, where a widow woman would sustain him. Which marker shows Zarephath?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,2,'1 Kings 17:9 commands, ''get thee to Zarephath, which belongeth to Zidon,'' where a widow woman would feed him. It lay on the Phoenician coast between Tyre and Sidon.','The verse says it belonged to Zidon, so look on the northern coast.',null,null,'KJV',array['geography','Zarephath','1 Kings']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Arise, get thee to Zarephath, which belongeth to Zidon, and dwell there: behold, I have commanded a widow woman there to sustain thee.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.2447, "lon": 34.8408, "label": "A"}, {"lat": 31.8717, "lon": 35.4446, "label": "B"}, {"lat": 33.4642, "lon": 35.2951, "label": "C"}, {"lat": 31.504, "lon": 34.4644, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gy-9','geography',24,43,7,7,'Jeremiah 43:7',3,'Against Jeremiah''s warning, the remnant of Judah fled into Egypt and came to Tahpanhes, taking the prophet with them. Which marker shows Tahpanhes?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'Jeremiah 43:7 says ''they came into the land of Egypt... thus came they even to Tahpanhes.'' It was a border city in the eastern Nile Delta.','The refugees went into Egypt, so look in the eastern Nile Delta.',null,null,'KJV',array['geography','Tahpanhes','Jeremiah']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'So they came into the land of Egypt: for they obeyed not the voice of the LORD: thus came they even to Tahpanhes.',null,'{"map": {"view": "east", "kind": "locate", "markers": [{"lat": 30.8606, "lon": 32.1714, "label": "A"}, {"lat": 32.5433, "lon": 44.4222, "label": "B"}, {"lat": 33.5111, "lon": 36.3064, "label": "C"}, {"lat": 36.8644, "lon": 39.0328, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gy-10','geography',11,21,1,1,'1 Kings 21:1',2,'Naboth''s vineyard, coveted by King Ahab, lay in the town marked on the map, close by Ahab''s palace. Which town is it?',null,'["Hebron", "Lachish", "Gezer", "Jezreel"]'::jsonb,3,'1 Kings 21:1 says Naboth ''had a vineyard, which was in Jezreel, hard by the palace of Ahab king of Samaria.''','Naboth''s hometown gave its name to the broad northern valley below Mount Gilboa.',null,null,'KJV',array['geography','Jezreel','1 Kings']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And it came to pass after these things, that Naboth the Jezreelite had a vineyard, which was in Jezreel, hard by the palace of Ahab king of Samaria.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 32.5579, "lon": 35.328}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m1-1','mystery',1,44,1,2,'Genesis 44:1-2',2,'According to the text, who ordered the silver cup to be put in the youngest brother''s sack?',null,'["Joseph, who commanded his steward to do it", "Benjamin, who hid it there himself", "Reuben, who took it from the table", "Judah, who wanted to test his brothers"]'::jsonb,0,'Joseph commanded his steward to put ''my cup, the silver cup, in the sack''s mouth of the youngest,'' and the steward ''did according to the word that Joseph had spoken'' (Genesis 44:1-2).','Read who ''commanded the steward of his house.''',null,null,'KJV',array['mystery','Genesis','m1']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he commanded the steward of his house, saying, Fill the men’s sacks with food, as much as they can carry, and put every man’s money in his sack’s mouth. And put my cup, the silver cup, in the sack’s mouth of the youngest, and his corn money. And he did according to the word that Joseph had spoken.',null,'{"case_title": "The Silver Cup in the Sack", "stage": 1, "stages": 5, "clue": "Household record: the master of the house gave orders to his steward about the travellers'' sacks, including special instructions about his own cup."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m1-2','mystery',1,44,4,5,'Genesis 44:4-5',2,'What question did Joseph tell the steward to put to the men when he overtook them?',null,'["Wherefore have ye rewarded evil for good?", "Why have ye not paid for your corn?", "Where is your youngest brother?", "Why did ye leave before morning?"]'::jsonb,0,'Joseph instructed the steward to say, ''Wherefore have ye rewarded evil for good?'' and to describe the cup as the one in which his lord drinks and divines (Genesis 44:4-5).','The question contrasts two opposites: what they received and what they gave back.',null,null,'KJV',array['mystery','Genesis','m1']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And when they were gone out of the city, and not yet far off, Joseph said unto his steward, Up, follow after the men; and when thou dost overtake them, say unto them, Wherefore have ye rewarded evil for good? Is not this it in which my lord drinketh, and whereby indeed he divineth? ye have done evil in so doing.',null,'{"case_title": "The Silver Cup in the Sack", "stage": 2, "stages": 5, "clue": "Witness statement: ''We were gone out of the city, and not yet far off, when the steward overtook us and put a hard question to us.''"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m1-3','mystery',1,44,9,10,'Genesis 44:9-10',2,'What terms did the steward state for the one with whom the cup was found?',null,'["He shall pay back the cup''s value twice over", "He shall be sent home in disgrace", "He shall be my servant; and the rest shall be blameless", "All the brothers shall be put to death"]'::jsonb,2,'The brothers offered death for the guilty one and bondage for themselves, but the steward said, ''he with whom it is found shall be my servant; and ye shall be blameless'' (Genesis 44:9-10).','The steward''s terms were narrower than the brothers'' own offer.',null,null,'KJV',array['mystery','Genesis','m1']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'With whomsoever of thy servants it be found, both let him die, and we also will be my lord’s bondmen. And he said, Now also let it be according unto your words: he with whom it is found shall be my servant; and ye shall be blameless.',null,'{"case_title": "The Silver Cup in the Sack", "stage": 3, "stages": 5, "clue": "Transcript of the roadside exchange: the brothers, sure of their innocence, proposed a severe penalty, but the steward set his own terms."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m1-4','mystery',1,44,11,13,'Genesis 44:11-13',2,'Where was the cup found, and what did the brothers do next?',null,'["In Simeon''s sack; they left him behind", "In Benjamin''s sack; they rent their clothes and returned to the city", "In Reuben''s sack; they hid it again", "In Judah''s sack; they fled toward Canaan"]'::jsonb,1,'The steward ''began at the eldest, and left at the youngest: and the cup was found in Benjamin''s sack''; then the brothers ''rent their clothes'' and returned to the city (Genesis 44:12-13).','The search ended with the youngest brother.',null,null,'KJV',array['mystery','Genesis','m1']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then they speedily took down every man his sack to the ground, and opened every man his sack. And he searched, and began at the eldest, and left at the youngest: and the cup was found in Benjamin’s sack. Then they rent their clothes, and laded every man his ass, and returned to the city.',null,'{"case_title": "The Silver Cup in the Sack", "stage": 4, "stages": 5, "clue": "Search report: each sack was lowered to the ground and opened, beginning with the eldest brother and ending with the youngest."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m1-5','mystery',1,44,32,33,'Genesis 44:32-33',2,'How did Judah propose to resolve the case?',null,'["He offered to pay double silver for the cup", "He accused the steward of planting the cup", "He asked that all the brothers stay in Egypt except Judah", "He asked to remain as a bondman instead of the lad, so the lad could go home"]'::jsonb,3,'Judah said he ''became surety for the lad unto my father'' and asked to ''abide instead of the lad a bondman to my lord; and let the lad go up with his brethren'' (Genesis 44:32-33).','Judah had made himself responsible for the youngest before his father.',null,null,'KJV',array['mystery','Genesis','m1']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'For thy servant became surety for the lad unto my father, saying, If I bring him not unto thee, then I shall bear the blame to my father for ever. Now therefore, I pray thee, let thy servant abide instead of the lad a bondman to my lord; and let the lad go up with his brethren.',null,'{"case_title": "The Silver Cup in the Sack", "stage": 5, "stages": 5, "clue": "Final statement before the ruler: one brother stepped forward, explaining that he had pledged himself to his father for the lad''s safe return."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m6-1','mystery',7,16,4,4,'Judges 16:4',2,'According to the text, where did Delilah live?',null,'["In the town of Zorah", "In the valley of Sorek", "In the house of Dagon", "In the city of Gaza"]'::jsonb,1,'Judges 16:4 says Samson loved a woman "in the valley of Sorek, whose name was Delilah."','The location is named in the same verse that first names Delilah.',null,null,'KJV',array['mystery','Judges','m6']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And it came to pass afterward, that he loved a woman in the valley of Sorek, whose name was Delilah.',null,'{"case_title": "The Secret of Samson''s Strength", "stage": 1, "stages": 5, "clue": "Case note: The file opens after Samson''s escape from Gaza. Our informant says he has come to love a woman who lives in a certain valley."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m6-2','mystery',7,16,5,5,'Judges 16:5',2,'Who approached Delilah, and what did each of them promise her?',null,'["The men of Judah, each promising thirty changes of garments", "The priests of Dagon, each promising a talent of gold", "The lords of the Philistines, each promising eleven hundred pieces of silver", "Samson''s father and mother, each promising a flock of sheep"]'::jsonb,2,'In Judges 16:5 the lords of the Philistines asked Delilah to entice Samson and promised, "every one of us eleven hundred pieces of silver."','Those who came up unto her were the rulers of Israel''s enemies, and each promised the same large sum.',null,null,'KJV',array['mystery','Judges','m6']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the lords of the Philistines came up unto her, and said unto her, Entice him, and see wherein his great strength lieth, and by what means we may prevail against him, that we may bind him to afflict him: and we will give thee every one of us eleven hundred pieces of silver.',null,'{"case_title": "The Secret of Samson''s Strength", "stage": 2, "stages": 5, "clue": "Intercepted message: Powerful men came up unto Delilah with a proposal and a price for her cooperation."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m6-3','mystery',7,16,6,9,'Judges 16:6-9',2,'When Delilah first asked, what did Samson say would make him weak?',null,'["Being kept from eating bread and drinking water", "Being bound with seven green withs that were never dried", "Having his eyes put out", "Being bound with chains of iron"]'::jsonb,1,'Samson told Delilah, "If they bind me with seven green withs that were never dried, then shall I be weak" (Judges 16:7), yet he broke them when she bound him (Judges 16:9).','Look for something freshly cut that had not yet dried out.',null,null,'KJV',array['mystery','Judges','m6']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Delilah said to Samson, Tell me, I pray thee, wherein thy great strength lieth, and wherewith thou mightest be bound to afflict thee. And Samson said unto her, If they bind me with seven green withs that were never dried, then shall I be weak, and be as another man. Then the lords of the Philistines brought up to her seven green withs which had not been dried, and she bound him with them. Now there were men lying in wait, abiding with her in the chamber. And she said unto him, The Philistines be upon thee, Samson. And he brake the withs, as a thread of tow is broken when it toucheth the fire. So his strength was not known.',null,'{"case_title": "The Secret of Samson''s Strength", "stage": 3, "stages": 5, "clue": "Evidence bag #1: Seven fresh, undried withs recovered from Delilah''s chamber, where men had been lying in wait. Samson broke them as a thread of tow breaks when it touches the fire."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m6-4','mystery',7,16,15,17,'Judges 16:15-17',2,'What secret did Samson finally reveal to Delilah?',null,'["That he could be weakened only if he were bound while asleep", "That he would lose his strength if he ever drank wine", "That his strength came from a hidden amulet he wore", "That no razor had come upon his head, for he had been a Nazarite unto God from his mother''s womb"]'::jsonb,3,'In Judges 16:17 Samson said, "There hath not come a razor upon mine head; for I have been a Nazarite unto God from my mother''s womb: if I be shaven, then my strength will go from me."','The secret concerns his head and a lifelong vow to God.',null,null,'KJV',array['mystery','Judges','m6']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And she said unto him, How canst thou say, I love thee, when thine heart is not with me? thou hast mocked me these three times, and hast not told me wherein thy great strength lieth. And it came to pass, when she pressed him daily with her words, and urged him, so that his soul was vexed unto death; That he told her all his heart, and said unto her, There hath not come a razor upon mine head; for I have been a Nazarite unto God from my mother’s womb: if I be shaven, then my strength will go from me, and I shall become weak, and be like any other man.',null,'{"case_title": "The Secret of Samson''s Strength", "stage": 4, "stages": 5, "clue": "Witness statement: \"She pressed him daily with her words, until his soul was vexed unto death. Then he finally told her all his heart.\""}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m6-5','mystery',7,16,19,20,'Judges 16:19-20',2,'What really happened that left Samson powerless?',null,'["He was wounded in battle and carried to Gaza", "The lords of the Philistines put out his eyes before he could escape", "Delilah bound him with new ropes while the Philistines held him down", "While he slept upon Delilah''s knees, a man shaved off the seven locks of his head, and his strength went from him"]'::jsonb,3,'Judges 16:19 says Delilah "made him sleep upon her knees" and had a man "shave off the seven locks of his head," and "his strength went from him"; verse 20 adds that "he wist not that the LORD was departed from him."','Remember the secret he revealed in the previous stage, and what happened while he slept.',null,null,'KJV',array['mystery','Judges','m6']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And she made him sleep upon her knees; and she called for a man, and she caused him to shave off the seven locks of his head; and she began to afflict him, and his strength went from him. And she said, The Philistines be upon thee, Samson. And he awoke out of his sleep, and said, I will go out as at other times before, and shake myself. And he wist not that the LORD was departed from him.',null,'{"case_title": "The Secret of Samson''s Strength", "stage": 5, "stages": 5, "clue": "Final report: Delilah cried, \"The Philistines be upon thee, Samson.\" He awoke and said he would go out as at other times before and shake himself. The text adds that he did not know something had changed."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m7-1','mystery',11,3,16,17,'1 Kings 3:16-17',1,'According to the first woman, what was the living arrangement of the two women?',null,'["They lived in separate cities", "They lived in the king''s palace", "They dwelt together in one house", "They were traveling strangers who met at an inn"]'::jsonb,2,'The first woman said, "I and this woman dwell in one house; and I was delivered of a child with her in the house" (1 Kings 3:17).','Listen to how she describes where they both live.',null,null,'KJV',array['mystery','1 Kings','m7']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then came there two women, that were harlots, unto the king, and stood before him. And the one woman said, O my lord, I and this woman dwell in one house; and I was delivered of a child with her in the house.',null,'{"case_title": "Two Mothers and One Child", "stage": 1, "stages": 5, "clue": "Court record: two women arrived together and stood before the king. The first testified that they shared a home and that she had given birth there."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m7-2','mystery',11,3,18,19,'1 Kings 3:18-19',1,'According to the testimony, how did the other woman''s child die?',null,'["She overlaid it in the night", "It died at birth", "It fell sick with a fever", "It was taken by a stranger"]'::jsonb,0,'The first woman testified, "this woman''s child died in the night; because she overlaid it" (1 Kings 3:19).','The cause happened while the mother lay with the child at night.',null,null,'KJV',array['mystery','1 Kings','m7']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And it came to pass the third day after that I was delivered, that this woman was delivered also: and we were together; there was no stranger with us in the house, save we two in the house. And this woman’s child died in the night; because she overlaid it.',null,'{"case_title": "Two Mothers and One Child", "stage": 2, "stages": 5, "clue": "Witness statement: the second baby was born three days after the first, and no stranger was with them in the house. One of the infants did not survive the night."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m7-3','mystery',11,3,20,21,'1 Kings 3:20-21',1,'What did the first woman claim happened at midnight?',null,'["She woke and found both babies missing", "A servant switched the children", "The other woman fled the house with both babies", "The other woman took her son and laid her own dead child in the first woman''s bosom"]'::jsonb,3,'She said the other woman "took my son from beside me... and laid her dead child in my bosom," and in the morning she saw "it was not my son, which I did bear" (1 Kings 3:20-21).','Think about what was exchanged while she slept.',null,null,'KJV',array['mystery','1 Kings','m7']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And she arose at midnight, and took my son from beside me, while thine handmaid slept, and laid it in her bosom, and laid her dead child in my bosom. And when I rose in the morning to give my child suck, behold, it was dead: but when I had considered it in the morning, behold, it was not my son, which I did bear.',null,'{"case_title": "Two Mothers and One Child", "stage": 3, "stages": 5, "clue": "Witness statement: \"She arose at midnight... while thine handmaid slept.\" At morning, the first woman examined the dead child closely."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m7-4','mystery',11,3,24,25,'1 Kings 3:24-25',1,'What did the king command after the sword was brought?',null,'["That both women be sent away", "That the child be given to the elders of the city", "That the living child be divided in two, half to each woman", "That the women draw lots for the child"]'::jsonb,2,'The king said, "Bring me a sword," and then, "Divide the living child in two, and give half to the one, and half to the other" (1 Kings 3:24-25).','He asked for a sword; consider what he ordered next.',null,null,'KJV',array['mystery','1 Kings','m7']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the king said, Bring me a sword. And they brought a sword before the king. And the king said, Divide the living child in two, and give half to the one, and half to the other.',null,'{"case_title": "Two Mothers and One Child", "stage": 4, "stages": 5, "clue": "Evidence log: after hearing both women insist the living child was theirs, the king called for an unusual object, and it was brought before him."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m7-5','mystery',11,3,26,27,'1 Kings 3:26-27',1,'Whom did the king declare to be the true mother of the living child?',null,'["The woman who pleaded, \"Give her the living child, and in no wise slay it\"", "Both women, who were told to share the child", "Neither woman, so the king kept the child", "The woman who said, \"Let it be neither mine nor thine, but divide it\""]'::jsonb,0,'The woman whose bowels yearned for her son begged that the child be given away rather than slain, and the king said, "Give her the living child, and in no wise slay it: she is the mother thereof" (1 Kings 3:26-27).','Which woman was willing to give up her claim so the child would live?',null,null,'KJV',array['mystery','1 Kings','m7']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then spake the woman whose the living child was unto the king, for her bowels yearned upon her son, and she said, O my lord, give her the living child, and in no wise slay it. But the other said, Let it be neither mine nor thine, but divide it. Then the king answered and said, Give her the living child, and in no wise slay it: she is the mother thereof.',null,'{"case_title": "Two Mothers and One Child", "stage": 5, "stages": 5, "clue": "Final testimony: one woman''s \"bowels yearned upon her son\" and she spoke up at once; the other woman answered very differently. The king then gave his verdict."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m4-1','mystery',6,2,1,1,'Joshua 2:1',1,'According to the record, who sent the two men out to spy?',null,'["Moses the servant of the LORD", "The king of Jericho", "Rahab", "Joshua the son of Nun"]'::jsonb,3,'Joshua 2:1 states that Joshua the son of Nun sent out of Shittim two men to spy secretly, saying, Go view the land, even Jericho.','Look for the leader named at the very start of the chapter, identified by his father''s name.',null,null,'KJV',array['mystery','Joshua','m4']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Joshua the son of Nun sent out of Shittim two men to spy secretly, saying, Go view the land, even Jericho. And they went, and came into an harlot’s house, named Rahab, and lodged there.',null,'{"case_title": "The Spies on the Roof", "stage": 1, "stages": 5, "clue": "Camp record: two men departed from Shittim under orders to view the land, even Jericho. They were later traced to the house of a woman named Rahab."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m4-2','mystery',6,2,4,6,'Joshua 2:4-6',1,'Where were the two men actually hidden?',null,'["At the bottom of a well", "In a cave outside the city", "On the roof, under stalks of flax", "In the king''s own storehouse"]'::jsonb,2,'Joshua 2:6 says she had brought them up to the roof of the house and hid them with the stalks of flax which she had laid in order upon the roof.','Think high, not low, and of something she had laid out in order there.',null,null,'KJV',array['mystery','Joshua','m4']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the woman took the two men, and hid them, and said thus, There came men unto me, but I wist not whence they were: And it came to pass about the time of shutting of the gate, when it was dark, that the men went out: whither the men went I wot not: pursue after them quickly; for ye shall overtake them. But she had brought them up to the roof of the house, and hid them with the stalks of flax, which she had laid in order upon the roof.',null,'{"case_title": "The Spies on the Roof", "stage": 2, "stages": 5, "clue": "Statement given to the king''s messengers: ''There came men unto me, but I wist not whence they were... pursue after them quickly.'' Yet the text says she had already taken the two men and hid them."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m4-3','mystery',6,2,7,7,'Joshua 2:7',1,'Which way did the pursuers go in search of the men?',null,'["North to the mountain of Lebanon", "The way to Jordan unto the fords", "Toward the Red sea", "Back to Shittim"]'::jsonb,1,'Joshua 2:7 records that the men pursued after them the way to Jordan unto the fords, and the gate was shut once they had gone out.','The pursuers headed toward a river crossing.',null,null,'KJV',array['mystery','Joshua','m4']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the men pursued after them the way to Jordan unto the fords: and as soon as they which pursued after them were gone out, they shut the gate.',null,'{"case_title": "The Spies on the Roof", "stage": 3, "stages": 5, "clue": "Gatekeeper''s report: the king''s men went out in pursuit of the spies, and as soon as the pursuers had gone out, the city gate was shut behind them."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m4-4','mystery',6,2,9,11,'Joshua 2:9-11',1,'What did Rahab tell the spies she knew?',null,'["That the spies had been seen at Shittim", "That Jericho''s walls could never be taken", "That the king of Jericho would make peace with Israel", "That the LORD had given them the land"]'::jsonb,3,'In Joshua 2:9 Rahab says, I know that the LORD hath given you the land, and in verse 11 she confesses that the LORD your God, he is God in heaven above, and in earth beneath.','Her words began with ''I know'' and concerned who would possess the land.',null,null,'KJV',array['mystery','Joshua','m4']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And she said unto the men, I know that the LORD hath given you the land, and that your terror is fallen upon us, and that all the inhabitants of the land faint because of you. For we have heard how the LORD dried up the water of the Red sea for you, when ye came out of Egypt; and what ye did unto the two kings of the Amorites, that were on the other side Jordan, Sihon and Og, whom ye utterly destroyed. And as soon as we had heard these things, our hearts did melt, neither did there remain any more courage in any man, because of you: for the LORD your God, he is God in heaven above, and in earth beneath.',null,'{"case_title": "The Spies on the Roof", "stage": 4, "stages": 5, "clue": "Overheard on the roof before the men lay down: the woman spoke of what Jericho had heard about the Red sea and about the kings Sihon and Og."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m4-5','mystery',6,2,15,21,'Joshua 2:15-21',1,'What really happened: how did the spies leave Jericho, and what marked Rahab''s house?',null,'["They hid in a cart of flax, and she hung a white cloth on her roof", "They climbed down a ladder, and she placed a lamp in the window", "She let them down by a cord through the window, and she bound a scarlet line in that window", "They walked out through the city gate at dawn, and she painted the door with blood"]'::jsonb,2,'Joshua 2:15 says she let them down by a cord through the window because her house was upon the town wall, and Joshua 2:21 says she bound the scarlet line in the window.','Remember where her house stood, and the color of the thread the spies named.',null,null,'KJV',array['mystery','Joshua','m4']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then she let them down by a cord through the window: for her house was upon the town wall, and she dwelt upon the wall. And she said unto them, Get you to the mountain, lest the pursuers meet you; and hide yourselves there three days, until the pursuers be returned: and afterward may ye go your way. And the men said unto her, We will be blameless of this thine oath which thou hast made us swear. Behold, when we come into the land, thou shalt bind this line of scarlet thread in the window which thou didst let us down by: and thou shalt bring thy father, and thy mother, and thy brethren, and all thy father’s household, home unto thee. And it shall be, that whosoever shall go out of the doors …',null,'{"case_title": "The Spies on the Roof", "stage": 5, "stages": 5, "clue": "Final evidence: her house was upon the town wall. The spies told her to gather her household and to bind a token in the very window they had used; she answered, ''According unto your words, so be it.''"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m3-1','mystery',1,31,19,21,'Genesis 31:19-21',3,'According to the text, what was Laban doing when the images were taken?',null,'["He was at a wedding feast in Haran", "He had gone to shear his sheep", "He was offering a sacrifice on mount Gilead", "He was digging a well in Gerar"]'::jsonb,1,'Genesis 31:19 says Laban went to shear his sheep, and while he was away the images that were his were stolen. Jacob then fled over the river toward mount Gilead (Genesis 31:21).','Think about seasonal work with a flock.',null,null,'KJV',array['mystery','Genesis','m3']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Laban went to shear his sheep: and Rachel had stolen the images that were her father’s. And Jacob stole away unawares to Laban the Syrian, in that he told him not that he fled. So he fled with all that he had; and he rose up, and passed over the river, and set his face toward the mount Gilead.',null,'{"case_title": "The Missing Household Gods", "stage": 1, "stages": 5, "clue": "Shepherd''s log: the master of the house was away from his tents tending to the flock when the images vanished, and Jacob left without telling him."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m3-2','mystery',1,31,22,24,'Genesis 31:22-24',3,'Where did Laban and his brethren overtake Jacob?',null,'["At the brook Jabbok", "At the well of Bethel", "In the mount Gilead", "At the gates of Shechem"]'::jsonb,2,'Laban was told on the third day that Jacob had fled, pursued him seven days'' journey, and overtook him in the mount Gilead (Genesis 31:22-23).','Look at where the seven days'' journey of pursuit ended in verse 23.',null,null,'KJV',array['mystery','Genesis','m3']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And it was told Laban on the third day that Jacob was fled. And he took his brethren with him, and pursued after him seven days’ journey; and they overtook him in the mount Gilead. And God came to Laban the Syrian in a dream by night, and said unto him, Take heed that thou speak not to Jacob either good or bad.',null,'{"case_title": "The Missing Household Gods", "stage": 2, "stages": 5, "clue": "Messenger''s report: word of Jacob''s flight reached Laban on the third day, and he set out with his brethren on a long pursuit."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m3-3','mystery',1,31,30,32,'Genesis 31:30-32',3,'What did Jacob say should happen to whoever was found with Laban''s gods?',null,'["He should pay double to Laban", "He should not live", "He should serve Laban seven years", "He should be sent back to Haran"]'::jsonb,1,'When Laban asked why Jacob had stolen his gods, Jacob said, "With whomsoever thou findest thy gods, let him not live" (Genesis 31:32). The text adds that Jacob knew not that Rachel had stolen them.','Jacob''s pledge was far more severe than a fine or a period of service.',null,null,'KJV',array['mystery','Genesis','m3']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And now, though thou wouldest needs be gone, because thou sore longedst after thy father’s house, yet wherefore hast thou stolen my gods? And Jacob answered and said to Laban, Because I was afraid: for I said, Peradventure thou wouldest take by force thy daughters from me. With whomsoever thou findest thy gods, let him not live: before our brethren discern thou what is thine with me, and take it to thee. For Jacob knew not that Rachel had stolen them.',null,'{"case_title": "The Missing Household Gods", "stage": 3, "stages": 5, "clue": "Witness statement from the confrontation: Laban questioned why Jacob left, then made a pointed accusation about his gods; Jacob answered with a grave pledge."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m3-4','mystery',1,31,33,33,'Genesis 31:33',3,'After searching Jacob''s tent, Leah''s tent and the two maidservants'' tents without finding the images, which tent did Laban enter next?',null,'["The two maidservants'' tents", "Rachel''s tent", "Jacob''s tent", "Laban''s own tent"]'::jsonb,1,'Laban searched Jacob''s tent, Leah''s tent and the two maidservants'' tents without finding the gods, then went out of Leah''s tent and entered into Rachel''s tent (Genesis 31:33).','One wife''s tent had not yet been searched.',null,null,'KJV',array['mystery','Genesis','m3']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Laban went into Jacob’s tent, and into Leah’s tent, and into the two maidservants’ tents; but he found them not. Then went he out of Leah’s tent, and entered into Rachel’s tent.',null,'{"case_title": "The Missing Household Gods", "stage": 4, "stages": 5, "clue": "Search record: Laban went from tent to tent through the camp, finding nothing in the first several he entered."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m3-5','mystery',1,31,34,35,'Genesis 31:34-35',3,'Case solved: where were the missing images during the search?',null,'["Placed in the camel''s furniture, with Rachel sitting upon them", "Buried under the floor of Jacob''s tent", "Hidden among the flocks by the maidservants", "Carried ahead across the river by Leah''s sons"]'::jsonb,0,'Rachel had taken the images, put them in the camel''s furniture, and sat upon them, so Laban searched but found them not (Genesis 31:34-35).','The person who stayed seated during the search is the key.',null,null,'KJV',array['mystery','Genesis','m3']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now Rachel had taken the images, and put them in the camel’s furniture, and sat upon them. And Laban searched all the tent, but found them not. And she said to her father, Let it not displease my lord that I cannot rise up before thee; for the custom of women is upon me. And he searched, but found not the images.',null,'{"case_title": "The Missing Household Gods", "stage": 5, "stages": 5, "clue": "Final detail: Laban searched the entire last tent, yet its occupant stayed seated and asked him not to be displeased that she could not rise."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m2-1','mystery',1,37,3,4,'Genesis 37:3-4',1,'According to the text, why did Israel love Joseph more than all his children and make him this coat?',null,'["Because Joseph was the firstborn son", "Because Joseph was the son of his old age", "Because Joseph had been chosen by the elders", "Because Joseph had saved the family flocks"]'::jsonb,1,'Genesis 37:3 says Israel loved Joseph more than all his children ''because he was the son of his old age: and he made him a coat of many colours.'' Genesis 37:4 adds that his brothers hated him for this favour.','Think about Joseph''s age compared with his father''s age when he was born.',null,null,'KJV',array['mystery','Genesis','m2']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now Israel loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours. And when his brethren saw that their father loved him more than all his brethren, they hated him, and could not speak peaceably unto him.',null,'{"case_title": "The Bloodstained Coat", "stage": 1, "stages": 5, "clue": "Evidence item #1: A coat of many colours, made by the father for the one son he loved more than all his brethren."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m2-2','mystery',1,37,5,8,'Genesis 37:5-8',1,'In Joseph''s first dream, what made obeisance to his sheaf?',null,'["His brothers'' sheaves", "The sun, the moon, and eleven stars", "The flocks of his father", "Seven fat kine"]'::jsonb,0,'In Genesis 37:7 Joseph says his sheaf stood upright and ''your sheaves stood round about, and made obeisance to my sheaf.'' Genesis 37:8 says the brothers hated him yet the more for his dreams and his words.','The brothers were binding something in the field when the dream began.',null,null,'KJV',array['mystery','Genesis','m2']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Joseph dreamed a dream, and he told it his brethren: and they hated him yet the more. And he said unto them, Hear, I pray you, this dream which I have dreamed: For, behold, we were binding sheaves in the field, and, lo, my sheaf arose, and also stood upright; and, behold, your sheaves stood round about, and made obeisance to my sheaf. And his brethren said to him, Shalt thou indeed reign over us? or shalt thou indeed have dominion over us? And they hated him yet the more for his dreams, and for his words.',null,'{"case_title": "The Bloodstained Coat", "stage": 2, "stages": 5, "clue": "Witness statement from a brother: ''He told us his dream about the field, and we hated him yet the more.''"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m2-3','mystery',1,37,14,17,'Genesis 37:14-17',1,'Where did Joseph finally find his brothers?',null,'["In Shechem", "In Beersheba", "In Bethel", "In Dothan"]'::jsonb,3,'Joseph went to Shechem, but a man told him, ''I heard them say, Let us go to Dothan.'' Genesis 37:17 says Joseph ''found them in Dothan.''','His first destination was not his final one; follow the stranger''s directions.',null,null,'KJV',array['mystery','Genesis','m2']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he said to him, Go, I pray thee, see whether it be well with thy brethren, and well with the flocks; and bring me word again. So he sent him out of the vale of Hebron, and he came to Shechem. And a certain man found him, and, behold, he was wandering in the field: and the man asked him, saying, What seekest thou? And he said, I seek my brethren: tell me, I pray thee, where they feed their flocks. And the man said, They are departed hence; for I heard them say, Let us go to Dothan. And Joseph went after his brethren, and found them in Dothan.',null,'{"case_title": "The Bloodstained Coat", "stage": 3, "stages": 5, "clue": "Travel log: Joseph was sent from the vale of Hebron to check on his brothers, but they were not where he expected. A stranger in the field redirected him."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m2-4','mystery',1,37,21,24,'Genesis 37:21-24',1,'Which brother proposed casting Joseph into the pit instead of killing him?',null,'["Levi", "Simeon", "Judah", "Reuben"]'::jsonb,3,'Genesis 37:22 records Reuben saying, ''Shed no blood, but cast him into this pit that is in the wilderness,'' intending to deliver him to his father. Verse 24 notes the pit was empty, with no water in it.','This brother hoped to rescue Joseph and return him to his father.',null,null,'KJV',array['mystery','Genesis','m2']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Reuben heard it, and he delivered him out of their hands; and said, Let us not kill him. And Reuben said unto them, Shed no blood, but cast him into this pit that is in the wilderness, and lay no hand upon him; that he might rid him out of their hands, to deliver him to his father again. And it came to pass, when Joseph was come unto his brethren, that they stript Joseph out of his coat, his coat of many colours that was on him; And they took him, and cast him into a pit: and the pit was empty, there was no water in it.',null,'{"case_title": "The Bloodstained Coat", "stage": 4, "stages": 5, "clue": "Scene report: The coat was stripped from its owner near an empty hole in the wilderness. One brother had urged, ''Shed no blood.''"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m2-5','mystery',1,37,26,33,'Genesis 37:26-33',1,'What really happened to Joseph and the coat?',null,'["The Ishmeelites killed Joseph and left the coat in Dothan", "Joseph was sold for twenty pieces of silver, and his brothers dipped his coat in the blood of a kid of the goats", "Reuben slew Joseph secretly and hid the coat in the pit", "An evil beast killed Joseph in the field and tore his coat"]'::jsonb,1,'Genesis 37:28 says Joseph was lifted out of the pit and sold to the Ishmeelites ''for twenty pieces of silver,'' and verse 31 says the brothers ''killed a kid of the goats, and dipped the coat in the blood.'' Jacob, deceived, concluded in verse 33 that a beast had devoured him.','Whose blood was really on the coat? Judah asked what profit there was in slaying their brother.',null,null,'KJV',array['mystery','Genesis','m2']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Judah said unto his brethren, What profit is it if we slay our brother, and conceal his blood? Come, and let us sell him to the Ishmeelites, and let not our hand be upon him; for he is our brother and our flesh. And his brethren were content. Then there passed by Midianites merchantmen; and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmeelites for twenty pieces of silver: and they brought Joseph into Egypt. And Reuben returned unto the pit; and, behold, Joseph was not in the pit; and he rent his clothes. And he returned unto his brethren, and said, The child is not; and I, whither shall I go? And they took Joseph’s coat, and killed a kid of the goats, and …',null,'{"case_title": "The Bloodstained Coat", "stage": 5, "stages": 5, "clue": "The father''s verdict upon seeing the coat: ''It is my son''s coat; an evil beast hath devoured him.'' But the blood on the coat tells a different story."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m5-1','mystery',6,7,2,5,'Joshua 7:2-5',2,'What happened to the Israelite force that went up against Ai?',null,'["They captured Ai without losing a single man", "They fled before the men of Ai, who smote about thirty and six of them", "They made a peace treaty with the king of Ai", "They besieged Ai for seven days until its walls fell"]'::jsonb,1,'About three thousand men went up, but they fled before the men of Ai, who smote about thirty and six of them, and the people''s hearts melted (Joshua 7:4-5).','The report speaks of retreat and losses, not victory.',null,null,'KJV',array['mystery','Joshua','m5']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Joshua sent men from Jericho to Ai, which is beside Beth-aven, on the east side of Beth-el, and spake unto them, saying, Go up and view the country. And the men went up and viewed Ai. And they returned to Joshua, and said unto him, Let not all the people go up; but let about two or three thousand men go up and smite Ai; and make not all the people to labour thither; for they are but few. So there went up thither of the people about three thousand men: and they fled before the men of Ai. And the men of Ai smote of them about thirty and six men: for they chased them from before the gate even unto Shebarim, and smote them in the going down: wherefore the hearts of the people melted, and …',null,'{"case_title": "The Hidden Plunder", "stage": 1, "stages": 5, "clue": "Field report from Ai: On the spies'' advice that the men of Ai were but few, about three thousand men went up, yet they were chased from before the gate and some were smitten, and the hearts of the people melted, and became as water."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m5-2','mystery',6,7,10,12,'Joshua 7:10-12',2,'According to the LORD, why could Israel not stand before their enemies?',null,'["Israel had taken of the accursed thing, stolen, dissembled, and put it among their own stuff", "Israel had made a golden calf at the foot of the mountain", "Israel had sent too few soldiers against Ai", "Israel had made a covenant with the Gibeonites"]'::jsonb,0,'The LORD said Israel had sinned, taking of the accursed thing, stealing, dissembling, and putting it among their own stuff, therefore they could not stand before their enemies (Joshua 7:11-12).','The problem was something hidden inside the camp, not a lack of soldiers.',null,null,'KJV',array['mystery','Joshua','m5']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the LORD said unto Joshua, Get thee up; wherefore liest thou thus upon thy face? Israel hath sinned, and they have also transgressed my covenant which I commanded them: for they have even taken of the accursed thing, and have also stolen, and dissembled also, and they have put it even among their own stuff. Therefore the children of Israel could not stand before their enemies, but turned their backs before their enemies, because they were accursed: neither will I be with you any more, except ye destroy the accursed from among you.',null,'{"case_title": "The Hidden Plunder", "stage": 2, "stages": 5, "clue": "Statement from the LORD to Joshua, who lay on his face before the ark: ''Get thee up; wherefore liest thou thus upon thy face?''"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m5-3','mystery',6,7,13,14,'Joshua 7:13-14',2,'How did the LORD say the guilty person would be identified?',null,'["Each man would be asked to swear an oath before the priests", "The elders would search every tent in the camp at night", "The guilty one would be struck with leprosy", "The people would be brought by tribes, then families, then households, then man by man, as the LORD took them"]'::jsonb,3,'The LORD commanded that Israel be brought according to their tribes, and the one taken would come by families, then households, then man by man (Joshua 7:14).','Think of a narrowing process, from the largest group down to the individual.',null,null,'KJV',array['mystery','Joshua','m5']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Up, sanctify the people, and say, Sanctify yourselves against to morrow: for thus saith the LORD God of Israel, There is an accursed thing in the midst of thee, O Israel: thou canst not stand before thine enemies, until ye take away the accursed thing from among you. In the morning therefore ye shall be brought according to your tribes: and it shall be, that the tribe which the LORD taketh shall come according to the families thereof; and the family which the LORD shall take shall come by households; and the household which the LORD shall take shall come man by man.',null,'{"case_title": "The Hidden Plunder", "stage": 3, "stages": 5, "clue": "Instruction for the morning: the people are to sanctify themselves, for there is an accursed thing in the midst of Israel."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m5-4','mystery',6,7,16,17,'Joshua 7:16-17',2,'Which tribe and family were taken as the search narrowed?',null,'["The tribe of Judah and the family of the Zarhites", "The tribe of Ephraim and the family of the Shuthelahites", "The tribe of Benjamin and the family of the Matrites", "The tribe of Levi and the family of the Kohathites"]'::jsonb,0,'The tribe of Judah was taken, then the family of the Zarhites, and then Zabdi was taken (Joshua 7:16-17).','This tribe would later be known as the tribe of King David.',null,null,'KJV',array['mystery','Joshua','m5']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'So Joshua rose up early in the morning, and brought Israel by their tribes; and the tribe of Judah was taken: And he brought the family of Judah; and he took the family of the Zarhites: and he brought the family of the Zarhites man by man; and Zabdi was taken:',null,'{"case_title": "The Hidden Plunder", "stage": 4, "stages": 5, "clue": "Early morning record: Joshua rose up early and brought Israel by their tribes, narrowing the search step by step."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m5-5','mystery',6,7,18,21,'Joshua 7:18-21',2,'Case solved: who took the hidden plunder, and what did he take?',null,'["Joshua''s servant, who took the crown of the king of Jericho", "Carmi, who took cattle and sheep from the spoil of Ai", "Zabdi, who took the golden vessels of the house of the LORD", "Achan son of Carmi, who took a goodly Babylonish garment, two hundred shekels of silver, and a wedge of gold of fifty shekels weight"]'::jsonb,3,'Achan son of Carmi was taken, and he confessed that he coveted and took a Babylonish garment, two hundred shekels of silver, and a wedge of gold, hiding them in the earth in his tent (Joshua 7:18, 21).','The man taken was the grandson of the one taken in the previous stage.',null,null,'KJV',array['mystery','Joshua','m5']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he brought his household man by man; and Achan, the son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, was taken. And Joshua said unto Achan, My son, give, I pray thee, glory to the LORD God of Israel, and make confession unto him; and tell me now what thou hast done; hide it not from me. And Achan answered Joshua, and said, Indeed I have sinned against the LORD God of Israel, and thus and thus have I done: When I saw among the spoils a goodly Babylonish garment, and two hundred shekels of silver, and a wedge of gold of fifty shekels weight, then I coveted them, and took them; and, behold, they are hid in the earth in the midst of my tent, and the silver under it.',null,'{"case_title": "The Hidden Plunder", "stage": 5, "stages": 5, "clue": "Confession recorded before Joshua: ''When I saw among the spoils... then I coveted them, and took them.''"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m10-1','mystery',44,5,1,2,'Acts 5:1-2',3,'According to the text, what did Ananias do with the money from the sale?',null,'["He gave the entire price to the poor in the streets", "He refused to sell the possession at all", "He kept back part of the price and laid a certain part at the apostles'' feet", "He gave the whole price to Sapphira to manage"]'::jsonb,2,'Acts 5:1-2 says Ananias, with Sapphira, sold a possession, kept back part of the price with his wife being privy to it, and laid a certain part at the apostles'' feet.','Look at how much of the price actually arrived at the apostles'' feet.',null,null,'KJV',array['mystery','Acts','m10']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But a certain man named Ananias, with Sapphira his wife, sold a possession, And kept back part of the price, his wife also being privy to it, and brought a certain part, and laid it at the apostles’ feet.',null,'{"case_title": "The Price of the Land", "stage": 1, "stages": 5, "clue": "Ledger note: A man and his wife sold a possession. Only part of the money ever reached the apostles'' feet, and the wife was aware of it."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m10-2','mystery',44,5,3,4,'Acts 5:3-4',3,'According to Peter, what was true about the land and the money, and to whom had Ananias lied?',null,'["The land belonged to the apostles, and he lied to the elders", "The money belonged to the temple, and he lied to the priests", "He was required to give everything, and he lied only to his wife", "The land and money were his own and in his power, and he lied not unto men but unto God"]'::jsonb,3,'In Acts 5:3-4 Peter says the land was Ananias''s own and the price was in his own power, yet he had lied to the Holy Ghost: ''thou hast not lied unto men, but unto God.''','Peter asks two questions about ownership before naming the one who was lied to.',null,null,'KJV',array['mystery','Acts','m10']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But Peter said, Ananias, why hath Satan filled thine heart to lie to the Holy Ghost, and to keep back part of the price of the land? Whiles it remained, was it not thine own? and after it was sold, was it not in thine own power? why hast thou conceived this thing in thine heart? thou hast not lied unto men, but unto God.',null,'{"case_title": "The Price of the Land", "stage": 2, "stages": 5, "clue": "Witness statement (Peter): ''Whiles it remained, was it not thine own?'' The questioning then turns to whom the lie was really told."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m10-3','mystery',44,5,5,6,'Acts 5:5-6',3,'What happened to Ananias after he heard Peter''s words?',null,'["He fled the city before anyone could stop him", "He fell down and gave up the ghost, and the young men carried him out and buried him", "He was put in prison by the council", "He repented and was restored to the church"]'::jsonb,1,'Acts 5:5-6 records that Ananias fell down and gave up the ghost, great fear came on all who heard, and the young men wound him up, carried him out, and buried him.','Notice both what happened to him and who arose afterward.',null,null,'KJV',array['mystery','Acts','m10']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Ananias hearing these words fell down, and gave up the ghost: and great fear came on all them that heard these things. And the young men arose, wound him up, and carried him out, and buried him.',null,'{"case_title": "The Price of the Land", "stage": 3, "stages": 5, "clue": "Coroner''s note: The first subject collapsed immediately upon hearing Peter''s words. Certain men of the congregation handled the burial."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m10-4','mystery',44,5,7,8,'Acts 5:7-8',3,'How did Sapphira answer when Peter asked whether they sold the land for so much?',null,'["She said she did not know the price", "She said her husband had sold it without her knowledge", "She said, ''Yea, for so much''", "She confessed that they had kept back part"]'::jsonb,2,'Acts 5:7-8 says that about three hours later Sapphira, not knowing what was done, came in, and when Peter asked about the price she answered, ''Yea, for so much.''','Her answer echoes Peter''s own words back to him.',null,null,'KJV',array['mystery','Acts','m10']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And it was about the space of three hours after, when his wife, not knowing what was done, came in. And Peter answered unto her, Tell me whether ye sold the land for so much? And she said, Yea, for so much.',null,'{"case_title": "The Price of the Land", "stage": 4, "stages": 5, "clue": "Timeline entry: Some hours later the wife entered, unaware of what had happened. Peter asked her a single question about the sale price."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m10-5','mystery',44,5,9,11,'Acts 5:9-11',3,'Solution: What does the text say really happened with Ananias and Sapphira?',null,'["They had agreed together to tempt the Spirit of the Lord; she also fell down dead and was buried beside her husband, and great fear came upon all the church", "They returned the hidden money, and the matter was quietly settled", "Sapphira alone planned the deception, and Ananias knew nothing of it", "The apostles wrongly accused them, and the church was ashamed"]'::jsonb,0,'In Acts 5:9-11 Peter asks Sapphira how they had agreed together to tempt the Spirit of the Lord. She fell down and yielded up the ghost, and the young men carried her forth and buried her by (beside) her husband. Great fear came upon all the church and upon as many as heard these things.','Peter''s question shows whether the couple acted alone or jointly.',null,null,'KJV',array['mystery','Acts','m10']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then Peter said unto her, How is it that ye have agreed together to tempt the Spirit of the Lord? behold, the feet of them which have buried thy husband are at the door, and shall carry thee out. Then fell she down straightway at his feet, and yielded up the ghost: and the young men came in, and found her dead, and, carrying her forth, buried her by her husband. And great fear came upon all the church, and upon as many as heard these things.',null,'{"case_title": "The Price of the Land", "stage": 5, "stages": 5, "clue": "Final report: Peter told her the feet of those who buried her husband were at the door. Afterward the whole church was affected."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m8-1','mystery',27,5,1,4,'Daniel 5:1-4',3,'According to the record, where had the vessels used at Belshazzar''s feast come from?',null,'["The royal workshops of Babylon, made for this feast", "The temple of the house of God at Jerusalem, taken by Nebuchadnezzar", "The temple of Bel, brought in by the Chaldean priests", "The treasury of the Medes and Persians, received as tribute"]'::jsonb,1,'Belshazzar ordered the golden and silver vessels that his father Nebuchadnezzar had taken out of the temple in Jerusalem, and the guests drank from them while praising gods of gold, silver, brass, iron, wood and stone (Daniel 5:1-4).','The text names the city these cups were taken from and the king who took them.',null,null,'KJV',array['mystery','Daniel','m8']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Belshazzar the king made a great feast to a thousand of his lords, and drank wine before the thousand. Belshazzar, whiles he tasted the wine, commanded to bring the golden and silver vessels which his father Nebuchadnezzar had taken out of the temple which was in Jerusalem; that the king, and his princes, his wives, and his concubines, might drink therein. Then they brought the golden vessels that were taken out of the temple of the house of God which was at Jerusalem; and the king, and his princes, his wives, and his concubines, drank in them. They drank wine, and praised the gods of gold, and of silver, of brass, of iron, of wood, and of stone.',null,'{"case_title": "The Writing on the Wall", "stage": 1, "stages": 5, "clue": "Evidence from the banquet hall: at a great feast for a thousand lords, the king commanded that certain golden and silver vessels be brought in, and he, his princes, his wives and his concubines drank wine from them."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m8-2','mystery',27,5,5,6,'Daniel 5:5-6',3,'What did the king see appear in the palace that same hour?',null,'["An angel standing beside the candlestick with a drawn sword", "A voice from heaven that spoke the words aloud to all the lords", "A burning scroll that fell onto the king''s table", "Fingers of a man''s hand writing upon the plaister of the wall"]'::jsonb,3,'Fingers of a man''s hand came forth and wrote over against the candlestick on the plaister of the palace wall, and the king saw the part of the hand that wrote and was badly shaken (Daniel 5:5-6).','The king saw only part of something, and it was writing.',null,null,'KJV',array['mystery','Daniel','m8']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'In the same hour came forth fingers of a man’s hand, and wrote over against the candlestick upon the plaister of the wall of the king’s palace: and the king saw the part of the hand that wrote. Then the king’s countenance was changed, and his thoughts troubled him, so that the joints of his loins were loosed, and his knees smote one against another.',null,'{"case_title": "The Writing on the Wall", "stage": 2, "stages": 5, "clue": "Witness statement: ''The king saw it near the candlestick. His face changed, and his knees knocked together.''"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m8-3','mystery',27,5,10,12,'Daniel 5:10-12',3,'Who came into the banquet house and told the king about a man in whom was ''the spirit of the holy gods''?',null,'["The chief of the astrologers", "Darius the Median", "One of the king''s concubines", "The queen"]'::jsonb,3,'The queen came into the banquet house, recalled how Daniel, whom the king named Belteshazzar, had shown light, understanding and wisdom, and advised that he be called to give the interpretation (Daniel 5:10-12).','This person came in because of the king''s and his lords'' words, and remembered Daniel from Nebuchadnezzar''s days.',null,null,'KJV',array['mystery','Daniel','m8']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now the queen, by reason of the words of the king and his lords, came into the banquet house: and the queen spake and said, O king, live for ever: let not thy thoughts trouble thee, nor let thy countenance be changed: There is a man in thy kingdom, in whom is the spirit of the holy gods; and in the days of thy father light and understanding and wisdom, like the wisdom of the gods, was found in him; whom the king Nebuchadnezzar thy father, the king, I say, thy father, made master of the magicians, astrologers, Chaldeans, and soothsayers; Forasmuch as an excellent spirit, and knowledge, and understanding, interpreting of dreams, and shewing of hard sentences, and dissolving of doubts, were …',null,'{"case_title": "The Writing on the Wall", "stage": 3, "stages": 5, "clue": "The king''s astrologers and soothsayers have failed to read the writing. Then someone enters the banquet house with a recommendation."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m8-4','mystery',27,5,22,23,'Daniel 5:22-23',3,'What charge did Daniel bring against Belshazzar?',null,'["He had refused to pay the wise men of Babylon for their service", "He had thrown Daniel''s friends into a fiery furnace", "He had broken a treaty with the Medes and Persians", "He had not humbled his heart, though he knew all this, but had lifted himself up against the Lord of heaven"]'::jsonb,3,'Daniel said Belshazzar had not humbled his heart, though he knew all this, but had lifted himself up against the Lord of heaven by drinking from His vessels and praising idols while not glorifying the God who held his breath (Daniel 5:22-23).','Consider what Belshazzar did with the vessels and whom he praised.',null,null,'KJV',array['mystery','Daniel','m8']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And thou his son, O Belshazzar, hast not humbled thine heart, though thou knewest all this; But hast lifted up thyself against the Lord of heaven; and they have brought the vessels of his house before thee, and thou, and thy lords, thy wives, and thy concubines, have drunk wine in them; and thou hast praised the gods of silver, and gold, of brass, iron, wood, and stone, which see not, nor hear, nor know: and the God in whose hand thy breath is, and whose are all thy ways, hast thou not glorified:',null,'{"case_title": "The Writing on the Wall", "stage": 4, "stages": 5, "clue": "Daniel turns down the king''s gifts, then recounts what happened to Nebuchadnezzar before he addresses Belshazzar directly."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m8-5','mystery',27,5,25,31,'Daniel 5:25-31',3,'Case solved: what did the writing announce, and what really happened?',null,'["The king would reign forty more years if he repented; he did, and Babylon was spared", "The kingdom would be divided among Belshazzar''s sons; Daniel was made king", "The king was weighed in the balances and found wanting; that night Belshazzar was slain and Darius the Median took the kingdom", "The wise men would be destroyed; Belshazzar had them executed the next morning"]'::jsonb,2,'Daniel interpreted the writing: the kingdom was numbered and finished, the king was weighed in the balances and found wanting, and the kingdom was divided and given to the Medes and Persians. In that night Belshazzar was slain, and Darius the Median took the kingdom (Daniel 5:25-31).','TEKEL concerns a measurement, and the fulfilment came very quickly.',null,null,'KJV',array['mystery','Daniel','m8']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And this is the writing that was written, MENE, MENE, TEKEL, UPHARSIN. This is the interpretation of the thing: MENE; God hath numbered thy kingdom, and finished it. TEKEL; Thou art weighed in the balances, and art found wanting. PERES; Thy kingdom is divided, and given to the Medes and Persians. Then commanded Belshazzar, and they clothed Daniel with scarlet, and put a chain of gold about his neck, and made a proclamation concerning him, that he should be the third ruler in the kingdom. In that night was Belshazzar the king of the Chaldeans slain. …',null,'{"case_title": "The Writing on the Wall", "stage": 5, "stages": 5, "clue": "The final report reads MENE, MENE, TEKEL, UPHARSIN. A note at the bottom of the file adds: ''In that night...''"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m9-1','mystery',40,26,14,16,'Matthew 26:14-16',2,'For what price did Judas Iscariot covenant with the chief priests?',null,'["Three hundred pence", "Fifty shekels of gold", "A field outside Jerusalem", "Thirty pieces of silver"]'::jsonb,3,'Judas went to the chief priests and ''they covenanted with him for thirty pieces of silver,'' after which he sought opportunity to betray Jesus (Matthew 26:14-16).','The sum was a number of pieces of a precious metal, but not gold.',null,null,'KJV',array['mystery','Matthew','m9']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then one of the twelve, called Judas Iscariot, went unto the chief priests, And said unto them, What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver. And from that time he sought opportunity to betray him.',null,'{"case_title": "The Betrayer at the Table", "stage": 1, "stages": 5, "clue": "A record from the chief priests'' meeting: one of the twelve came asking, ''What will ye give me, and I will deliver him unto you?'' A sum was agreed upon."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m9-2','mystery',40,26,21,25,'Matthew 26:21-25',2,'When Judas asked, ''Master, is it I?'', how did Jesus answer him?',null,'["He gave no answer at all.", "\"Not thou, but another.\"", "\"Ask Peter.\"", "\"Thou hast said.\""]'::jsonb,3,'When Judas, ''which betrayed him,'' asked ''Master, is it I?'', Jesus replied, ''Thou hast said'' (Matthew 26:25).','Jesus answered with a brief phrase that turned Judas''s own words back to him.',null,null,'KJV',array['mystery','Matthew','m9']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And as they did eat, he said, Verily I say unto you, that one of you shall betray me. And they were exceeding sorrowful, and began every one of them to say unto him, Lord, is it I? And he answered and said, He that dippeth his hand with me in the dish, the same shall betray me. The Son of man goeth as it is written of him: but woe unto that man by whom the Son of man is betrayed! it had been good for that man if he had not been born. Then Judas, which betrayed him, answered and said, Master, is it I? He said unto him, Thou hast said.',null,'{"case_title": "The Betrayer at the Table", "stage": 2, "stages": 5, "clue": "Witness statement from the table: ''As we were eating, the Master said one of us would betray him. We were exceeding sorrowful, and each began to ask him a question.''"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m9-3','mystery',43,13,21,26,'John 13:21-26',2,'What sign did Jesus say would identify the one who would betray him?',null,'["The one to whom he would give a sop after dipping it", "The one who would leave the room first", "The one who refused to have his feet washed", "The one sitting at his right hand"]'::jsonb,0,'Jesus said, ''He it is, to whom I shall give a sop, when I have dipped it,'' and he gave the sop to Judas Iscariot, the son of Simon (John 13:26).','Watch what Jesus handed across the table.',null,null,'KJV',array['mystery','John','m9']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'When Jesus had thus said, he was troubled in spirit, and testified, and said, Verily, verily, I say unto you, that one of you shall betray me. Then the disciples looked one on another, doubting of whom he spake. Now there was leaning on Jesus’ bosom one of his disciples, whom Jesus loved. Simon Peter therefore beckoned to him, that he should ask who it should be of whom he spake. He then lying on Jesus’ breast saith unto him, Lord, who is it? Jesus answered, He it is, to whom I shall give a sop, when I have dipped it. And when he had dipped the sop, he gave it to Judas Iscariot, the son of Simon.',null,'{"case_title": "The Betrayer at the Table", "stage": 3, "stages": 5, "clue": "Seating detail: the disciple whom Jesus loved was leaning on Jesus'' bosom. Simon Peter beckoned to him to ask who the betrayer was."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m9-4','mystery',43,13,27,30,'John 13:27-30',2,'Why did some of the disciples think Judas was leaving?',null,'["They thought he was going to fetch more wine for the table", "They thought he was going to bring Mary and Martha", "Because he had the bag, they thought he was sent to buy things for the feast or give to the poor", "They thought he was going to prepare the upper room"]'::jsonb,2,'Some thought, ''because Judas had the bag,'' that Jesus had told him to buy what was needed for the feast or to give something to the poor; Judas went out, ''and it was night'' (John 13:29-30).','Consider what Judas was responsible for carrying among the disciples.',null,null,'KJV',array['mystery','John','m9']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And after the sop Satan entered into him. Then said Jesus unto him, That thou doest, do quickly. Now no man at the table knew for what intent he spake this unto him. For some of them thought, because Judas had the bag, that Jesus had said unto him, Buy those things that we have need of against the feast; or, that he should give something to the poor. He then having received the sop went immediately out: and it was night.',null,'{"case_title": "The Betrayer at the Table", "stage": 4, "stages": 5, "clue": "After Jesus told Judas, ''That thou doest, do quickly,'' none at the table understood the remark. Judas went out immediately."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m9-5','mystery',40,26,47,50,'Matthew 26:47-50',2,'Case solved: what sign did Judas use to deliver Jesus to the multitude?',null,'["He embraced Peter so the soldiers would know the group", "He placed the thirty pieces of silver at Jesus'' feet", "He pointed at Jesus and called out his name", "He greeted Jesus with ''Hail, master'' and kissed him"]'::jsonb,3,'Judas had told them, ''Whomsoever I shall kiss, that same is he: hold him fast,'' and he came to Jesus, said ''Hail, master; and kissed him'' (Matthew 26:48-49).','The signal was a greeting normally given as a sign of friendship.',null,null,'KJV',array['mystery','Matthew','m9']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And while he yet spake, lo, Judas, one of the twelve, came, and with him a great multitude with swords and staves, from the chief priests and elders of the people. Now he that betrayed him gave them a sign, saying, Whomsoever I shall kiss, that same is he: hold him fast. And forthwith he came to Jesus, and said, Hail, master; and kissed him. And Jesus said unto him, Friend, wherefore art thou come? Then came they, and laid hands on Jesus, and took him.',null,'{"case_title": "The Betrayer at the Table", "stage": 5, "stages": 5, "clue": "Garden report: a great multitude with swords and staves arrived from the chief priests and elders. Their guide had arranged a signal beforehand so they would seize the right man."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m11-1','mystery',44,12,1,4,'Acts 12:1-4',2,'According to the record, why did Herod proceed to take Peter as well?',null,'["Because Peter had insulted him in the temple", "Because Peter had tried to free James", "Because he saw it pleased the Jews", "Because the Roman governor ordered it"]'::jsonb,2,'Acts 12:3 states that because Herod saw that killing James pleased the Jews, he proceeded further to take Peter also. He then imprisoned him under four quaternions of soldiers (Acts 12:4).','Look at Herod''s reaction to how people responded to the death of James.',null,null,'KJV',array['mystery','Acts','m11']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now about that time Herod the king stretched forth his hands to vex certain of the church. And he killed James the brother of John with the sword. And because he saw it pleased the Jews, he proceeded further to take Peter also. (Then were the days of unleavened bread.) And when he had apprehended him, he put him in prison, and delivered him to four quaternions of soldiers to keep him; intending after Easter to bring him forth to the people.',null,'{"case_title": "The Prisoner Who Walked Free", "stage": 1, "stages": 5, "clue": "Court record: King Herod has already killed James the brother of John with the sword. Shortly afterward, during the days of unleavened bread, he orders a second arrest."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m11-2','mystery',44,12,5,6,'Acts 12:5-6',2,'How was Peter being held that night?',null,'["Sleeping between two soldiers, bound with two chains", "Alone in a pit sealed with a stone", "Standing in stocks in the inner prison", "Locked in a tower with no guards inside"]'::jsonb,0,'Acts 12:6 records that Peter was sleeping between two soldiers, bound with two chains, while keepers before the door kept the prison. Meanwhile, Acts 12:5 notes the church prayed without ceasing for him.','The record mentions a pair of soldiers and a pair of restraints.',null,null,'KJV',array['mystery','Acts','m11']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Peter therefore was kept in prison: but prayer was made without ceasing of the church unto God for him. And when Herod would have brought him forth, the same night Peter was sleeping between two soldiers, bound with two chains: and the keepers before the door kept the prison.',null,'{"case_title": "The Prisoner Who Walked Free", "stage": 2, "stages": 5, "clue": "Guard report: On the night before Herod planned to bring the prisoner out, the cell was under full watch, with keepers stationed before the door."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m11-3','mystery',44,12,7,10,'Acts 12:7-10',2,'What happened when Peter and his escort reached the iron gate leading to the city?',null,'["A sympathetic guard unlocked it", "It opened to them of his own accord", "Peter broke the lock with his chains", "They climbed over it with a rope"]'::jsonb,1,'Acts 12:10 says the iron gate that leads to the city opened to them of his own accord. Then they passed through one street, and the angel departed from Peter.','No human hand is mentioned at the gate.',null,null,'KJV',array['mystery','Acts','m11']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And, behold, the angel of the Lord came upon him, and a light shined in the prison: and he smote Peter on the side, and raised him up, saying, Arise up quickly. And his chains fell off from his hands. And the angel said unto him, Gird thyself, and bind on thy sandals. And so he did. And he saith unto him, Cast thy garment about thee, and follow me. And he went out, and followed him; and wist not that it was true which was done by the angel; but thought he saw a vision. When they were past the first and the second ward, they came unto the iron gate that leadeth unto the city; which opened to them of his own accord: and they went out, and passed on through one street; and forthwith the angel …',null,'{"case_title": "The Prisoner Who Walked Free", "stage": 3, "stages": 5, "clue": "Scene evidence: A light shined in the prison, Peter''s chains fell off from his hands, and he and the angel passed the first and the second ward."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m11-4','mystery',44,12,12,16,'Acts 12:12-16',2,'Who was this witness, and at whose house did it happen?',null,'["Lydia, at the house of Simon the tanner", "Priscilla, at the house of Jason", "Dorcas, at the house of Cornelius", "Rhoda, at the house of Mary the mother of John Mark"]'::jsonb,3,'Acts 12:12-13 identifies the house of Mary the mother of John whose surname was Mark, and the damsel named Rhoda. For gladness she did not open the gate but ran in to tell that Peter stood there (Acts 12:14).','The house belonged to the mother of a man whose surname was Mark.',null,null,'KJV',array['mystery','Acts','m11']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And when he had considered the thing, he came to the house of Mary the mother of John, whose surname was Mark; where many were gathered together praying. And as Peter knocked at the door of the gate, a damsel came to hearken, named Rhoda. And when she knew Peter’s voice, she opened not the gate for gladness, but ran in, and told how Peter stood before the gate. And they said unto her, Thou art mad. But she constantly affirmed that it was even so. Then said they, It is his angel. But Peter continued knocking: and when they had opened the door, and saw him, they were astonished.',null,'{"case_title": "The Prisoner Who Walked Free", "stage": 4, "stages": 5, "clue": "Witness statement: A young woman at a house where many were gathered praying heard a familiar voice knocking at the gate, but she ran inside instead of opening it."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m11-5','mystery',44,12,17,17,'Acts 12:17',2,'Case solution: according to Peter''s own declaration, how did he get out of prison?',null,'["The Lord had brought him out of the prison", "The church members bribed the keepers", "He slipped his chains and escaped by his own strength", "Herod quietly released him to avoid a riot"]'::jsonb,0,'Acts 12:17 records that Peter declared to them how the Lord had brought him out of the prison. He then told them to show these things to James and to the brethren.','Peter credits neither himself nor any human helper.',null,null,'KJV',array['mystery','Acts','m11']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But he, beckoning unto them with the hand to hold their peace, declared unto them how the Lord had brought him out of the prison. And he said, Go shew these things unto James, and to the brethren. And he departed, and went into another place.',null,'{"case_title": "The Prisoner Who Walked Free", "stage": 5, "stages": 5, "clue": "Final testimony: Once inside, Peter beckoned the astonished gathering to hold their peace and gave his own account before departing to another place."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m12-1','mystery',17,3,1,6,'Esther 3:1-6',4,'According to the text, what did Haman seek to do after learning that Mordecai would not bow to him?',null,'["Have Mordecai alone quietly removed from the king''s gate", "Petition the king to promote Mordecai in his place", "Banish Mordecai and his household from Shushan", "Destroy all the Jews throughout the kingdom"]'::jsonb,3,'When Mordecai ''bowed not, nor did him reverence,'' Haman was ''full of wrath'' and ''sought to destroy all the Jews that were throughout the whole kingdom of Ahasuerus'' (Esther 3:2-6).','Haman thought scorn to lay hands on just one man.',null,null,'KJV',array['mystery','Esther','m12']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'After these things did king Ahasuerus promote Haman the son of Hammedatha the Agagite, and advanced him, and set his seat above all the princes that were with him. And all the king’s servants, that were in the king’s gate, bowed, and reverenced Haman: for the king had so commanded concerning him. But Mordecai bowed not, nor did him reverence. Then the king’s servants, which were in the king’s gate, said unto Mordecai, Why transgressest thou the king’s commandment? Now it came to pass, when they spake daily unto him, and he hearkened not unto them, that they told Haman, to see whether Mordecai’s matters would stand: for he had told them that he was a Jew. And when Haman saw that Mordecai …',null,'{"case_title": "The Plot Against the Queen''s People", "stage": 1, "stages": 5, "clue": "Witness statement from the king''s servants at the gate: ''All of us bowed to the newly promoted official as the king commanded, but one man refused day after day. He had told us he was a Jew.''"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m12-2','mystery',17,3,7,11,'Esther 3:7-11',4,'To which month did the lot, called Pur, fall for carrying out the plot?',null,'["The tenth month, Tebeth", "The third month, Sivan", "The twelfth month, Adar", "The first month, Nisan"]'::jsonb,2,'They cast ''Pur, that is, the lot, before Haman from day to day, and from month to month, to the twelfth month, that is, the month Adar'' (Esther 3:7).','The lot was cast before Haman in Nisan, but it did not settle on that month.',null,null,'KJV',array['mystery','Esther','m12']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'In the first month, that is, the month Nisan, in the twelfth year of king Ahasuerus, they cast Pur, that is, the lot, before Haman from day to day, and from month to month, to the twelfth month, that is, the month Adar. And Haman said unto king Ahasuerus, There is a certain people scattered abroad and dispersed among the people in all the provinces of thy kingdom; and their laws are diverse from all people; neither keep they the king’s laws: therefore it is not for the king’s profit to suffer them. If it please the king, let it be written that they may be destroyed: and I will pay ten thousand talents of silver to the hands of those that have the charge of the business, to bring it into the …',null,'{"case_title": "The Plot Against the Queen''s People", "stage": 2, "stages": 5, "clue": "In the first month, Nisan, in the twelfth year of king Ahasuerus, Pur (the lot) was cast before Haman from day to day and from month to month until it settled on a particular month."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m12-3','mystery',17,4,10,17,'Esther 4:10-17',4,'How long did Esther say it had been since she was called to come in unto the king?',null,'["Thirty days", "Seven days", "Three days", "Twelve months"]'::jsonb,0,'Esther explained that only those to whom the king held out ''the golden sceptre'' would live, and ''I have not been called to come in unto the king these thirty days'' (Esther 4:11).','The number Esther gives is longer than the fast she later calls for.',null,null,'KJV',array['mystery','Esther','m12']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Again Esther spake unto Hatach, and gave him commandment unto Mordecai; All the king’s servants, and the people of the king’s provinces, do know, that whosoever, whether man or woman, shall come unto the king into the inner court, who is not called, there is one law of his to put him to death, except such to whom the king shall hold out the golden sceptre, that he may live: but I have not been called to come in unto the king these thirty days. And they told to Mordecai Esther’s words. Then Mordecai commanded to answer Esther, Think not with thyself that thou shalt escape in the king’s house, more than all the Jews. For if thou altogether holdest thy peace at this time, then shall there …',null,'{"case_title": "The Plot Against the Queen''s People", "stage": 3, "stages": 5, "clue": "Message carried by Hatach from the queen to Mordecai: ''Whosoever shall come unto the king into the inner court, who is not called, there is one law of his to put him to death.''"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m12-4','mystery',17,5,9,14,'Esther 5:9-14',4,'How high did Zeresh and Haman''s friends say the gallows should be made?',null,'["Thirty cubits", "A hundred cubits", "Twenty cubits", "Fifty cubits"]'::jsonb,3,'Zeresh his wife and all his friends said, ''Let a gallows be made of fifty cubits high,'' and ''he caused the gallows to be made'' (Esther 5:14).','The same figure appears again when a chamberlain points out the gallows in Haman''s house.',null,null,'KJV',array['mystery','Esther','m12']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then went Haman forth that day joyful and with a glad heart: but when Haman saw Mordecai in the king’s gate, that he stood not up, nor moved for him, he was full of indignation against Mordecai. Nevertheless Haman refrained himself: and when he came home, he sent and called for his friends, and Zeresh his wife. And Haman told them of the glory of his riches, and the multitude of his children, and all the things wherein the king had promoted him, and how he had advanced him above the princes and servants of the king. Haman said moreover, Yea, Esther the queen did let no man come in with the king unto the banquet that she had prepared but myself; and to morrow am I invited unto her also with …',null,'{"case_title": "The Plot Against the Queen''s People", "stage": 4, "stages": 5, "clue": "Overheard at Haman''s house after the queen''s banquet: his wife and friends urged him to have a gallows made, and on the morrow to speak to the king that Mordecai might be hanged on it."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('mys-m12-5','mystery',17,7,3,10,'Esther 7:3-10',4,'Whom did Esther name as the adversary, and what became of him?',null,'["Harbonah, who was removed from the king''s chamberlains", "Bigthan, who was hanged for conspiring against the king", "Mordecai, who was sent away from the king''s gate", "Haman, who was hanged on the gallows he had prepared for Mordecai"]'::jsonb,3,'Esther said, ''The adversary and enemy is this wicked Haman,'' and ''they hanged Haman on the gallows that he had prepared for Mordecai'' (Esther 7:6, 10).','The man who built the gallows met it himself.',null,null,'KJV',array['mystery','Esther','m12']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then Esther the queen answered and said, If I have found favour in thy sight, O king, and if it please the king, let my life be given me at my petition, and my people at my request: For we are sold, I and my people, to be destroyed, to be slain, and to perish. But if we had been sold for bondmen and bondwomen, I had held my tongue, although the enemy could not countervail the king’s damage. Then the king Ahasuerus answered and said unto Esther the queen, Who is he, and where is he, that durst presume in his heart to do so? And Esther said, The adversary and enemy is this wicked Haman. Then Haman was afraid before the king and the queen. And the king arising from the banquet of wine in his …',null,'{"case_title": "The Plot Against the Queen''s People", "stage": 5, "stages": 5, "clue": "At the second banquet the queen begs for her life and her people''s, saying they are sold to be destroyed. The king demands to know who durst presume in his heart to do so."}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p1-1','parables',40,13,4,4,'Matthew 13:4',1,'In the parable, what happened to the seeds that fell by the way side?',null,'["The sun scorched them", "The fowls came and devoured them up", "They brought forth thirtyfold", "The thorns choked them"]'::jsonb,1,'Matthew 13:4 says some seeds fell by the way side, "and the fowls came and devoured them up."','Think of creatures that would find seed lying on a hard path.',null,null,'KJV',array['parables','Matthew','p1']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And when he sowed, some seeds fell by the way side, and the fowls came and devoured them up:',null,'{"parable_title": "The Sower"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p1-2','parables',40,13,5,6,'Matthew 13:5-6',1,'Why did the seeds on stony places wither away?',null,'["Because the thorns sprung up", "Because they had no root", "Because the fowls ate them", "Because the sower stopped watering them"]'::jsonb,1,'Matthew 13:5-6 says these seeds sprang up quickly but were scorched when the sun was up, "and because they had no root, they withered away."','The text notes they lacked deepness of earth; what could not grow down into it?',null,null,'KJV',array['parables','Matthew','p1']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Some fell upon stony places, where they had not much earth: and forthwith they sprung up, because they had no deepness of earth: And when the sun was up, they were scorched; and because they had no root, they withered away.',null,'{"parable_title": "The Sower"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p1-3','parables',40,13,19,19,'Matthew 13:19',2,'In his explanation, what does Jesus say happens when someone hears the word of the kingdom and understands it not?',null,'["The wicked one catches away what was sown in his heart", "He receives it with joy for a while", "He bears fruit an hundredfold", "The care of this world chokes it"]'::jsonb,0,'Matthew 13:19 says that when one hears and understands not, "then cometh the wicked one, and catcheth away that which was sown in his heart," which is the seed by the way side.','Think of the seed that fell by the way side, where the fowls came and devoured it.',null,null,'KJV',array['parables','Matthew','p1']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'When any one heareth the word of the kingdom, and understandeth it not, then cometh the wicked one, and catcheth away that which was sown in his heart. This is he which received seed by the way side.',null,'{"parable_title": "The Sower"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p1-4','parables',40,13,22,22,'Matthew 13:22',3,'According to Jesus'' explanation, what chokes the word in the one who received seed among the thorns?',null,'["The wicked one", "Lack of deepness of earth", "The care of this world, and the deceitfulness of riches", "Tribulation or persecution"]'::jsonb,2,'Matthew 13:22 says that for the one who received seed among the thorns, "the care of this world, and the deceitfulness of riches, choke the word, and he becometh unfruitful."','Tribulation is linked to the stony places; the thorns stand for two other pressures Jesus names.',null,null,'KJV',array['parables','Matthew','p1']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He also that received seed among the thorns is he that heareth the word; and the care of this world, and the deceitfulness of riches, choke the word, and he becometh unfruitful.',null,'{"parable_title": "The Sower"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p6-1','parables',40,7,24,24,'Matthew 7:24',1,'In the parable, where did the wise man build his house?',null,'["On top of a high hill", "Upon a rock", "Upon the sand", "Beside a river"]'::jsonb,1,'Jesus likens the obedient hearer to "a wise man, which built his house upon a rock" (Matthew 7:24).','Think of the firmest foundation a builder could choose.',null,null,'KJV',array['parables','Matthew','p6']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Therefore whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man, which built his house upon a rock:',null,'{"parable_title": "The Wise and Foolish Builders"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p6-2','parables',40,7,26,27,'Matthew 7:26-27',1,'When the rain, floods, and winds beat upon the foolish man''s house, what happened to it?',null,'["It stood firm because the storm passed it by", "It fell, and great was the fall of it", "It was damaged only slightly and then repaired", "The foolish man moved it to a safer place"]'::jsonb,1,'The foolish man built "upon the sand," and when the storm beat upon his house "it fell: and great was the fall of it" (Matthew 7:26-27).','Compare its outcome with the house in verse 25, which "fell not."',null,null,'KJV',array['parables','Matthew','p6']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And every one that heareth these sayings of mine, and doeth them not, shall be likened unto a foolish man, which built his house upon the sand: And the rain descended, and the floods came, and the winds blew, and beat upon that house; and it fell: and great was the fall of it.',null,'{"parable_title": "The Wise and Foolish Builders"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p6-3','parables',40,7,24,24,'Matthew 7:24',2,'According to Jesus, whom is he likening to the wise man who built on the rock?',null,'["Whoever hears his sayings and does them", "Whoever builds the largest house", "Whoever teaches the law as the scribes do", "Whoever hears his sayings but does not do them"]'::jsonb,0,'Jesus says, "whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man" (Matthew 7:24).','Both builders heard; the difference lies in what came next.',null,null,'KJV',array['parables','Matthew','p6']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Therefore whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man, which built his house upon a rock:',null,'{"parable_title": "The Wise and Foolish Builders"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p6-4','parables',40,7,28,29,'Matthew 7:28-29',3,'When Jesus ended these sayings, the people were astonished at his doctrine. What reason does the narrator give for their astonishment?',null,'["For he spoke to them only in parables", "For he taught them in the synagogue on the sabbath", "For he taught them as one having authority, and not as the scribes", "For he had healed many of their sick that day"]'::jsonb,2,'The narrator records that "the people were astonished at his doctrine: For he taught them as one having authority, and not as the scribes" (Matthew 7:28-29).','Read the two verses immediately following the parable.',null,null,'KJV',array['parables','Matthew','p6']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And it came to pass, when Jesus had ended these sayings, the people were astonished at his doctrine: For he taught them as one having authority, and not as the scribes.',null,'{"parable_title": "The Wise and Foolish Builders"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p2-1','parables',42,10,30,30,'Luke 10:30',1,'In the parable, along which road was the man travelling when he fell among thieves?',null,'["From Nazareth to Capernaum", "From Jerusalem to Jericho", "From Bethlehem to Jerusalem", "From Samaria to Galilee"]'::jsonb,1,'Jesus says, ''A certain man went down from Jerusalem to Jericho, and fell among thieves,'' who left him half dead (Luke 10:30).','He ''went down'' from the holy city toward a city near the Jordan.',null,null,'KJV',array['parables','Luke','p2']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Jesus answering said, A certain man went down from Jerusalem to Jericho, and fell among thieves, which stripped him of his raiment, and wounded him, and departed, leaving him half dead.',null,'{"parable_title": "The Good Samaritan"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p2-2','parables',42,10,35,35,'Luke 10:35',2,'When the Samaritan left the inn the next day, what did he give the host to care for the wounded man?',null,'["Two pence", "A talent of gold", "Ten pounds", "Thirty pieces of silver"]'::jsonb,0,'On the morrow the Samaritan ''took out two pence, and gave them to the host,'' promising to repay any further cost when he returned (Luke 10:35).','It was a small number of coins, with a promise to cover anything more.',null,null,'KJV',array['parables','Luke','p2']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And on the morrow when he departed, he took out two pence, and gave them to the host, and said unto him, Take care of him; and whatsoever thou spendest more, when I come again, I will repay thee.',null,'{"parable_title": "The Good Samaritan"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p2-3','parables',42,10,36,37,'Luke 10:36-37',2,'After the lawyer said the neighbour was ''He that shewed mercy on him,'' what did Jesus tell him?',null,'["Go and shew thyself to the priest", "Sell all that thou hast, and give to the poor", "Go thy way; thy faith hath made thee whole", "Go, and do thou likewise"]'::jsonb,3,'Jesus asked which of the three was neighbour to the wounded man, and when the lawyer answered ''He that shewed mercy on him,'' Jesus said, ''Go, and do thou likewise'' (Luke 10:36-37).','Jesus turned the lawyer''s answer into a personal instruction to imitate the Samaritan.',null,null,'KJV',array['parables','Luke','p2']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Which now of these three, thinkest thou, was neighbour unto him that fell among the thieves? And he said, He that shewed mercy on him. Then said Jesus unto him, Go, and do thou likewise.',null,'{"parable_title": "The Good Samaritan"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p2-4','parables',42,10,29,29,'Luke 10:29',3,'What question from the lawyer directly prompted Jesus to tell this parable?',null,'["Which is the great commandment in the law?", "Is it lawful to give tribute unto Caesar?", "And who is my neighbour?", "Lord, how oft shall my brother sin against me?"]'::jsonb,2,'The lawyer, ''willing to justify himself, said unto Jesus, And who is my neighbour?'' and Jesus answered with the story of the Samaritan (Luke 10:29).','The lawyer wanted to define one word from the commandment he had just quoted.',null,null,'KJV',array['parables','Luke','p2']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But he, willing to justify himself, said unto Jesus, And who is my neighbour?',null,'{"parable_title": "The Good Samaritan"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p5-1','parables',40,13,31,32,'Matthew 13:31-32',1,'In the first parable, where did the man sow the grain of mustard seed?',null,'["In a vineyard", "On stony ground", "In his field", "Among thorns"]'::jsonb,2,'Jesus says the grain of mustard seed was one ''which a man took, and sowed in his field'' (Matthew 13:31).','The man planted it on land that belonged to him.',null,null,'KJV',array['parables','Matthew','p5']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Another parable put he forth unto them, saying, The kingdom of heaven is like to a grain of mustard seed, which a man took, and sowed in his field: Which indeed is the least of all seeds: but when it is grown, it is the greatest among herbs, and becometh a tree, so that the birds of the air come and lodge in the branches thereof.',null,'{"parable_title": "The Mustard Seed and the Leaven"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p5-2','parables',40,13,33,33,'Matthew 13:33',2,'In the second parable, how many measures of meal did the woman hide the leaven in?',null,'["Two", "Three", "Seven", "Ten"]'::jsonb,1,'The woman ''hid in three measures of meal, till the whole was leavened'' (Matthew 13:33).','It is a small number, and the woman kept the leaven in the meal ''till the whole was leavened.''',null,null,'KJV',array['parables','Matthew','p5']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Another parable spake he unto them; The kingdom of heaven is like unto leaven, which a woman took, and hid in three measures of meal, till the whole was leavened.',null,'{"parable_title": "The Mustard Seed and the Leaven"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p5-3','parables',40,13,31,33,'Matthew 13:31-33',2,'Both parables begin with the same comparison. What does Jesus say is like a grain of mustard seed and like leaven?',null,'["The city of Nineveh", "The kingdom of heaven", "The temple in Jerusalem", "The law of Moses"]'::jsonb,1,'Jesus opens each parable with ''The kingdom of heaven is like'', first to a grain of mustard seed and then to leaven (Matthew 13:31, 33).','Listen to the opening words Jesus repeats in both parables.',null,null,'KJV',array['parables','Matthew','p5']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Another parable put he forth unto them, saying, The kingdom of heaven is like to a grain of mustard seed, which a man took, and sowed in his field: Which indeed is the least of all seeds: but when it is grown, it is the greatest among herbs, and becometh a tree, so that the birds of the air come and lodge in the branches thereof. Another parable spake he unto them; The kingdom of heaven is like unto leaven, which a woman took, and hid in three measures of meal, till the whole was leavened.',null,'{"parable_title": "The Mustard Seed and the Leaven"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p5-4','parables',40,13,34,35,'Matthew 13:34-35',3,'According to Matthew right after these parables, why did Jesus speak to the multitude in parables?',null,'["Because the multitude could not hear him from the ship", "That it might be fulfilled which was spoken by the prophet", "Because the disciples asked him to", "Because the Pharisees forbade him to teach openly"]'::jsonb,1,'Matthew says Jesus spoke in parables ''That it might be fulfilled which was spoken by the prophet, saying, I will open my mouth in parables'' (Matthew 13:35).','Matthew connects this teaching style to words written long before.',null,null,'KJV',array['parables','Matthew','p5']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'All these things spake Jesus unto the multitude in parables; and without a parable spake he not unto them: That it might be fulfilled which was spoken by the prophet, saying, I will open my mouth in parables; I will utter things which have been kept secret from the foundation of the world.',null,'{"parable_title": "The Mustard Seed and the Leaven"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p7-1','parables',42,12,16,17,'Luke 12:16-17',1,'When the rich man''s ground brought forth plentifully, what problem did he say he had?',null,'["He had no heir to receive his goods", "He had no buyers for his grain", "He had no room where to bestow his fruits", "He had no servants to gather the harvest"]'::jsonb,2,'The rich man thought within himself, ''What shall I do, because I have no room where to bestow my fruits?'' (Luke 12:17).','Think about storage space for an unusually large harvest.',null,null,'KJV',array['parables','Luke','p7']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he spake a parable unto them, saying, The ground of a certain rich man brought forth plentifully: And he thought within himself, saying, What shall I do, because I have no room where to bestow my fruits?',null,'{"parable_title": "The Rich Fool"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p7-2','parables',42,12,18,19,'Luke 12:18-19',1,'What did the rich man decide to do with his barns?',null,'["Open them to feed the poor", "Sell them to a neighbor", "Give them to his brother", "Pull them down and build greater ones"]'::jsonb,3,'He said, ''I will pull down my barns, and build greater; and there will I bestow all my fruits and my goods'' (Luke 12:18).','His solution was about making more space for himself.',null,null,'KJV',array['parables','Luke','p7']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he said, This will I do: I will pull down my barns, and build greater; and there will I bestow all my fruits and my goods. And I will say to my soul, Soul, thou hast much goods laid up for many years; take thine ease, eat, drink, and be merry.',null,'{"parable_title": "The Rich Fool"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p7-3','parables',42,12,20,21,'Luke 12:20-21',2,'After God called the man a fool, what conclusion did Jesus draw about such a person?',null,'["So is he that trusteth in his servants", "So is he that refuseth to share with his brother", "So is he that buildeth barns in the wrong season", "So is he that layeth up treasure for himself, and is not rich toward God"]'::jsonb,3,'God told him his soul would be required that night, and Jesus concluded, ''So is he that layeth up treasure for himself, and is not rich toward God'' (Luke 12:20-21).','Jesus contrasts treasure kept for oneself with being rich in another direction.',null,null,'KJV',array['parables','Luke','p7']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But God said unto him, Thou fool, this night thy soul shall be required of thee: then whose shall those things be, which thou hast provided? So is he that layeth up treasure for himself, and is not rich toward God.',null,'{"parable_title": "The Rich Fool"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p3-1','parables',42,15,4,4,'Luke 15:4',1,'When a man with an hundred sheep loses one, where does Jesus say he leaves the ninety and nine while he goes after the lost one?',null,'["In the wilderness", "With a hired servant in the city", "In the sheepfold at home", "In the temple courts"]'::jsonb,0,'Jesus asks what man would not "leave the ninety and nine in the wilderness, and go after that which is lost, until he find it" (Luke 15:4).','Think of the open country where the flock was grazing.',null,null,'KJV',array['parables','Luke','p3']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?',null,'{"parable_title": "The Lost Sheep and the Lost Coin"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p3-2','parables',42,15,8,8,'Luke 15:8',1,'What does the woman who loses one of her ten pieces of silver do to find it?',null,'["She asks her neighbours to search the street for her", "She borrows another piece of silver from a friend", "She lights a candle, sweeps the house, and seeks diligently", "She waits until morning and then looks in the market"]'::jsonb,2,'Jesus describes the woman who would "light a candle, and sweep the house, and seek diligently till she find it" (Luke 15:8).','She searches her own house carefully, needing light to see.',null,null,'KJV',array['parables','Luke','p3']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Either what woman having ten pieces of silver, if she lose one piece, doth not light a candle, and sweep the house, and seek diligently till she find it?',null,'{"parable_title": "The Lost Sheep and the Lost Coin"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p3-3','parables',42,15,10,10,'Luke 15:10',2,'After the parable of the lost coin, what point does Jesus himself state?',null,'["Silver laid up on earth is better kept than spent", "Whoever loses what is entrusted to him shall be cast out", "The righteous shall be rewarded for never going astray", "There is joy in the presence of the angels of God over one sinner that repenteth"]'::jsonb,3,'Jesus concludes, "Likewise, I say unto you, There is joy in the presence of the angels of God over one sinner that repenteth" (Luke 15:10).','The finding in the story led to rejoicing; Jesus applies that rejoicing to heaven.',null,null,'KJV',array['parables','Luke','p3']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Likewise, I say unto you, there is joy in the presence of the angels of God over one sinner that repenteth.',null,'{"parable_title": "The Lost Sheep and the Lost Coin"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p3-4','parables',42,15,1,3,'Luke 15:1-3',3,'What complaint from the Pharisees and scribes led Jesus to speak these parables?',null,'["\"This man receiveth sinners, and eateth with them\"", "\"This man teacheth that the temple shall be destroyed\"", "\"This man healeth on the sabbath day\"", "\"This man''s disciples wash not their hands\""]'::jsonb,0,'When publicans and sinners drew near to hear him, the Pharisees and scribes murmured that he received sinners and ate with them, and Jesus answered with this parable (Luke 15:1-3).','Look at who was gathering around Jesus at the start of the chapter.',null,null,'KJV',array['parables','Luke','p3']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then drew near unto him all the publicans and sinners for to hear him. And the Pharisees and scribes murmured, saying, This man receiveth sinners, and eateth with them. And he spake this parable unto them, saying,',null,'{"parable_title": "The Lost Sheep and the Lost Coin"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p4-1','parables',42,15,11,13,'Luke 15:11-13',1,'What did the younger son ask his father to give him?',null,'["A ring for his hand and shoes for his feet", "The fatted calf for a feast with his friends", "A field of his own to farm", "The portion of goods that fell to him"]'::jsonb,3,'The younger son said, "Father, give me the portion of goods that falleth to me," and soon took his journey into a far country (Luke 15:12-13).','He asked for his share before leaving home.',null,null,'KJV',array['parables','Luke','p4']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he said, A certain man had two sons: And the younger of them said to his father, Father, give me the portion of goods that falleth to me. And he divided unto them his living. And not many days after the younger son gathered all together, and took his journey into a far country, and there wasted his substance with riotous living.',null,'{"parable_title": "The Prodigal Son"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p4-2','parables',42,15,14,16,'Luke 15:14-16',2,'After a mighty famine arose, what work was the younger son sent into the fields to do?',null,'["To dress a vineyard", "To keep the citizen''s sheep", "To gather the harvest of wheat", "To feed swine"]'::jsonb,3,'A citizen of that country sent him into his fields to feed swine, and he would fain have filled his belly with the husks that the swine did eat (Luke 15:15-16).','He longed to eat what these animals ate.',null,null,'KJV',array['parables','Luke','p4']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And when he had spent all, there arose a mighty famine in that land; and he began to be in want. And he went and joined himself to a citizen of that country; and he sent him into his fields to feed swine. And he would fain have filled his belly with the husks that the swine did eat: and no man gave unto him.',null,'{"parable_title": "The Prodigal Son"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p4-3','parables',42,15,28,32,'Luke 15:28-32',2,'When the elder son refused to join the celebration, what reason did the father give for making merry?',null,'["The younger son had returned with great wealth", "His brother was dead and is alive again, was lost and is found", "The elder son had not served faithfully", "The servants had asked for a feast"]'::jsonb,1,'The father said, "It was meet that we should make merry, and be glad: for this thy brother was dead, and is alive again; and was lost, and is found" (Luke 15:32).','The father''s answer echoes what he said when the son first came home (Luke 15:24).',null,null,'KJV',array['parables','Luke','p4']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he was angry, and would not go in: therefore came his father out, and intreated him. And he answering said to his father, Lo, these many years do I serve thee, neither transgressed I at any time thy commandment: and yet thou never gavest me a kid, that I might make merry with my friends: But as soon as this thy son was come, which hath devoured thy living with harlots, thou hast killed for him the fatted calf. And he said unto him, Son, thou art ever with me, and all that I have is thine. It was meet that we should make merry, and be glad: for this thy brother was dead, and is alive again; and was lost, and is found.',null,'{"parable_title": "The Prodigal Son"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p4-4','parables',42,15,1,3,'Luke 15:1-3',3,'According to the opening of Luke 15, what prompted Jesus to tell the parables of this chapter?',null,'["His disciples asked him to teach them to pray", "A lawyer asked him, \"Who is my neighbour?\"", "Herod sought to kill him", "The Pharisees and scribes murmured that he received sinners and ate with them"]'::jsonb,3,'When publicans and sinners drew near to hear him, the Pharisees and scribes murmured, "This man receiveth sinners, and eateth with them," and Jesus spake this parable unto them (Luke 15:1-3).','Look at who was drawing near to Jesus and who objected.',null,null,'KJV',array['parables','Luke','p4']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then drew near unto him all the publicans and sinners for to hear him. And the Pharisees and scribes murmured, saying, This man receiveth sinners, and eateth with them. And he spake this parable unto them, saying,',null,'{"parable_title": "The Prodigal Son"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p8-1','parables',40,18,23,27,'Matthew 18:23-27',1,'When the king began to reckon with his servants, how much did the first servant brought to him owe?',null,'["An hundred pence", "Seven talents", "Thirty pieces of silver", "Ten thousand talents"]'::jsonb,3,'The servant brought to the king "owed him ten thousand talents," and the lord, moved with compassion, "forgave him the debt" (Matthew 18:24, 27).','It was an enormous sum, far greater than any servant could repay.',null,null,'KJV',array['parables','Matthew','p8']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Therefore is the kingdom of heaven likened unto a certain king, which would take account of his servants. And when he had begun to reckon, one was brought unto him, which owed him ten thousand talents. But forasmuch as he had not to pay, his lord commanded him to be sold, and his wife, and children, and all that he had, and payment to be made. The servant therefore fell down, and worshipped him, saying, Lord, have patience with me, and I will pay thee all. Then the lord of that servant was moved with compassion, and loosed him, and forgave him the debt.',null,'{"parable_title": "The Unforgiving Servant"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p8-2','parables',40,18,28,30,'Matthew 18:28-30',1,'What did the forgiven servant do to the fellowservant who owed him an hundred pence and begged for patience?',null,'["He brought him before the king to be judged", "He gave him more time and lent him more money", "He forgave him the debt as he himself had been forgiven", "He cast him into prison till he should pay the debt"]'::jsonb,3,'He took his fellowservant by the throat, and when begged for patience "he would not: but went and cast him into prison, till he should pay the debt" (Matthew 18:28-30).','Compare how he treated his fellowservant with how the king treated him; he showed no mercy.',null,null,'KJV',array['parables','Matthew','p8']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But the same servant went out, and found one of his fellowservants, which owed him an hundred pence: and he laid hands on him, and took him by the throat, saying, Pay me that thou owest. And his fellowservant fell down at his feet, and besought him, saying, Have patience with me, and I will pay thee all. And he would not: but went and cast him into prison, till he should pay the debt.',null,'{"parable_title": "The Unforgiving Servant"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p8-3','parables',40,18,32,35,'Matthew 18:32-35',2,'After the king delivered the wicked servant to the tormentors, what lesson did Jesus draw for his hearers?',null,'["Servants should never take their complaints to their lord", "The heavenly Father will do likewise if they from their hearts forgive not every one his brother", "Forgiveness is only required when the offender can pay back what is owed", "Debts must always be repaid in full before any forgiveness is given"]'::jsonb,1,'Jesus concluded, "So likewise shall my heavenly Father do also unto you, if ye from your hearts forgive not every one his brother their trespasses" (Matthew 18:35).','Look at the final verse, which begins "So likewise."',null,null,'KJV',array['parables','Matthew','p8']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then his lord, after that he had called him, said unto him, O thou wicked servant, I forgave thee all that debt, because thou desiredst me: Shouldest not thou also have had compassion on thy fellowservant, even as I had pity on thee? And his lord was wroth, and delivered him to the tormentors, till he should pay all that was due unto him. So likewise shall my heavenly Father do also unto you, if ye from your hearts forgive not every one his brother their trespasses.',null,'{"parable_title": "The Unforgiving Servant"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p8-4','parables',40,18,21,22,'Matthew 18:21-22',2,'Peter had suggested forgiving a brother "till seven times." How did Jesus answer him before telling this parable?',null,'["Until seventy times seven", "Only until the brother repays what he owes", "Until seven times, as Peter said", "Until three times, and then no more"]'::jsonb,0,'Jesus told Peter, "I say not unto thee, Until seven times: but, Until seventy times seven" (Matthew 18:22), and the parable follows as an illustration ("Therefore," Matthew 18:23).','Jesus explicitly rejected Peter''s number and gave a far larger one.',null,null,'KJV',array['parables','Matthew','p8']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then came Peter to him, and said, Lord, how oft shall my brother sin against me, and I forgive him? till seven times? Jesus saith unto him, I say not unto thee, Until seven times: but, Until seventy times seven.',null,'{"parable_title": "The Unforgiving Servant"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p9-1','parables',40,20,1,2,'Matthew 20:1-2',1,'What wage did the householder agree to pay the labourers he hired early in the morning?',null,'["A talent for the season", "A share of the vintage", "Two pence a day", "A penny a day"]'::jsonb,3,'The householder "agreed with the labourers for a penny a day" and sent them into his vineyard (Matthew 20:1-2).','It was a single coin for the day, agreed before any work began.',null,null,'KJV',array['parables','Matthew','p9']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'For the kingdom of heaven is like unto a man that is an householder, which went out early in the morning to hire labourers into his vineyard. And when he had agreed with the labourers for a penny a day, he sent them into his vineyard.',null,'{"parable_title": "The Labourers in the Vineyard"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p9-2','parables',40,20,6,7,'Matthew 20:6-7',2,'When the householder asked the men standing idle at the eleventh hour why they stood there all day, what did they answer?',null,'["No man had hired them", "They had finished work in another vineyard", "They were waiting for higher pay", "They had just arrived from another city"]'::jsonb,0,'They replied, "Because no man hath hired us," and he sent them into the vineyard too (Matthew 20:6-7).','Their idleness was not by their own choice.',null,null,'KJV',array['parables','Matthew','p9']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And about the eleventh hour he went out, and found others standing idle, and saith unto them, Why stand ye here all the day idle? They say unto him, Because no man hath hired us. He saith unto them, Go ye also into the vineyard; and whatsoever is right, that shall ye receive.',null,'{"parable_title": "The Labourers in the Vineyard"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p9-3','parables',40,20,13,16,'Matthew 20:13-16',2,'After the householder defends paying everyone the same, what saying concludes the parable?',null,'["The labourer is worthy of his hire", "To whom much is given, much shall be required", "He that humbleth himself shall be exalted", "So the last shall be first, and the first last"]'::jsonb,3,'The parable ends, "So the last shall be first, and the first last: for many be called, but few chosen" (Matthew 20:16).','Think about the order in which the workers were paid.',null,null,'KJV',array['parables','Matthew','p9']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But he answered one of them, and said, Friend, I do thee no wrong: didst not thou agree with me for a penny? Take that thine is, and go thy way: I will give unto this last, even as unto thee. Is it not lawful for me to do what I will with mine own? Is thine eye evil, because I am good? So the last shall be first, and the first last: for many be called, but few chosen.',null,'{"parable_title": "The Labourers in the Vineyard"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p10-1','parables',40,25,3,4,'Matthew 25:3-4',1,'In the parable, what did the foolish virgins fail to bring that the wise virgins brought?',null,'["Money to pay the porter", "Gifts for the bridegroom", "Oil for their lamps", "Wedding garments"]'::jsonb,2,'The foolish "took their lamps, and took no oil with them," but the wise "took oil in their vessels with their lamps" (Matthew 25:3-4).','Think about what a lamp needs in order to keep burning.',null,null,'KJV',array['parables','Matthew','p10']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'They that were foolish took their lamps, and took no oil with them: But the wise took oil in their vessels with their lamps.',null,'{"parable_title": "The Ten Virgins"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p10-2','parables',40,25,10,10,'Matthew 25:10',2,'What happened while the foolish virgins went away to buy what they lacked?',null,'["The bridegroom sent servants to search for them", "The bridegroom delayed his coming until morning so they could return", "The bridegroom came, the ready ones went in with him to the marriage, and the door was shut", "The wise virgins fell asleep and missed the bridegroom"]'::jsonb,2,'"While they went to buy, the bridegroom came; and they that were ready went in with him to the marriage: and the door was shut" (Matthew 25:10).','Consider who was able to go in, and what happened to the entrance afterward.',null,null,'KJV',array['parables','Matthew','p10']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And while they went to buy, the bridegroom came; and they that were ready went in with him to the marriage: and the door was shut.',null,'{"parable_title": "The Ten Virgins"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p10-3','parables',40,25,13,13,'Matthew 25:13',2,'What conclusion does Jesus Himself draw at the end of the parable?',null,'["The kingdom belongs only to those who buy their own oil at the market", "Sleep is sinful, so never rest while waiting", "Share everything you have, so that no one goes without", "Watch, because you know neither the day nor the hour when the Son of man comes"]'::jsonb,3,'Jesus closes with, "Watch therefore, for ye know neither the day nor the hour wherein the Son of man cometh" (Matthew 25:13). Note that in the story both wise and foolish slept (Matthew 25:5); the difference was being prepared.','Look at the final verse, which begins with a command.',null,null,'KJV',array['parables','Matthew','p10']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Watch therefore, for ye know neither the day nor the hour wherein the Son of man cometh.',null,'{"parable_title": "The Ten Virgins"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p10-4','parables',40,24,3,3,'Matthew 24:3',3,'This parable is part of Jesus'' answer to a question. Who asked it, and what did they ask?',null,'["The multitude by the sea, asking for a sign from heaven", "The Pharisees in the temple, asking whether it was lawful to give tribute to Caesar", "The disciples, privately on the mount of Olives, asking about the sign of His coming and the end of the world", "A lawyer, asking who his neighbour was"]'::jsonb,2,'"As he sat upon the mount of Olives, the disciples came unto him privately, saying, Tell us, when shall these things be? and what shall be the sign of thy coming, and of the end of the world?" (Matthew 24:3).','Look at the start of the previous chapter, where a small group approached Jesus away from the crowds.',null,null,'KJV',array['parables','Matthew','p10']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And as he sat upon the mount of Olives, the disciples came unto him privately, saying, Tell us, when shall these things be? and what shall be the sign of thy coming, and of the end of the world?',null,'{"parable_title": "The Ten Virgins"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p12-1','parables',42,18,11,12,'Luke 18:11-12',1,'In his prayer, how often did the Pharisee say that he fasted?',null,'["Every day", "Once a month", "Twice in the week", "Three times a year"]'::jsonb,2,'The Pharisee prayed, "I fast twice in the week, I give tithes of all that I possess" (Luke 18:12).','He mentioned his fasting alongside giving tithes of all he possessed.',null,null,'KJV',array['parables','Luke','p12']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'The Pharisee stood and prayed thus with himself, God, I thank thee, that I am not as other men are, extortioners, unjust, adulterers, or even as this publican. I fast twice in the week, I give tithes of all that I possess.',null,'{"parable_title": "The Pharisee and the Publican"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p12-2','parables',42,18,13,13,'Luke 18:13',1,'How did the publican behave as he prayed?',null,'["He stood near the altar and lifted his hands toward heaven", "He stood afar off, would not lift up his eyes, and smote upon his breast", "He offered a lamb and thanked God that he was not like other men", "He stood boldly and listed the good deeds he had done"]'::jsonb,1,'The publican, "standing afar off, would not lift up so much as his eyes unto heaven, but smote upon his breast, saying, God be merciful to me a sinner" (Luke 18:13).','Notice where he stood and what he did not dare to lift up.',null,null,'KJV',array['parables','Luke','p12']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the publican, standing afar off, would not lift up so much as his eyes unto heaven, but smote upon his breast, saying, God be merciful to me a sinner.',null,'{"parable_title": "The Pharisee and the Publican"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p12-3','parables',42,18,14,14,'Luke 18:14',2,'According to Jesus, which man went down to his house justified, and what principle did He give?',null,'["The publican, for every one that exalteth himself shall be abased, and he that humbleth himself shall be exalted", "The Pharisee, because he gave tithes of all that he possessed", "Neither man, because neither offered a sacrifice in the temple", "Both men equally, because both went up to the temple to pray"]'::jsonb,0,'Jesus said the publican "went down to his house justified rather than the other: for every one that exalteth himself shall be abased; and he that humbleth himself shall be exalted" (Luke 18:14).','Think about which man exalted himself and which humbled himself.',null,null,'KJV',array['parables','Luke','p12']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'I tell you, this man went down to his house justified rather than the other: for every one that exalteth himself shall be abased; and he that humbleth himself shall be exalted.',null,'{"parable_title": "The Pharisee and the Publican"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p12-4','parables',42,18,9,9,'Luke 18:9',2,'According to Luke, to whom did Jesus direct this parable?',null,'["To His disciples, after they asked Him to teach them to pray", "To publicans and sinners who drew near to hear Him", "To a lawyer who asked, \"Who is my neighbour?\"", "To certain which trusted in themselves that they were righteous, and despised others"]'::jsonb,3,'Luke states that Jesus "spake this parable unto certain which trusted in themselves that they were righteous, and despised others" (Luke 18:9).','The audience shared an attitude much like the Pharisee''s in the story.',null,null,'KJV',array['parables','Luke','p12']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he spake this parable unto certain which trusted in themselves that they were righteous, and despised others:',null,'{"parable_title": "The Pharisee and the Publican"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p11-1','parables',40,25,15,15,'Matthew 25:15',1,'On what basis did the man travelling into a far country decide how many talents to give each servant?',null,'["To every man according to his several ability", "According to which servant asked first", "Equally, so that no servant would complain", "According to how long each had served him"]'::jsonb,0,'The man gave five, two, and one talents "to every man according to his several ability" before he took his journey (Matthew 25:15).','Notice the phrase at the end of the sentence that lists the amounts of five, two, and one.',null,null,'KJV',array['parables','Matthew','p11']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And unto one he gave five talents, to another two, and to another one; to every man according to his several ability; and straightway took his journey.',null,'{"parable_title": "The Talents"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p11-2','parables',40,25,24,25,'Matthew 25:24-25',2,'When the lord returned, what reason did the servant who had received one talent give for hiding it in the earth?',null,'["He had been robbed and wanted to protect what was left", "He had lent it to a friend who had not repaid it", "He had forgotten about the talent until the lord returned", "He was afraid, saying he knew his lord was an hard man"]'::jsonb,3,'The servant said, "I knew thee that thou art an hard man... And I was afraid, and went and hid thy talent in the earth" (Matthew 25:24-25).','His answer describes both his view of his lord and his own feeling.',null,null,'KJV',array['parables','Matthew','p11']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then he which had received the one talent came and said, Lord, I knew thee that thou art an hard man, reaping where thou hast not sown, and gathering where thou hast not strawed: And I was afraid, and went and hid thy talent in the earth: lo, there thou hast that is thine.',null,'{"parable_title": "The Talents"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p11-3','parables',40,25,28,29,'Matthew 25:28-29',2,'After ordering the one talent to be given to the servant with ten talents, what principle does the lord state?',null,'["Whosoever exalteth himself shall be abased", "Unto every one that hath shall be given, and from him that hath not shall be taken away even that which he hath", "Many are called, but few are chosen", "The last shall be first, and the first last"]'::jsonb,1,'The lord explains the transfer with the words, "For unto every one that hath shall be given, and he shall have abundance: but from him that hath not shall be taken away even that which he hath" (Matthew 25:28-29).','The principle explains why the talent goes to the servant who already has the most.',null,null,'KJV',array['parables','Matthew','p11']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Take therefore the talent from him, and give it unto him which hath ten talents. For unto every one that hath shall be given, and he shall have abundance: but from him that hath not shall be taken away even that which he hath.',null,'{"parable_title": "The Talents"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('par-p11-4','parables',40,25,13,14,'Matthew 25:13-14',3,'The parable begins with "For the kingdom of heaven is as a man travelling into a far country." What command immediately before it does this "For" connect to?',null,'["\"Go ye therefore, and teach all nations\"", "\"Judge not, that ye be not judged\"", "\"Love your enemies, bless them that curse you\"", "\"Watch therefore, for ye know neither the day nor the hour wherein the Son of man cometh\""]'::jsonb,3,'Jesus'' command to watch, because no one knows the day or hour of the Son of man''s coming, leads directly into this parable of a lord who returns "after a long time" (Matthew 25:13-14, 19).','Look at the last verse of the parable of the ten virgins, just before this one begins.',null,null,'KJV',array['parables','Matthew','p11']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Watch therefore, for ye know neither the day nor the hour wherein the Son of man cometh. For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.',null,'{"parable_title": "The Talents"}'::jsonb) on conflict (id) do nothing;
