insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('hid-hero_jerusalem-temple','hidden',42,21,5,5,'Luke 21:5',2,'Find the temple adorned with goodly stones.',null,'["Area 1", "Area 2", "Area 3"]'::jsonb,0,'Some spake of the temple, how it was adorned with goodly stones and gifts (Luke 21:5).','Look for something mentioned in Luke 21:5.','hero_jerusalem','Ancient Jerusalem glowing gold at sunrise, seen from an olive grove with a traveller on the path.','KJV',array['hidden','hero_jerusalem','Luke']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And as some spake of the temple, how it was adorned with goodly stones and gifts, he said,',null,'{"boxes": [{"area": 0, "box": [53, 15, 13, 23]}, {"area": 1, "box": [34, 33, 66, 18]}, {"area": 2, "box": [0, 0, 35, 50]}]}'::jsonb) on conflict (id) do nothing;
