insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('hid-hero_jerusalem-olive','hidden',42,19,29,29,'Luke 19:29',2,'Find an olive tree on the Mount of Olives.',null,'["Area 1", "Area 2", "Area 3"]'::jsonb,2,'Jesus came nigh to Bethphage and Bethany, at the mount called the mount of Olives (Luke 19:29).','Look for something mentioned in Luke 19:29.','hero_jerusalem','Ancient Jerusalem glowing gold at sunrise, seen from an olive grove with a traveller on the path.','KJV',array['hidden','hero_jerusalem','Luke']::text[],'published','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And it came to pass, when he was come nigh to Bethphage and Bethany, at the mount called the mount of Olives, he sent two of his disciples,',null,'{"boxes": [{"area": 0, "box": [53, 15, 13, 23]}, {"area": 1, "box": [34, 33, 66, 18]}, {"area": 2, "box": [0, 0, 35, 50]}]}'::jsonb) on conflict (id) do nothing;
insert into public.adventures (id, title, summary, testament, image_id, sort_order, status, kind) values ('cases-ot','Old Testament Case Files','Nine investigations from Genesis to Daniel. Read each briefing, study the clues and answer from the text.','OT','joseph_coat',2,'published','mystery') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m3','cases-ot',1,'The Missing Household Gods','Genesis 31','Jacob has left Paddan-aram with his wives, children and flocks, and Laban has discovered that his household images are gone. Working only from Genesis 31, piece together when they vanished, how Laban gave chase, what was said, and where the missing gods really were.',null,array['mys-m3-1','mys-m3-2','mys-m3-3','mys-m3-4','mys-m3-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m2','cases-ot',2,'The Bloodstained Coat','Genesis 37','A grieving father in Canaan holds a torn, blood-soaked garment and believes his favoured son is dead. Your assignment is to trace the coat''s journey from Jacob''s tent to the wilderness pit and uncover what really happened, using only the testimony of Genesis 37.','joseph_coat',array['mys-m2-1','mys-m2-2','mys-m2-3','mys-m2-4','mys-m2-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m1','cases-ot',3,'The Silver Cup in the Sack','Genesis 44','Eleven brothers set out for home from Egypt with full sacks of corn, and a costly silver cup goes missing from the house of the ruler. Your case file is Genesis 44: trace how the cup got into the sack, how it was found, and how the matter was settled.','joseph_coat',array['mys-m1-1','mys-m1-2','mys-m1-3','mys-m1-4','mys-m1-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m4','cases-ot',4,'The Spies on the Roof','Joshua 2','Two strangers from the camp of Israel slipped into Jericho, and by nightfall the king''s men were knocking at a house on the town wall. Your case file is Joshua 2: follow the evidence in story order to learn who sent the men, where they vanished, and how they escaped the city.',null,array['mys-m4-1','mys-m4-2','mys-m4-3','mys-m4-4','mys-m4-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m5','cases-ot',5,'The Hidden Plunder','Joshua 7','After the stunning fall of Jericho, Israel suffers an unexpected and humiliating defeat at the small city of Ai. Something has gone terribly wrong in the camp, and the LORD reveals that a hidden wrong must be uncovered before Israel can stand again. Investigate the case of ''The Hidden Plunder'' in Joshua 7.',null,array['mys-m5-1','mys-m5-2','mys-m5-3','mys-m5-4','mys-m5-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m6','cases-ot',6,'The Secret of Samson''s Strength','Judges 16','Samson, the judge of Israel, has broken every bond his enemies placed on him, and no one knows why he cannot be overpowered. In Judges 16 a woman is offered a fortune to uncover his secret. Your task is to follow the evidence, stage by stage, to learn how the strongest man in Israel was finally brought low.',null,array['mys-m6-1','mys-m6-2','mys-m6-3','mys-m6-4','mys-m6-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m7','cases-ot',7,'Two Mothers and One Child','1 Kings 3','In 1 Kings 3, two women stand before King Solomon with one living baby and one dead one, and each claims the living child as her own. There were no other witnesses in the house, so the king must uncover the truth from their testimony alone. Gather the evidence and discover how the true mother was revealed.',null,array['mys-m7-1','mys-m7-2','mys-m7-3','mys-m7-4','mys-m7-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m12','cases-ot',8,'The Plot Against the Queen''s People','Esther 3, 4, 5, 7','In the court of king Ahasuerus at Shushan, a royal decree has gone out to destroy every Jew in the empire on a single appointed day, and the queen herself is secretly one of the people marked for death. Investigate Esther 3-7 to trace who set the plot in motion, how it was arranged, and how it was finally exposed.','esther_king',array['mys-m12-1','mys-m12-2','mys-m12-3','mys-m12-4','mys-m12-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m8','cases-ot',9,'The Writing on the Wall','Daniel 5','During a royal banquet in Babylon, a disembodied hand writes a message on the palace wall, and the king''s wise men cannot explain it. Your task is to work through the case file in Daniel 5 and find out what the writing meant and what happened that same night.',null,array['mys-m8-1','mys-m8-2','mys-m8-3','mys-m8-4','mys-m8-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventures (id, title, summary, testament, image_id, sort_order, status, kind) values ('cases-nt','New Testament Case Files','Three investigations from the Gospels and Acts.','NT','pentecost',3,'published','mystery') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m9','cases-nt',1,'The Betrayer at the Table','Matthew 26; John 13','On the night of the Passover, Jesus sat at the table with his twelve disciples and announced that one of them would betray him. Using the accounts in Matthew 26 and John 13, trace how the agreement was made, how the betrayer was revealed at the table, and what sign was finally used to deliver Jesus over.',null,array['mys-m9-1','mys-m9-2','mys-m9-3','mys-m9-4','mys-m9-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m10','cases-nt',2,'The Price of the Land','Acts 5','In the early Jerusalem church, a couple sold a possession and brought money to the apostles, but within hours both were dead and fear had spread through the whole church. Your case file covers Acts 5:1-11. Follow the money, the words spoken, and the timeline to learn what really happened with the price of the land.',null,array['mys-m10-1','mys-m10-2','mys-m10-3','mys-m10-4','mys-m10-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('case-m11','cases-nt',3,'The Prisoner Who Walked Free','Acts 12','Case file: The Prisoner Who Walked Free. Peter has been locked in a heavily guarded prison by King Herod, yet by morning he is gone and the soldiers cannot account for him. Investigate the evidence recorded in Acts 12 to discover how the prisoner walked free.',null,array['mys-m11-1','mys-m11-2','mys-m11-3','mys-m11-4','mys-m11-5']::text[],'published',null) on conflict (id) do nothing;
insert into public.adventures (id, title, summary, testament, image_id, sort_order, status, kind) values ('parables-matthew','Parables in Matthew','Read seven parables of Jesus from Matthew in the King James Version, then answer questions on each.','NT','sermon_mount',4,'published','parables') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p6','parables-matthew',1,'The Wise and Foolish Builders','Matthew 7:24-29','This parable is the closing illustration of the Sermon on the Mount, which Jesus taught after he "went up into a mountain" and his disciples came to him while the multitudes gathered (Matthew 5:1-2). When he finished, "the people were astonished at his doctrine" (Matthew 7:28).','sermon_mount',array['par-p6-1','par-p6-2','par-p6-3','par-p6-4']::text[],'published','[{"ref": "Matthew 7:24-29", "text": "Therefore whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man, which built his house upon a rock: And the rain descended, and the floods came, and the winds blew, and beat upon that house; and it fell not: for it was founded upon a rock. And every one that heareth these sayings of mine, and doeth them not, shall be likened unto a foolish man, which built his house upon the sand: And the rain descended, and the floods came, and the winds blew, and beat upon that house; and it fell: and great was the fall of it. And it came to pass, when Jesus had ended these sayings, the people were astonished at his doctrine: For he taught them as one having authority, and not as the scribes."}]'::jsonb) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p1','parables-matthew',2,'The Sower','Matthew 13:1-9, 18-23','Jesus went out of the house, sat by the sea side, and because great multitudes gathered, he entered a ship and taught the people on the shore in parables (Matthew 13:1-3). He later explained the parable of the sower to his disciples (Matthew 13:18).',null,array['par-p1-1','par-p1-2','par-p1-3','par-p1-4']::text[],'published','[{"ref": "Matthew 13:1-9", "text": "The same day went Jesus out of the house, and sat by the sea side. And great multitudes were gathered together unto him, so that he went into a ship, and sat; and the whole multitude stood on the shore. And he spake many things unto them in parables, saying, Behold, a sower went forth to sow; And when he sowed, some seeds fell by the way side, and the fowls came and devoured them up: Some fell upon stony places, where they had not much earth: and forthwith they sprung up, because they had no deepness of earth: And when the sun was up, they were scorched; and because they had no root, they withered away. And some fell among thorns; and the thorns sprung up, and choked them: But other fell into good ground, and brought forth fruit, some an hundredfold, some sixtyfold, some thirtyfold. Who hath ears to hear, let him hear."}, {"ref": "Matthew 13:18-23", "text": "Hear ye therefore the parable of the sower. When any one heareth the word of the kingdom, and understandeth it not, then cometh the wicked one, and catcheth away that which was sown in his heart. This is he which received seed by the way side. But he that received the seed into stony places, the same is he that heareth the word, and anon with joy receiveth it; Yet hath he not root in himself, but dureth for a while: for when tribulation or persecution ariseth because of the word, by and by he is offended. He also that received seed among the thorns is he that heareth the word; and the care of this world, and the deceitfulness of riches, choke the word, and he becometh unfruitful. But he that received seed into the good ground is he that heareth the word, and understandeth it; which also beareth fruit, and bringeth forth, some an hundredfold, some sixty, some thirty."}]'::jsonb) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p5','parables-matthew',3,'The Mustard Seed and the Leaven','Matthew 13:31-35','Sitting in a ship by the sea, Jesus taught great multitudes gathered on the shore, speaking ''many things unto them in parables'' (Matthew 13:1-3). These two short parables were spoken to that multitude (Matthew 13:34).',null,array['par-p5-1','par-p5-2','par-p5-3','par-p5-4']::text[],'published','[{"ref": "Matthew 13:31-35", "text": "Another parable put he forth unto them, saying, The kingdom of heaven is like to a grain of mustard seed, which a man took, and sowed in his field: Which indeed is the least of all seeds: but when it is grown, it is the greatest among herbs, and becometh a tree, so that the birds of the air come and lodge in the branches thereof. Another parable spake he unto them; The kingdom of heaven is like unto leaven, which a woman took, and hid in three measures of meal, till the whole was leavened. All these things spake Jesus unto the multitude in parables; and without a parable spake he not unto them: That it might be fulfilled which was spoken by the prophet, saying, I will open my mouth in parables; I will utter things which have been kept secret from the foundation of the world."}]'::jsonb) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p8','parables-matthew',4,'The Unforgiving Servant','Matthew 18:21-35','Peter came to Jesus and asked, "Lord, how oft shall my brother sin against me, and I forgive him?" (Matthew 18:21). Jesus answered him, then told this parable of a king settling accounts with his servants (Matthew 18:22-23).',null,array['par-p8-1','par-p8-2','par-p8-3','par-p8-4']::text[],'published','[{"ref": "Matthew 18:21-35", "text": "Then came Peter to him, and said, Lord, how oft shall my brother sin against me, and I forgive him? till seven times? Jesus saith unto him, I say not unto thee, Until seven times: but, Until seventy times seven. Therefore is the kingdom of heaven likened unto a certain king, which would take account of his servants. And when he had begun to reckon, one was brought unto him, which owed him ten thousand talents. But forasmuch as he had not to pay, his lord commanded him to be sold, and his wife, and children, and all that he had, and payment to be made. The servant therefore fell down, and worshipped him, saying, Lord, have patience with me, and I will pay thee all. Then the lord of that servant was moved with compassion, and loosed him, and forgave him the debt. But the same servant went out, and found one of his fellowservants, which owed him an hundred pence: and he laid hands on him, and took him by the throat, saying, Pay me that thou owest. And his fellowservant fell down at his feet, and besought him, saying, Have patience with me, and I will pay thee all. And he would not: but went and cast him into prison, till he should pay the debt. So when his fellowservants saw what was done, they were very sorry, and came and told unto their lord all that was done. Then his lord, after that he had called him, said unto him, O thou wicked servant, I forgave thee all that debt, because thou desiredst me: Shouldest not thou also have had compassion on thy fellowservant, even as I had pity on thee? And his lord was wroth, and delivered him to the tormentors, till he should pay all that was due unto him. So likewise shall my heavenly Father do also unto you, if ye from your hearts forgive not every one his brother their trespasses."}]'::jsonb) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p9','parables-matthew',5,'The Labourers in the Vineyard','Matthew 20:1-16','Jesus told this parable to His disciples right after Peter asked, "Behold, we have forsaken all, and followed thee; what shall we have therefore?" and Jesus answered that "many that are first shall be last; and the last shall be first" (Matthew 19:27-30). The parable opens with "For the kingdom of heaven is like unto a man that is an householder" (Matthew 20:1), illustrating that saying.',null,array['par-p9-1','par-p9-2','par-p9-3']::text[],'published','[{"ref": "Matthew 20:1-8", "text": "For the kingdom of heaven is like unto a man that is an householder, which went out early in the morning to hire labourers into his vineyard. And when he had agreed with the labourers for a penny a day, he sent them into his vineyard. And he went out about the third hour, and saw others standing idle in the marketplace, And said unto them; Go ye also into the vineyard, and whatsoever is right I will give you. And they went their way. Again he went out about the sixth and ninth hour, and did likewise. And about the eleventh hour he went out, and found others standing idle, and saith unto them, Why stand ye here all the day idle? They say unto him, Because no man hath hired us. He saith unto them, Go ye also into the vineyard; and whatsoever is right, that shall ye receive. So when even was come, the lord of the vineyard saith unto his steward, Call the labourers, and give them their hire, beginning from the last unto the first."}, {"ref": "Matthew 20:9-16", "text": "And when they came that were hired about the eleventh hour, they received every man a penny. But when the first came, they supposed that they should have received more; and they likewise received every man a penny. And when they had received it, they murmured against the goodman of the house, Saying, These last have wrought but one hour, and thou hast made them equal unto us, which have borne the burden and heat of the day. But he answered one of them, and said, Friend, I do thee no wrong: didst not thou agree with me for a penny? Take that thine is, and go thy way: I will give unto this last, even as unto thee. Is it not lawful for me to do what I will with mine own? Is thine eye evil, because I am good? So the last shall be first, and the first last: for many be called, but few chosen."}]'::jsonb) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p10','parables-matthew',6,'The Ten Virgins','Matthew 25:1-13','Jesus told this parable to His disciples, who had come to Him privately on the mount of Olives asking, "what shall be the sign of thy coming, and of the end of the world?" (Matthew 24:3). It continues His answer about being ready for His coming, since "of that day and hour knoweth no man" (Matthew 24:36).',null,array['par-p10-1','par-p10-2','par-p10-3','par-p10-4']::text[],'published','[{"ref": "Matthew 25:1-13", "text": "Then shall the kingdom of heaven be likened unto ten virgins, which took their lamps, and went forth to meet the bridegroom. And five of them were wise, and five were foolish. They that were foolish took their lamps, and took no oil with them: But the wise took oil in their vessels with their lamps. While the bridegroom tarried, they all slumbered and slept. And at midnight there was a cry made, Behold, the bridegroom cometh; go ye out to meet him. Then all those virgins arose, and trimmed their lamps. And the foolish said unto the wise, Give us of your oil; for our lamps are gone out. But the wise answered, saying, Not so; lest there be not enough for us and you: but go ye rather to them that sell, and buy for yourselves. And while they went to buy, the bridegroom came; and they that were ready went in with him to the marriage: and the door was shut. Afterward came also the other virgins, saying, Lord, Lord, open to us. But he answered and said, Verily I say unto you, I know you not. Watch therefore, for ye know neither the day nor the hour wherein the Son of man cometh."}]'::jsonb) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p11','parables-matthew',7,'The Talents','Matthew 25:14-30','Sitting on the Mount of Olives, Jesus was answering His disciples'' private question about the sign of His coming and of the end of the world (Matthew 24:3). He told this parable right after warning, "Watch therefore, for ye know neither the day nor the hour wherein the Son of man cometh" (Matthew 25:13).',null,array['par-p11-1','par-p11-2','par-p11-3','par-p11-4']::text[],'published','[{"ref": "Matthew 25:14-22", "text": "For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods. And unto one he gave five talents, to another two, and to another one; to every man according to his several ability; and straightway took his journey. Then he that had received the five talents went and traded with the same, and made them other five talents. And likewise he that had received two, he also gained other two. But he that had received one went and digged in the earth, and hid his lord’s money. After a long time the lord of those servants cometh, and reckoneth with them. And so he that had received five talents came and brought other five talents, saying, Lord, thou deliveredst unto me five talents: behold, I have gained beside them five talents more. His lord said unto him, Well done, thou good and faithful servant: thou hast been faithful over a few things, I will make thee ruler over many things: enter thou into the joy of thy lord. He also that had received two talents came and said, Lord, thou deliveredst unto me two talents: behold, I have gained two other talents beside them."}, {"ref": "Matthew 25:23-30", "text": "His lord said unto him, Well done, good and faithful servant; thou hast been faithful over a few things, I will make thee ruler over many things: enter thou into the joy of thy lord. Then he which had received the one talent came and said, Lord, I knew thee that thou art an hard man, reaping where thou hast not sown, and gathering where thou hast not strawed: And I was afraid, and went and hid thy talent in the earth: lo, there thou hast that is thine. His lord answered and said unto him, Thou wicked and slothful servant, thou knewest that I reap where I sowed not, and gather where I have not strawed: Thou oughtest therefore to have put my money to the exchangers, and then at my coming I should have received mine own with usury. Take therefore the talent from him, and give it unto him which hath ten talents. For unto every one that hath shall be given, and he shall have abundance: but from him that hath not shall be taken away even that which he hath. And cast ye the unprofitable servant into outer darkness: there shall be weeping and gnashing of teeth."}]'::jsonb) on conflict (id) do nothing;
insert into public.adventures (id, title, summary, testament, image_id, sort_order, status, kind) values ('parables-luke','Parables in Luke','Read five parables of Jesus from Luke in the King James Version, then answer questions on each.','NT','good_samaritan',5,'published','parables') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p2','parables-luke',1,'The Good Samaritan','Luke 10:25-37','A certain lawyer stood up and tempted Jesus, asking, ''Master, what shall I do to inherit eternal life?'' (Luke 10:25). After agreeing that the law commands love for God and neighbour, the lawyer, ''willing to justify himself,'' asked, ''And who is my neighbour?'' Jesus answered with this parable (Luke 10:29-30).','good_samaritan',array['par-p2-1','par-p2-2','par-p2-3','par-p2-4']::text[],'published','[{"ref": "Luke 10:25-37", "text": "And, behold, a certain lawyer stood up, and tempted him, saying, Master, what shall I do to inherit eternal life? He said unto him, What is written in the law? how readest thou? And he answering said, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy strength, and with all thy mind; and thy neighbour as thyself. And he said unto him, Thou hast answered right: this do, and thou shalt live. But he, willing to justify himself, said unto Jesus, And who is my neighbour? And Jesus answering said, A certain man went down from Jerusalem to Jericho, and fell among thieves, which stripped him of his raiment, and wounded him, and departed, leaving him half dead. And by chance there came down a certain priest that way: and when he saw him, he passed by on the other side. And likewise a Levite, when he was at the place, came and looked on him, and passed by on the other side. But a certain Samaritan, as he journeyed, came where he was: and when he saw him, he had compassion on him, And went to him, and bound up his wounds, pouring in oil and wine, and set him on his own beast, and brought him to an inn, and took care of him. And on the morrow when he departed, he took out two pence, and gave them to the host, and said unto him, Take care of him; and whatsoever thou spendest more, when I come again, I will repay thee. Which now of these three, thinkest thou, was neighbour unto him that fell among the thieves? And he said, He that shewed mercy on him. Then said Jesus unto him, Go, and do thou likewise."}]'::jsonb) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p7','parables-luke',2,'The Rich Fool','Luke 12:13-21','When a man in the crowd asked Jesus to make his brother divide the inheritance with him, Jesus refused to act as judge and warned them to beware of covetousness, then told this parable (Luke 12:13-15).',null,array['par-p7-1','par-p7-2','par-p7-3']::text[],'published','[{"ref": "Luke 12:13-21", "text": "And one of the company said unto him, Master, speak to my brother, that he divide the inheritance with me. And he said unto him, Man, who made me a judge or a divider over you? And he said unto them, Take heed, and beware of covetousness: for a man’s life consisteth not in the abundance of the things which he possesseth. And he spake a parable unto them, saying, The ground of a certain rich man brought forth plentifully: And he thought within himself, saying, What shall I do, because I have no room where to bestow my fruits? And he said, This will I do: I will pull down my barns, and build greater; and there will I bestow all my fruits and my goods. And I will say to my soul, Soul, thou hast much goods laid up for many years; take thine ease, eat, drink, and be merry. But God said unto him, Thou fool, this night thy soul shall be required of thee: then whose shall those things be, which thou hast provided? So is he that layeth up treasure for himself, and is not rich toward God."}]'::jsonb) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p3','parables-luke',3,'The Lost Sheep and the Lost Coin','Luke 15:1-10','Publicans and sinners drew near to hear Jesus, and the Pharisees and scribes murmured, "This man receiveth sinners, and eateth with them"; in answer, Jesus spake this parable unto them (Luke 15:1-3).',null,array['par-p3-1','par-p3-2','par-p3-3','par-p3-4']::text[],'published','[{"ref": "Luke 15:1-10", "text": "Then drew near unto him all the publicans and sinners for to hear him. And the Pharisees and scribes murmured, saying, This man receiveth sinners, and eateth with them. And he spake this parable unto them, saying, What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it? And when he hath found it, he layeth it on his shoulders, rejoicing. And when he cometh home, he calleth together his friends and neighbours, saying unto them, Rejoice with me; for I have found my sheep which was lost. I say unto you, that likewise joy shall be in heaven over one sinner that repenteth, more than over ninety and nine just persons, which need no repentance. Either what woman having ten pieces of silver, if she lose one piece, doth not light a candle, and sweep the house, and seek diligently till she find it? And when she hath found it, she calleth her friends and her neighbours together, saying, Rejoice with me; for I have found the piece which I had lost. Likewise, I say unto you, there is joy in the presence of the angels of God over one sinner that repenteth."}]'::jsonb) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p4','parables-luke',4,'The Prodigal Son','Luke 15:11-32','Publicans and sinners drew near to hear Jesus, and the Pharisees and scribes murmured, saying, "This man receiveth sinners, and eateth with them" (Luke 15:1-2). In answer, Jesus told a series of parables about the lost being found, ending with this story of a father and his two sons (Luke 15:3, 11).','prodigal_son',array['par-p4-1','par-p4-2','par-p4-3','par-p4-4']::text[],'published','[{"ref": "Luke 15:11-24", "text": "And he said, A certain man had two sons: And the younger of them said to his father, Father, give me the portion of goods that falleth to me. And he divided unto them his living. And not many days after the younger son gathered all together, and took his journey into a far country, and there wasted his substance with riotous living. And when he had spent all, there arose a mighty famine in that land; and he began to be in want. And he went and joined himself to a citizen of that country; and he sent him into his fields to feed swine. And he would fain have filled his belly with the husks that the swine did eat: and no man gave unto him. And when he came to himself, he said, How many hired servants of my father’s have bread enough and to spare, and I perish with hunger! I will arise and go to my father, and will say unto him, Father, I have sinned against heaven, and before thee, And am no more worthy to be called thy son: make me as one of thy hired servants. And he arose, and came to his father. But when he was yet a great way off, his father saw him, and had compassion, and ran, and fell on his neck, and kissed him. And the son said unto him, Father, I have sinned against heaven, and in thy sight, and am no more worthy to be called thy son. But the father said to his servants, Bring forth the best robe, and put it on him; and put a ring on his hand, and shoes on his feet: And bring hither the fatted calf, and kill it; and let us eat, and be merry: For this my son was dead, and is alive again; he was lost, and is found. And they began to be merry."}, {"ref": "Luke 15:25-32", "text": "Now his elder son was in the field: and as he came and drew nigh to the house, he heard musick and dancing. And he called one of the servants, and asked what these things meant. And he said unto him, Thy brother is come; and thy father hath killed the fatted calf, because he hath received him safe and sound. And he was angry, and would not go in: therefore came his father out, and intreated him. And he answering said to his father, Lo, these many years do I serve thee, neither transgressed I at any time thy commandment: and yet thou never gavest me a kid, that I might make merry with my friends: But as soon as this thy son was come, which hath devoured thy living with harlots, thou hast killed for him the fatted calf. And he said unto him, Son, thou art ever with me, and all that I have is thine. It was meet that we should make merry, and be glad: for this thy brother was dead, and is alive again; and was lost, and is found."}]'::jsonb) on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status, reading) values ('parable-p12','parables-luke',5,'The Pharisee and the Publican','Luke 18:9-14','Luke records that Jesus spoke this parable "unto certain which trusted in themselves that they were righteous, and despised others" (Luke 18:9). It contrasts the prayers of two men who went up to the temple to pray (Luke 18:10).',null,array['par-p12-1','par-p12-2','par-p12-3','par-p12-4']::text[],'published','[{"ref": "Luke 18:9-14", "text": "And he spake this parable unto certain which trusted in themselves that they were righteous, and despised others: Two men went up into the temple to pray; the one a Pharisee, and the other a publican. The Pharisee stood and prayed thus with himself, God, I thank thee, that I am not as other men are, extortioners, unjust, adulterers, or even as this publican. I fast twice in the week, I give tithes of all that I possess. And the publican, standing afar off, would not lift up so much as his eyes unto heaven, but smote upon his breast, saying, God be merciful to me a sinner. I tell you, this man went down to his house justified rather than the other: for every one that exalteth himself shall be abased; and he that humbleth himself shall be exalted."}]'::jsonb) on conflict (id) do nothing;
